/* Mi Plato Inteligente — recetas de los platos del catálogo (platos.js), en español e inglés.
   Cada receta usa solo los ingredientes que el nombre del plato y sus etiquetas ya declaran, para que sea segura con el mismo filtro de restricciones.
   Cantidades para el número de porciones indicado en «porciones». Minutos: ver platos.js. */
const RECETAS = {"albondigas-res-tomate":{"es":{"ingredientes":["300 g de carne molida de res","1 huevo","1/4 de taza de pan molido","2 dientes de ajo picados","2 cdas de perejil picado","1 taza de tomate triturado","1/2 cebolla picada","1 cda de aceite de oliva","sal al gusto"],"pasos":["Mezcle la carne con el huevo, el pan molido, la mitad del ajo, el perejil y sal; forme bolitas.","Dore las albóndigas en una sartén con aceite y apártelas.","En la misma sartén sofría la cebolla y el resto del ajo; agregue el tomate.","Regrese las albóndigas y cocine tapadas 20 minutos a fuego bajo."],"titulo":"Albóndigas de res en salsa de tomate","porciones":2},"en":{"ingredientes":["300 g ground beef","1 egg","1/4 cup breadcrumbs","2 garlic cloves, minced","2 tbsp chopped parsley","1 cup crushed tomatoes","1/2 onion, chopped","1 tbsp olive oil","salt to taste"],"pasos":["Mix the beef with the egg, breadcrumbs, half the garlic, parsley and salt; shape into balls.","Brown the meatballs in a pan with oil and set aside.","In the same pan sauté the onion and remaining garlic; add the tomatoes.","Return the meatballs and simmer covered for 20 minutes."],"titulo":"Beef meatballs in tomato sauce","porciones":2}},"americano-bbq-ribs":{"es":{"ingredientes":["700 g de costillas de cerdo","1/2 taza de salsa de tomate","2 cdas de azúcar moreno","2 cdas de vinagre de manzana","1 cdta de paprika","2 dientes de ajo picados","1 cdta de sal"],"pasos":["Caliente el horno a 150 °C. Sazone las costillas con sal, paprika y ajo.","Mezcle la salsa de tomate, el azúcar moreno y el vinagre.","Cubra las costillas con la salsa, tápelas con papel de aluminio y hornee 2 horas.","Destape, unte más salsa y hornee 20 minutos más hasta que se doren."],"titulo":"Costillas de cerdo con salsa BBQ casera","porciones":2},"en":{"ingredientes":["700 g pork ribs","1/2 cup tomato sauce","2 tbsp brown sugar","2 tbsp apple cider vinegar","1 tsp paprika","2 garlic cloves, minced","1 tsp salt"],"pasos":["Heat the oven to 150 °C. Season the ribs with salt, paprika and garlic.","Mix the tomato sauce, brown sugar and vinegar.","Brush the ribs with the sauce, cover with foil and bake for 2 hours.","Uncover, brush with more sauce and bake 20 more minutes until browned."],"titulo":"Pork ribs with homemade BBQ sauce","porciones":2}},"americano-chicken-pot-pie":{"es":{"ingredientes":["300 g de pechuga de pollo en cubos","2 papas medianas en cubos","1 zanahoria en cubos","1/2 taza de arvejas","1/2 cebolla picada","3 cdas de harina de trigo","1 taza de leche","1 taza de caldo de pollo","1 cda de mantequilla","1 lámina de masa para pastel","sal y pimienta al gusto"],"pasos":["Caliente el horno a 200 °C. Derrita la mantequilla y sofría la cebolla y el pollo 5 minutos.","Agregue la harina, luego el caldo y la leche poco a poco, revolviendo hasta que espese.","Incorpore la papa, la zanahoria y las arvejas y cocine 10 minutos; sazone.","Pase la mezcla a un molde, cubra con la masa y hornee 25 minutos hasta que dore."],"titulo":"Pastel de pollo con vegetales","porciones":4},"en":{"ingredientes":["300 g chicken breast, cubed","2 medium potatoes, cubed","1 carrot, cubed","1/2 cup peas","1/2 onion, chopped","3 tbsp wheat flour","1 cup milk","1 cup chicken broth","1 tbsp butter","1 sheet pie dough","salt and pepper to taste"],"pasos":["Heat the oven to 200 °C. Melt the butter and sauté the onion and chicken for 5 minutes.","Stir in the flour, then add the broth and milk gradually, stirring until thickened.","Add the potato, carrot and peas and cook for 10 minutes; season.","Transfer to a baking dish, cover with the dough and bake 25 minutes until golden."],"titulo":"Chicken pot pie with vegetables","porciones":4}},"americano-mac-cheese":{"es":{"ingredientes":["200 g de macarrones","1 1/2 tazas de queso cheddar rallado","1 taza de leche","1 cda de mantequilla","1 cda de harina de trigo","sal y pimienta al gusto"],"pasos":["Cocine los macarrones en agua con sal según el paquete y escúrralos.","Derrita la mantequilla, agregue la harina y revuelva 1 minuto.","Vierta la leche poco a poco y cocine hasta que espese; agregue el queso hasta que se derrita.","Mezcle con los macarrones y sazone."],"titulo":"Macarrones con queso","porciones":2},"en":{"ingredientes":["200 g macaroni","1 1/2 cups grated cheddar cheese","1 cup milk","1 tbsp butter","1 tbsp wheat flour","salt and pepper to taste"],"pasos":["Cook the macaroni in salted water as directed and drain.","Melt the butter, add the flour and stir for 1 minute.","Pour in the milk gradually and cook until thick; add the cheese until melted.","Combine with the macaroni and season."],"titulo":"Macaroni and cheese","porciones":2}},"americano-meatloaf":{"es":{"ingredientes":["500 g de carne molida de res","1 huevo","1/2 taza de pan molido","1/2 cebolla picada","2 dientes de ajo picados","1/4 de taza de salsa de tomate","1 cdta de sal"],"pasos":["Caliente el horno a 180 °C. Mezcle la carne con el huevo, el pan molido, la cebolla, el ajo y la sal.","Forme un pan y colóquelo en un molde.","Cubra con la salsa de tomate y hornee 60 minutos.","Deje reposar 10 minutos antes de cortar."],"titulo":"Pastel de carne al horno","porciones":4},"en":{"ingredientes":["500 g ground beef","1 egg","1/2 cup breadcrumbs","1/2 onion, chopped","2 garlic cloves, minced","1/4 cup tomato sauce","1 tsp salt"],"pasos":["Heat the oven to 180 °C. Mix the beef with the egg, breadcrumbs, onion, garlic and salt.","Shape into a loaf and place in a baking dish.","Top with the tomato sauce and bake for 60 minutes.","Rest 10 minutes before slicing."],"titulo":"Baked meatloaf","porciones":4}},"arroz-coco-frijoles":{"es":{"ingredientes":["1 taza de arroz","1 taza de leche de coco","1 taza de agua","1 taza de frijoles rojos cocidos","2 dientes de ajo picados","1/2 cebolla picada","1 ramita de tomillo","1/2 cdta de sal"],"pasos":["Sofría la cebolla y el ajo en una olla con un poco de aceite.","Agregue el arroz, la leche de coco, el agua, el tomillo y la sal; hierva.","Baje el fuego, tape y cocine 20 minutos.","Incorpore los frijoles, tape 5 minutos y sirva."],"titulo":"Arroz con coco y frijoles","porciones":2},"en":{"ingredientes":["1 cup rice","1 cup coconut milk","1 cup water","1 cup cooked red beans","2 garlic cloves, minced","1/2 onion, chopped","1 sprig of thyme","1/2 tsp salt"],"pasos":["Sauté the onion and garlic in a pot with a little oil.","Add the rice, coconut milk, water, thyme and salt; bring to a boil.","Reduce the heat, cover and cook for 20 minutes.","Stir in the beans, cover for 5 minutes and serve."],"titulo":"Coconut rice with beans","porciones":2}},"arroz-con-pollo":{"es":{"ingredientes":["2 tazas de arroz","400 g de pollo en trozos","1 zanahoria en cubos","1/2 taza de arvejas","1 chile dulce picado","1/2 cebolla picada","3 tazas de caldo de pollo","2 cdas de culantro picado","2 cdas de aceite","sal al gusto"],"pasos":["Dore el pollo en aceite con sal y apártelo.","Sofría la cebolla, el chile dulce y la zanahoria; agregue el arroz y revuelva 2 minutos.","Agregue el caldo, el pollo y las arvejas; hierva, tape y cocine a fuego bajo 25 minutos.","Adorne con el culantro y sirva."],"titulo":"Arroz con pollo","porciones":4},"en":{"ingredientes":["2 cups rice","400 g chicken pieces","1 carrot, diced","1/2 cup peas","1 sweet pepper, chopped","1/2 onion, chopped","3 cups chicken broth","2 tbsp chopped culantro","2 tbsp oil","salt to taste"],"pasos":["Brown the chicken in oil with salt and set aside.","Sauté the onion, sweet pepper and carrot; add the rice and stir for 2 minutes.","Add the broth, chicken and peas; bring to a boil, cover and simmer for 25 minutes.","Garnish with culantro and serve."],"titulo":"Chicken and rice","porciones":4}},"arroz-integral-hierbas":{"es":{"ingredientes":["1 taza de arroz integral","2 tazas de agua","1 cdta de comino","1/2 cdta de cúrcuma","3 cdas de cilantro picado","1 limón","1 cda de aceite","sal al gusto"],"pasos":["Caliente el aceite y tueste el comino y la cúrcuma 30 segundos.","Agregue el arroz y revuelva 1 minuto; añada el agua y la sal.","Tape y cocine a fuego bajo 40 minutos.","Mezcle con el cilantro y el jugo de limón."],"titulo":"Arroz integral con hierbas y especias","porciones":2},"en":{"ingredientes":["1 cup brown rice","2 cups water","1 tsp cumin","1/2 tsp turmeric","3 tbsp chopped cilantro","1 lemon","1 tbsp oil","salt to taste"],"pasos":["Heat the oil and toast the cumin and turmeric for 30 seconds.","Add the rice and stir for 1 minute; add the water and salt.","Cover and simmer for 40 minutes.","Fold in the cilantro and lemon juice."],"titulo":"Brown rice with herbs and spices","porciones":2}},"arroz-integral-hongos":{"es":{"ingredientes":["1 taza de arroz integral","250 g de hongos en láminas","2 dientes de ajo picados","1/2 cebolla picada","2 tazas de caldo de verduras","2 cdas de perejil picado","1 cda de aceite de oliva","sal y pimienta al gusto"],"pasos":["Sofría la cebolla y el ajo en aceite; agregue los hongos y cocine hasta que suelten el agua.","Agregue el arroz y el caldo; hierva.","Tape y cocine a fuego bajo 40 minutos.","Sazone y adorne con perejil."],"titulo":"Arroz integral con hongos","porciones":2},"en":{"ingredientes":["1 cup brown rice","250 g sliced mushrooms","2 garlic cloves, minced","1/2 onion, chopped","2 cups vegetable broth","2 tbsp chopped parsley","1 tbsp olive oil","salt and pepper to taste"],"pasos":["Sauté the onion and garlic in oil; add the mushrooms and cook until they release their water.","Add the rice and broth; bring to a boil.","Cover and simmer for 40 minutes.","Season and garnish with parsley."],"titulo":"Brown rice with mushrooms","porciones":2}},"arroz-integral-vegetales":{"es":{"ingredientes":["1 taza de arroz integral","2 tazas de agua","1 zanahoria en cubos","1/2 taza de arvejas","1 chile dulce picado","1/2 cebolla picada","1 cda de aceite","sal al gusto"],"pasos":["Sofría la cebolla, el chile dulce y la zanahoria en aceite 5 minutos.","Agregue el arroz, el agua y la sal; hierva.","Tape y cocine a fuego bajo 35 minutos; agregue las arvejas los últimos 5 minutos."],"titulo":"Arroz integral con vegetales","porciones":2},"en":{"ingredientes":["1 cup brown rice","2 cups water","1 carrot, diced","1/2 cup peas","1 sweet pepper, chopped","1/2 onion, chopped","1 tbsp oil","salt to taste"],"pasos":["Sauté the onion, sweet pepper and carrot in oil for 5 minutes.","Add the rice, water and salt; bring to a boil.","Cover and simmer for 35 minutes; add the peas for the last 5 minutes."],"titulo":"Brown rice with vegetables","porciones":2}},"berenjenas-rellenas":{"es":{"ingredientes":["2 berenjenas medianas","1 taza de garbanzos cocidos","2 tomates picados","1/2 cebolla picada","2 dientes de ajo picados","2 cdas de perejil picado","2 cdas de aceite de oliva","sal al gusto"],"pasos":["Caliente el horno a 190 °C. Corte las berenjenas por la mitad y vacíelas, dejando 1 cm de pared; pique la pulpa.","Sofría la cebolla, el ajo y la pulpa en aceite; agregue el tomate y los garbanzos y cocine 8 minutos.","Rellene las berenjenas y hornee 30 minutos.","Sirva con perejil."],"titulo":"Berenjenas rellenas de tomate y garbanzos","porciones":2},"en":{"ingredientes":["2 medium eggplants","1 cup cooked chickpeas","2 tomatoes, chopped","1/2 onion, chopped","2 garlic cloves, minced","2 tbsp chopped parsley","2 tbsp olive oil","salt to taste"],"pasos":["Heat the oven to 190 °C. Halve the eggplants and scoop them out, leaving a 1 cm wall; chop the flesh.","Sauté the onion, garlic and flesh in oil; add the tomatoes and chickpeas and cook for 8 minutes.","Fill the eggplants and bake for 30 minutes.","Serve with parsley."],"titulo":"Stuffed eggplants with tomato and chickpeas","porciones":2}},"bowl-frijoles-negros-maiz":{"es":{"ingredientes":["1 taza de arroz cocido","1 taza de frijoles negros cocidos","1/2 taza de maíz","1 aguacate","1 tomate picado","2 cdas de culantro picado","1 limón","sal al gusto"],"pasos":["Caliente los frijoles y el maíz en una olla con sal.","Divida el arroz en dos bowls y agregue los frijoles y el maíz.","Agregue el tomate, el aguacate en láminas y el culantro.","Exprima el limón por encima."],"titulo":"Bowl de frijoles negros, maíz y aguacate","porciones":2},"en":{"ingredientes":["1 cup cooked rice","1 cup cooked black beans","1/2 cup corn","1 avocado","1 tomato, chopped","2 tbsp chopped culantro","1 lime","salt to taste"],"pasos":["Warm the beans and corn in a pot with salt.","Divide the rice between two bowls and top with the beans and corn.","Add the tomato, sliced avocado and culantro.","Squeeze the lime over the top."],"titulo":"Black bean, corn and avocado bowl","porciones":2}},"bowl-quinoa-vegetales":{"es":{"ingredientes":["1 taza de quinoa","2 tazas de agua","1 zanahoria rallada","1 taza de brócoli","1 pepino en rodajas","1/2 aguacate","2 cdas de aceite de oliva","1 limón","sal al gusto"],"pasos":["Lave la quinoa y cocínela en el agua con sal 15 minutos; deje reposar tapada.","Cocine el brócoli al vapor 5 minutos.","Arme los bowls con la quinoa, el brócoli, la zanahoria, el pepino y el aguacate.","Aliñe con el aceite y el jugo de limón."],"titulo":"Bowl de quinoa con vegetales","porciones":2},"en":{"ingredientes":["1 cup quinoa","2 cups water","1 carrot, grated","1 cup broccoli","1 cucumber, sliced","1/2 avocado","2 tbsp olive oil","1 lemon","salt to taste"],"pasos":["Rinse the quinoa and cook in the salted water for 15 minutes; let rest covered.","Steam the broccoli for 5 minutes.","Build the bowls with quinoa, broccoli, carrot, cucumber and avocado.","Dress with the oil and lemon juice."],"titulo":"Quinoa bowl with vegetables","porciones":2}},"burrito-integral-desayuno":{"es":{"ingredientes":["2 tortillas de harina integral","3 huevos","1/2 taza de frijoles negros cocidos","1 tomate picado","1/2 aguacate","1 cdta de aceite","sal al gusto"],"pasos":["Bata los huevos con sal y revuélvalos en una sartén con aceite.","Caliente los frijoles y las tortillas.","Rellene cada tortilla con huevo, frijoles, tomate y aguacate.","Enrolle y sirva."],"titulo":"Burrito integral de desayuno","porciones":2},"en":{"ingredientes":["2 whole-wheat flour tortillas","3 eggs","1/2 cup cooked black beans","1 tomato, chopped","1/2 avocado","1 tsp oil","salt to taste"],"pasos":["Beat the eggs with salt and scramble them in a pan with oil.","Warm the beans and tortillas.","Fill each tortilla with egg, beans, tomato and avocado.","Roll up and serve."],"titulo":"Whole-wheat breakfast burrito","porciones":2}},"camarones-salteados-vegetales":{"es":{"ingredientes":["300 g de camarones pelados","1 taza de brócoli en ramitos","1 chile dulce en tiras","1 zanahoria en rodajas finas","2 dientes de ajo picados","1 cdta de jengibre rallado","1 cda de aceite","1 limón","sal al gusto"],"pasos":["Caliente el aceite a fuego alto y saltee el ajo y el jengibre 30 segundos.","Agregue la zanahoria y el brócoli y saltee 4 minutos.","Agregue el chile dulce y los camarones y cocine 3 minutos hasta que estén rosados.","Sazone con sal y limón."],"titulo":"Camarones salteados con vegetales","porciones":2},"en":{"ingredientes":["300 g peeled shrimp","1 cup broccoli florets","1 sweet pepper, sliced","1 carrot, thinly sliced","2 garlic cloves, minced","1 tsp grated ginger","1 tbsp oil","1 lime","salt to taste"],"pasos":["Heat the oil over high heat and stir-fry the garlic and ginger for 30 seconds.","Add the carrot and broccoli and stir-fry for 4 minutes.","Add the sweet pepper and shrimp and cook for 3 minutes until pink.","Season with salt and lime juice."],"titulo":"Stir-fried shrimp with vegetables","porciones":2}},"camarones-vegetales-frescos":{"es":{"ingredientes":["300 g de camarones pelados","2 tomates en cubos","1 pepino en cubos","1/2 cebolla morada en tiras","2 cdas de culantro picado","2 limones","1 cda de aceite de oliva","sal al gusto"],"pasos":["Cocine los camarones en agua hirviendo con sal 2 o 3 minutos; escúrralos y enfríelos.","Mezcle el tomate, el pepino, la cebolla y el culantro.","Agregue los camarones, el jugo de limón y el aceite.","Mezcle y sirva fresco."],"titulo":"Camarones con vegetales frescos","porciones":2},"en":{"ingredientes":["300 g peeled shrimp","2 tomatoes, diced","1 cucumber, diced","1/2 red onion, sliced","2 tbsp chopped culantro","2 limes","1 tbsp olive oil","salt to taste"],"pasos":["Cook the shrimp in boiling salted water for 2 to 3 minutes; drain and cool.","Mix the tomato, cucumber, onion and culantro.","Add the shrimp, lime juice and oil.","Toss and serve chilled."],"titulo":"Shrimp with fresh vegetables","porciones":2}},"casado-costarricense":{"es":{"ingredientes":["1 taza de arroz cocido","1 taza de frijoles negros cocidos","2 pechugas de pollo pequeñas","1 plátano maduro","1 tomate en rodajas","2 hojas de lechuga","1 zanahoria rallada","2 cdas de aceite","sal al gusto"],"pasos":["Sazone el pollo con sal y cocínelo a la plancha con un poco de aceite, 6 minutos por lado.","Fría el plátano en rodajas hasta que dore.","Caliente los frijoles y el arroz.","Sirva todo en un plato con la ensalada de tomate, lechuga y zanahoria."],"titulo":"Casado costarricense con pollo","porciones":2},"en":{"ingredientes":["1 cup cooked rice","1 cup cooked black beans","2 small chicken breasts","1 ripe plantain","1 tomato, sliced","2 lettuce leaves","1 carrot, grated","2 tbsp oil","salt to taste"],"pasos":["Season the chicken with salt and cook on a griddle with a little oil, 6 minutes per side.","Fry the plantain slices until golden.","Warm the beans and rice.","Plate everything with the tomato, lettuce and carrot salad."],"titulo":"Costa Rican casado with chicken","porciones":2}},"cazuela-vegetales-granos":{"es":{"ingredientes":["1/2 taza de arroz integral","1/2 taza de lentejas","1 zanahoria en cubos","1 papa en cubos","1 chile dulce picado","1/2 cebolla picada","3 tazas de caldo de verduras","1 cda de aceite","sal y pimienta al gusto"],"pasos":["Sofría la cebolla y el chile dulce en aceite.","Agregue el arroz, las lentejas, la zanahoria, la papa y el caldo.","Hierva, tape y cocine a fuego bajo 40 minutos.","Sazone y sirva caliente."],"titulo":"Cazuela de vegetales y granos","porciones":2},"en":{"ingredientes":["1/2 cup brown rice","1/2 cup lentils","1 carrot, diced","1 potato, diced","1 sweet pepper, chopped","1/2 onion, chopped","3 cups vegetable broth","1 tbsp oil","salt and pepper to taste"],"pasos":["Sauté the onion and sweet pepper in oil.","Add the rice, lentils, carrot, potato and broth.","Bring to a boil, cover and simmer for 40 minutes.","Season and serve hot."],"titulo":"Vegetable and grain casserole","porciones":2}},"ceviche-pescado":{"es":{"ingredientes":["300 g de filete de corvina fresco en cubos","6 limones","1/2 cebolla morada picada","1/2 chile dulce picado","3 cdas de culantro picado","1 cdta de sal"],"pasos":["Exprima los limones y coloque el pescado en el jugo con la sal.","Refrigere 20 minutos, hasta que el pescado se vea opaco.","Agregue la cebolla, el chile dulce y el culantro.","Mezcle y sirva frío."],"titulo":"Ceviche de pescado","porciones":2},"en":{"ingredientes":["300 g fresh sea bass fillet, cubed","6 limes","1/2 red onion, chopped","1/2 sweet pepper, chopped","3 tbsp chopped culantro","1 tsp salt"],"pasos":["Squeeze the limes and place the fish in the juice with the salt.","Refrigerate 20 minutes, until the fish looks opaque.","Add the onion, sweet pepper and culantro.","Toss and serve cold."],"titulo":"Fish ceviche","porciones":2}},"crema-ayote-zanahoria":{"es":{"ingredientes":["300 g de ayote en cubos","2 zanahorias en rodajas","1/2 cebolla picada","1 diente de ajo","3 tazas de caldo de verduras","1 cda de aceite","sal y pimienta al gusto"],"pasos":["Sofría la cebolla y el ajo en aceite.","Agregue el ayote, la zanahoria y el caldo; cocine 20 minutos hasta que estén suaves.","Licúe hasta obtener una sopa lisa.","Sazone y sirva caliente."],"titulo":"Sopa cremosa de ayote y zanahoria","porciones":2},"en":{"ingredientes":["300 g squash, cubed","2 carrots, sliced","1/2 onion, chopped","1 garlic clove","3 cups vegetable broth","1 tbsp oil","salt and pepper to taste"],"pasos":["Sauté the onion and garlic in oil.","Add the squash, carrot and broth; cook 20 minutes until soft.","Blend until smooth.","Season and serve hot."],"titulo":"Creamy squash and carrot soup","porciones":2}},"crema-coliflor":{"es":{"ingredientes":["1 coliflor mediana en ramitos","1 papa pequeña en cubos","1/2 cebolla picada","1 diente de ajo","3 tazas de caldo de verduras","1 cda de aceite de oliva","sal y pimienta al gusto"],"pasos":["Sofría la cebolla y el ajo en el aceite.","Agregue la coliflor, la papa y el caldo; cocine 20 minutos.","Licúe hasta que quede lisa.","Sazone y sirva."],"titulo":"Sopa cremosa de coliflor","porciones":2},"en":{"ingredientes":["1 medium cauliflower, in florets","1 small potato, cubed","1/2 onion, chopped","1 garlic clove","3 cups vegetable broth","1 tbsp olive oil","salt and pepper to taste"],"pasos":["Sauté the onion and garlic in the oil.","Add the cauliflower, potato and broth; cook 20 minutes.","Blend until smooth.","Season and serve."],"titulo":"Creamy cauliflower soup","porciones":2}},"crema-tomate-albahaca":{"es":{"ingredientes":["6 tomates maduros","1/2 cebolla picada","2 dientes de ajo","1 taza de caldo de verduras","1/4 de taza de albahaca fresca","1 cda de aceite de oliva","sal y pimienta al gusto"],"pasos":["Sofría la cebolla y el ajo en aceite.","Agregue los tomates picados y el caldo; cocine 20 minutos.","Agregue la albahaca y licúe hasta que quede lisa.","Sazone y caliente de nuevo antes de servir."],"titulo":"Sopa cremosa de tomate y albahaca","porciones":2},"en":{"ingredientes":["6 ripe tomatoes","1/2 onion, chopped","2 garlic cloves","1 cup vegetable broth","1/4 cup fresh basil","1 tbsp olive oil","salt and pepper to taste"],"pasos":["Sauté the onion and garlic in oil.","Add the chopped tomatoes and broth; cook 20 minutes.","Add the basil and blend until smooth.","Season and reheat before serving."],"titulo":"Creamy tomato and basil soup","porciones":2}},"curry-garbanzos-coco":{"es":{"ingredientes":["2 tazas de garbanzos cocidos","1 taza de leche de coco","2 tomates picados","1/2 cebolla picada","2 dientes de ajo picados","1 cda de curry en polvo","1 cdta de jengibre rallado","1 cda de aceite","sal al gusto"],"pasos":["Sofría la cebolla, el ajo y el jengibre en aceite.","Agregue el curry y el tomate y cocine 5 minutos.","Agregue los garbanzos y la leche de coco; cocine 15 minutos a fuego bajo.","Sazone con sal y sirva, si desea con arroz."],"titulo":"Curry de garbanzos con leche de coco","porciones":2},"en":{"ingredientes":["2 cups cooked chickpeas","1 cup coconut milk","2 tomatoes, chopped","1/2 onion, chopped","2 garlic cloves, minced","1 tbsp curry powder","1 tsp grated ginger","1 tbsp oil","salt to taste"],"pasos":["Sauté the onion, garlic and ginger in oil.","Add the curry powder and tomatoes and cook for 5 minutes.","Add the chickpeas and coconut milk; simmer for 15 minutes.","Season with salt and serve, with rice if you like."],"titulo":"Chickpea curry with coconut milk","porciones":2}},"dal-lentejas-rojas":{"es":{"ingredientes":["1 taza de lentejas rojas","3 tazas de agua","1/2 cebolla picada","2 dientes de ajo picados","1 tomate picado","1 cdta de cúrcuma","1 cdta de comino","1 cda de aceite","1 limón","sal al gusto"],"pasos":["Enjuague las lentejas y cocínelas en el agua con la cúrcuma 20 minutos.","En otra sartén sofría la cebolla, el ajo y el comino en aceite; agregue el tomate.","Mezcle el sofrito con las lentejas y cocine 5 minutos más.","Sazone con sal y jugo de limón."],"titulo":"Dal de lentejas rojas","porciones":2},"en":{"ingredientes":["1 cup red lentils","3 cups water","1/2 onion, chopped","2 garlic cloves, minced","1 tomato, chopped","1 tsp turmeric","1 tsp cumin","1 tbsp oil","1 lemon","salt to taste"],"pasos":["Rinse the lentils and cook them in the water with the turmeric for 20 minutes.","In another pan sauté the onion, garlic and cumin in oil; add the tomato.","Stir the sauté into the lentils and cook 5 more minutes.","Season with salt and lemon juice."],"titulo":"Red lentil dal","porciones":2}},"ensalada-atun":{"es":{"ingredientes":["1 lata de atún (140 g) escurrida","2 huevos cocidos","2 tazas de lechuga","2 tomates en gajos","1/2 pepino en rodajas","1 cda de aceite de oliva","1 limón","sal y pimienta al gusto"],"pasos":["Cocine los huevos 10 minutos en agua hirviendo, enfríelos y pélelos.","Coloque la lechuga, el tomate y el pepino en un plato.","Agregue el atún y los huevos en cuartos.","Aliñe con aceite, limón, sal y pimienta."],"titulo":"Ensalada de atún con huevo","porciones":2},"en":{"ingredientes":["1 can tuna (140 g), drained","2 hard-boiled eggs","2 cups lettuce","2 tomatoes, in wedges","1/2 cucumber, sliced","1 tbsp olive oil","1 lemon","salt and pepper to taste"],"pasos":["Boil the eggs for 10 minutes, cool and peel them.","Place the lettuce, tomato and cucumber on a plate.","Add the tuna and the eggs in quarters.","Dress with oil, lemon, salt and pepper."],"titulo":"Tuna salad with egg","porciones":2}},"ensalada-espinacas-fresas":{"es":{"ingredientes":["3 tazas de espinacas frescas","1 taza de fresas en láminas","1/4 de taza de nueces","1/4 de cebolla morada en tiras finas","2 cdas de aceite de oliva","1 limón","sal al gusto"],"pasos":["Lave y escurra las espinacas.","Mezcle las espinacas, las fresas y la cebolla en un tazón.","Aliñe con el aceite, el jugo de limón y la sal.","Agregue las nueces picadas y sirva."],"titulo":"Ensalada de espinacas, fresas y nueces","porciones":2},"en":{"ingredientes":["3 cups fresh spinach","1 cup sliced strawberries","1/4 cup walnuts","1/4 red onion, thinly sliced","2 tbsp olive oil","1 lemon","salt to taste"],"pasos":["Wash and drain the spinach.","Combine the spinach, strawberries and onion in a bowl.","Dress with the oil, lemon juice and salt.","Top with the chopped walnuts and serve."],"titulo":"Spinach, strawberry and walnut salad","porciones":2}},"ensalada-mediterranea-garbanzos":{"es":{"ingredientes":["2 tazas de garbanzos cocidos","2 tomates en cubos","1 pepino en cubos","1/2 cebolla morada picada","10 aceitunas","2 cdas de aceite de oliva","1 limón","1 cda de orégano","sal al gusto"],"pasos":["Mezcle los garbanzos, el tomate, el pepino, la cebolla y las aceitunas.","Aliñe con el aceite, el jugo de limón, el orégano y la sal.","Deje reposar 10 minutos antes de servir."],"titulo":"Ensalada mediterránea de garbanzos","porciones":2},"en":{"ingredientes":["2 cups cooked chickpeas","2 tomatoes, diced","1 cucumber, diced","1/2 red onion, chopped","10 olives","2 tbsp olive oil","1 lemon","1 tbsp oregano","salt to taste"],"pasos":["Mix the chickpeas, tomato, cucumber, onion and olives.","Dress with the oil, lemon juice, oregano and salt.","Let it rest 10 minutes before serving."],"titulo":"Mediterranean chickpea salad","porciones":2}},"ensalada-mediterranea":{"es":{"ingredientes":["3 tomates en cubos","1 pepino en cubos","1/2 cebolla morada en tiras","10 aceitunas","100 g de queso feta","2 cdas de aceite de oliva","1 cdta de orégano","sal al gusto"],"pasos":["Mezcle el tomate, el pepino, la cebolla y las aceitunas.","Agregue el queso feta en cubos.","Aliñe con el aceite, el orégano y la sal."],"titulo":"Ensalada mediterránea con queso feta","porciones":2},"en":{"ingredientes":["3 tomatoes, diced","1 cucumber, diced","1/2 red onion, sliced","10 olives","100 g feta cheese","2 tbsp olive oil","1 tsp oregano","salt to taste"],"pasos":["Combine the tomato, cucumber, onion and olives.","Add the cubed feta.","Dress with the oil, oregano and salt."],"titulo":"Mediterranean salad with feta","porciones":2}},"ensalada-pepino-tomate":{"es":{"ingredientes":["2 pepinos en rodajas","3 tomates en gajos","1/2 cebolla morada en tiras finas","2 cdas de aceite de oliva","1 limón","2 cdas de perejil picado","sal al gusto"],"pasos":["Coloque el pepino, el tomate y la cebolla en un tazón.","Aliñe con el aceite, el limón y la sal.","Agregue el perejil y sirva."],"titulo":"Ensalada de pepino y tomate","porciones":2},"en":{"ingredientes":["2 cucumbers, sliced","3 tomatoes, in wedges","1/2 red onion, thinly sliced","2 tbsp olive oil","1 lemon","2 tbsp chopped parsley","salt to taste"],"pasos":["Place the cucumber, tomato and onion in a bowl.","Dress with the oil, lemon and salt.","Add the parsley and serve."],"titulo":"Cucumber and tomato salad","porciones":2}},"ensalada-pollo":{"es":{"ingredientes":["2 pechugas de pollo cocidas","3 tazas de lechuga","1 tomate en gajos","1 zanahoria rallada","1/2 pepino en rodajas","2 cdas de aceite de oliva","1 limón","sal y pimienta al gusto"],"pasos":["Cocine las pechugas en agua con sal 15 minutos, enfríelas y deshébrelas.","Mezcle la lechuga, el tomate, la zanahoria y el pepino en un tazón.","Agregue el pollo.","Aliñe con aceite, limón, sal y pimienta."],"titulo":"Ensalada de pollo","porciones":2},"en":{"ingredientes":["2 cooked chicken breasts","3 cups lettuce","1 tomato, in wedges","1 carrot, grated","1/2 cucumber, sliced","2 tbsp olive oil","1 lemon","salt and pepper to taste"],"pasos":["Cook the breasts in salted water for 15 minutes, cool and shred.","Combine the lettuce, tomato, carrot and cucumber in a bowl.","Add the chicken.","Dress with oil, lemon, salt and pepper."],"titulo":"Chicken salad","porciones":2}},"ensalada-quinoa-aguacate":{"es":{"ingredientes":["1 taza de quinoa","2 tazas de agua","1 aguacate en cubos","1 tomate en cubos","1/2 pepino en cubos","2 cdas de culantro picado","2 cdas de aceite de oliva","1 limón","sal al gusto"],"pasos":["Lave la quinoa y cocínela en el agua con sal 15 minutos; enfríela.","Mezcle con el tomate, el pepino y el culantro.","Agregue el aguacate con cuidado.","Aliñe con el aceite y el limón."],"titulo":"Ensalada de quinoa y aguacate","porciones":2},"en":{"ingredientes":["1 cup quinoa","2 cups water","1 avocado, diced","1 tomato, diced","1/2 cucumber, diced","2 tbsp chopped culantro","2 tbsp olive oil","1 lime","salt to taste"],"pasos":["Rinse the quinoa and cook in the salted water for 15 minutes; cool.","Mix with the tomato, cucumber and culantro.","Gently fold in the avocado.","Dress with the oil and lime."],"titulo":"Quinoa and avocado salad","porciones":2}},"ensalada-remolacha-nueces":{"es":{"ingredientes":["3 remolachas medianas","1/4 de taza de nueces","2 tazas de lechuga o espinaca","2 cdas de aceite de oliva","1 limón","sal al gusto"],"pasos":["Cocine las remolachas en agua 30 minutos hasta que estén suaves; pélelas y córtelas en rodajas.","Acomode las hojas en un plato y encima las remolachas.","Aliñe con el aceite, el limón y la sal.","Agregue las nueces picadas."],"titulo":"Ensalada de remolacha con nueces","porciones":2},"en":{"ingredientes":["3 medium beets","1/4 cup walnuts","2 cups lettuce or spinach","2 tbsp olive oil","1 lemon","salt to taste"],"pasos":["Boil the beets for 30 minutes until tender; peel and slice.","Arrange the leaves on a plate and top with the beets.","Dress with the oil, lemon and salt.","Top with the chopped walnuts."],"titulo":"Beet salad with walnuts","porciones":2}},"ensalada-tropical-mango-aguacate":{"es":{"ingredientes":["1 mango maduro en cubos","1 aguacate en cubos","3 tazas de lechuga","1/4 de cebolla morada en tiras finas","2 limones","1 cda de aceite de oliva","sal al gusto"],"pasos":["Coloque la lechuga en un tazón o plato.","Agregue el mango, el aguacate y la cebolla.","Mezcle el jugo de limón, el aceite y la sal; aliñe la ensalada."],"titulo":"Ensalada tropical de mango y aguacate","porciones":2},"en":{"ingredientes":["1 ripe mango, diced","1 avocado, diced","3 cups lettuce","1/4 red onion, thinly sliced","2 limes","1 tbsp olive oil","salt to taste"],"pasos":["Place the lettuce in a bowl or plate.","Add the mango, avocado and onion.","Whisk the lime juice, oil and salt; dress the salad."],"titulo":"Tropical mango and avocado salad","porciones":2}},"ensalada-vegetales-semillas":{"es":{"ingredientes":["3 tazas de lechuga","1 zanahoria rallada","1 tomate en gajos","1/2 pepino en rodajas","2 cdas de semillas de girasol","1 cda de semillas de calabaza","2 cdas de aceite de oliva","1 limón","sal al gusto"],"pasos":["Mezcle la lechuga, la zanahoria, el tomate y el pepino.","Aliñe con el aceite, el limón y la sal.","Espolvoree las semillas y sirva."],"titulo":"Ensalada de vegetales con semillas","porciones":2},"en":{"ingredientes":["3 cups lettuce","1 carrot, grated","1 tomato, in wedges","1/2 cucumber, sliced","2 tbsp sunflower seeds","1 tbsp pumpkin seeds","2 tbsp olive oil","1 lemon","salt to taste"],"pasos":["Combine the lettuce, carrot, tomato and cucumber.","Dress with the oil, lemon and salt.","Sprinkle with the seeds and serve."],"titulo":"Vegetable salad with seeds","porciones":2}},"espagueti-integral-vegetales":{"es":{"ingredientes":["200 g de espagueti integral","1 zucchini en cubos","1 chile dulce en tiras","2 tomates picados","2 dientes de ajo picados","2 cdas de aceite de oliva","2 cdas de albahaca fresca","sal al gusto"],"pasos":["Cocine el espagueti en agua con sal según el paquete y escúrralo.","Sofría el ajo en aceite; agregue el zucchini y el chile dulce 5 minutos.","Agregue el tomate y cocine 5 minutos.","Mezcle con el espagueti y la albahaca."],"titulo":"Espagueti integral con vegetales","porciones":2},"en":{"ingredientes":["200 g whole-wheat spaghetti","1 zucchini, diced","1 sweet pepper, sliced","2 tomatoes, chopped","2 garlic cloves, minced","2 tbsp olive oil","2 tbsp fresh basil","salt to taste"],"pasos":["Cook the spaghetti in salted water as directed and drain.","Sauté the garlic in oil; add the zucchini and sweet pepper for 5 minutes.","Add the tomatoes and cook 5 minutes.","Toss with the spaghetti and basil."],"titulo":"Whole-wheat spaghetti with vegetables","porciones":2}},"filete-pescado-limon":{"es":{"ingredientes":["2 filetes de pescado blanco (300 g)","2 limones","2 dientes de ajo picados","1 cda de aceite de oliva","2 cdas de perejil picado","sal y pimienta al gusto"],"pasos":["Sazone el pescado con sal, pimienta, ajo y el jugo de un limón.","Cocine en una sartén con aceite 4 minutos por lado.","Sirva con perejil y rodajas del otro limón."],"titulo":"Filete de pescado al limón","porciones":2},"en":{"ingredientes":["2 white fish fillets (300 g)","2 lemons","2 garlic cloves, minced","1 tbsp olive oil","2 tbsp chopped parsley","salt and pepper to taste"],"pasos":["Season the fish with salt, pepper, garlic and the juice of one lemon.","Cook in a pan with oil, 4 minutes per side.","Serve with parsley and slices of the other lemon."],"titulo":"Lemon fish fillet","porciones":2}},"gallo-pinto-huevo-aguacate":{"es":{"ingredientes":["1 1/2 tazas de arroz cocido","1 taza de frijoles negros cocidos con su caldo","1/4 de cebolla picada","1/4 de chile dulce picado","2 cdas de culantro picado","2 huevos","1/2 aguacate","1 cda de aceite"],"pasos":["Sofría la cebolla y el chile dulce en aceite 3 minutos.","Agregue los frijoles con un poco de su caldo y luego el arroz; mezcle hasta que se seque un poco.","Agregue el culantro.","Fría los huevos y sírvalos sobre el gallo pinto con el aguacate en láminas."],"titulo":"Gallo pinto con huevo y aguacate","porciones":2},"en":{"ingredientes":["1 1/2 cups cooked rice","1 cup cooked black beans with their broth","1/4 onion, chopped","1/4 sweet pepper, chopped","2 tbsp chopped culantro","2 eggs","1/2 avocado","1 tbsp oil"],"pasos":["Sauté the onion and sweet pepper in oil for 3 minutes.","Add the beans with a little of their broth and then the rice; stir until slightly dry.","Stir in the culantro.","Fry the eggs and serve over the gallo pinto with sliced avocado."],"titulo":"Gallo pinto with egg and avocado","porciones":2}},"gallo-pinto-tradicional":{"es":{"ingredientes":["1 1/2 tazas de arroz cocido","1 taza de frijoles negros cocidos con su caldo","1/2 cebolla picada","1/2 chile dulce picado","2 cdas de culantro picado","1 cda de aceite","sal al gusto"],"pasos":["Sofría la cebolla y el chile dulce en aceite 3 minutos.","Agregue los frijoles con un poco de su caldo y cocine 3 minutos.","Agregue el arroz y mezcle hasta que se integre.","Sazone con sal, agregue el culantro y sirva."],"titulo":"Gallo pinto tradicional","porciones":2},"en":{"ingredientes":["1 1/2 cups cooked rice","1 cup cooked black beans with their broth","1/2 onion, chopped","1/2 sweet pepper, chopped","2 tbsp chopped culantro","1 tbsp oil","salt to taste"],"pasos":["Sauté the onion and sweet pepper in oil for 3 minutes.","Add the beans with a little broth and cook for 3 minutes.","Add the rice and mix until combined.","Season with salt, add the culantro and serve."],"titulo":"Traditional gallo pinto","porciones":2}},"guiso-garbanzos-vegetales":{"es":{"ingredientes":["2 tazas de garbanzos cocidos","1 papa en cubos","1 zanahoria en rodajas","1 chile dulce picado","2 tomates picados","1/2 cebolla picada","2 dientes de ajo picados","1 cdta de paprika","1 taza de agua","1 cda de aceite de oliva"],"pasos":["Sofría la cebolla y el ajo en aceite; agregue la paprika.","Agregue el tomate y el chile dulce y cocine 5 minutos.","Agregue la papa, la zanahoria, los garbanzos y el agua.","Tape y cocine a fuego bajo 25 minutos; sazone con sal."],"titulo":"Guiso de garbanzos y vegetales","porciones":2},"en":{"ingredientes":["2 cups cooked chickpeas","1 potato, cubed","1 carrot, sliced","1 sweet pepper, chopped","2 tomatoes, chopped","1/2 onion, chopped","2 garlic cloves, minced","1 tsp paprika","1 cup water","1 tbsp olive oil"],"pasos":["Sauté the onion and garlic in oil; add the paprika.","Add the tomato and sweet pepper and cook for 5 minutes.","Add the potato, carrot, chickpeas and water.","Cover and simmer for 25 minutes; season with salt."],"titulo":"Chickpea and vegetable stew","porciones":2}},"hamburguesa-garbanzos":{"es":{"ingredientes":["2 tazas de garbanzos cocidos","1/4 de taza de pan molido","1/4 de cebolla picada","1 diente de ajo picado","1 cdta de comino","2 panes para hamburguesa","1 tomate en rodajas","2 hojas de lechuga","1 cda de aceite"],"pasos":["Triture los garbanzos con un tenedor y mezcle con el pan molido, la cebolla, el ajo, el comino y sal.","Forme dos hamburguesas.","Cocínelas en una sartén con aceite 4 minutos por lado.","Arme los panes con la hamburguesa, el tomate y la lechuga."],"titulo":"Hamburguesa de garbanzos","porciones":2},"en":{"ingredientes":["2 cups cooked chickpeas","1/4 cup breadcrumbs","1/4 onion, chopped","1 garlic clove, minced","1 tsp cumin","2 burger buns","1 tomato, sliced","2 lettuce leaves","1 tbsp oil"],"pasos":["Mash the chickpeas with a fork and mix with the breadcrumbs, onion, garlic, cumin and salt.","Shape into two patties.","Cook in a pan with oil for 4 minutes per side.","Assemble the buns with the patty, tomato and lettuce."],"titulo":"Chickpea burger","porciones":2}},"lasana-vegetales":{"es":{"ingredientes":["9 láminas de lasaña","2 tazas de salsa de tomate","1 zucchini en láminas","1 taza de espinacas","1 taza de hongos en láminas","2 tazas de queso mozzarella rallado","1 cda de aceite de oliva","sal y pimienta al gusto"],"pasos":["Caliente el horno a 180 °C. Saltee el zucchini, los hongos y las espinacas en aceite 5 minutos.","En un molde ponga salsa, una capa de láminas, vegetales y queso.","Repita las capas y termine con salsa y queso.","Tape con papel de aluminio y hornee 35 minutos; destape y hornee 10 minutos más."],"titulo":"Lasaña de vegetales","porciones":4},"en":{"ingredientes":["9 lasagna sheets","2 cups tomato sauce","1 zucchini, sliced","1 cup spinach","1 cup sliced mushrooms","2 cups grated mozzarella","1 tbsp olive oil","salt and pepper to taste"],"pasos":["Heat the oven to 180 °C. Sauté the zucchini, mushrooms and spinach in oil for 5 minutes.","In a baking dish layer sauce, sheets, vegetables and cheese.","Repeat the layers and finish with sauce and cheese.","Cover with foil and bake 35 minutes; uncover and bake 10 more minutes."],"titulo":"Vegetable lasagna","porciones":4}},"lomo-cerdo-vegetales":{"es":{"ingredientes":["400 g de lomo de cerdo","2 papas en cuartos","2 zanahorias en trozos","1 cebolla en gajos","3 dientes de ajo","2 cdas de aceite de oliva","1 cdta de orégano","sal y pimienta al gusto"],"pasos":["Caliente el horno a 190 °C. Sazone el lomo con sal, pimienta, ajo y orégano.","Coloque las papas, las zanahorias y la cebolla en una bandeja con aceite.","Ponga el lomo encima y hornee 40 minutos.","Deje reposar 5 minutos y corte en rodajas."],"titulo":"Lomo de cerdo con vegetales","porciones":2},"en":{"ingredientes":["400 g pork loin","2 potatoes, quartered","2 carrots, chunked","1 onion, in wedges","3 garlic cloves","2 tbsp olive oil","1 tsp oregano","salt and pepper to taste"],"pasos":["Heat the oven to 190 °C. Season the loin with salt, pepper, garlic and oregano.","Place the potatoes, carrots and onion on a tray with oil.","Place the loin on top and bake for 40 minutes.","Rest 5 minutes and slice."],"titulo":"Pork loin with vegetables","porciones":2}},"mexicano-chilaquiles":{"es":{"ingredientes":["6 tortillas de maíz en triángulos","2 tomates","1/4 de cebolla","1 diente de ajo","2 huevos","1/4 de taza de queso fresco desmenuzado","2 cdas de aceite","sal al gusto"],"pasos":["Hornee o fría los triángulos de tortilla hasta que estén crujientes.","Licúe los tomates cocidos con la cebolla, el ajo y sal; cocine la salsa 5 minutos.","Mezcle las tortillas con la salsa 2 minutos.","Sirva con los huevos fritos y el queso fresco."],"titulo":"Chilaquiles rojos con huevo","porciones":2},"en":{"ingredientes":["6 corn tortillas, cut in triangles","2 tomatoes","1/4 onion","1 garlic clove","2 eggs","1/4 cup crumbled fresh cheese","2 tbsp oil","salt to taste"],"pasos":["Bake or fry the tortilla triangles until crisp.","Blend the cooked tomatoes with the onion, garlic and salt; simmer the sauce for 5 minutes.","Toss the tortillas in the sauce for 2 minutes.","Serve with fried eggs and fresh cheese."],"titulo":"Red chilaquiles with egg","porciones":2}},"mexicano-chiles-rellenos":{"es":{"ingredientes":["4 chiles poblanos o chiles dulces grandes","200 g de queso fresco en tiras","2 huevos","1/4 de taza de harina de trigo","2 tomates","1/4 de cebolla","1/2 taza de aceite"],"pasos":["Ase los chiles, pélelos y rellénelos con el queso.","Separe las claras y bátalas a punto de nieve; agregue las yemas.","Pase los chiles por harina y luego por el huevo; fríalos hasta dorar.","Licúe los tomates con la cebolla y sal, cocine 5 minutos y sirva sobre los chiles."],"titulo":"Chiles rellenos con queso","porciones":2},"en":{"ingredientes":["4 poblano or large sweet peppers","200 g fresh cheese, in strips","2 eggs","1/4 cup wheat flour","2 tomatoes","1/4 onion","1/2 cup oil"],"pasos":["Roast the peppers, peel them and stuff with the cheese.","Separate the whites and whip to stiff peaks; fold in the yolks.","Dust the peppers in flour, dip in the egg and fry until golden.","Blend the tomatoes with the onion and salt, simmer 5 minutes and serve over the peppers."],"titulo":"Cheese-stuffed peppers","porciones":2}},"mexicano-enchiladas":{"es":{"ingredientes":["6 tortillas de maíz","2 tazas de pollo cocido deshebrado","2 tazas de salsa de tomate","1/2 taza de queso rallado","1/4 de cebolla picada","1 cda de aceite"],"pasos":["Caliente el horno a 180 °C. Caliente las tortillas en aceite para suavizarlas.","Rellene cada tortilla con pollo y cebolla y enróllelas.","Colóquelas en un molde, cubra con la salsa y el queso.","Hornee 15 minutos."],"titulo":"Enchiladas de pollo","porciones":2},"en":{"ingredientes":["6 corn tortillas","2 cups cooked shredded chicken","2 cups tomato sauce","1/2 cup grated cheese","1/4 onion, chopped","1 tbsp oil"],"pasos":["Heat the oven to 180 °C. Warm the tortillas in oil to soften them.","Fill each tortilla with chicken and onion and roll up.","Place in a dish, top with the sauce and cheese.","Bake for 15 minutes."],"titulo":"Chicken enchiladas","porciones":2}},"mexicano-fajitas":{"es":{"ingredientes":["200 g de pechuga de pollo en tiras","200 g de res en tiras","1 chile dulce rojo en tiras","1 chile dulce verde en tiras","1 cebolla en tiras","6 tortillas de harina","1 cdta de comino","1 limón","2 cdas de aceite","sal al gusto"],"pasos":["Sazone el pollo y la res con comino, sal y limón.","Saltee la carne en aceite a fuego alto hasta que esté cocida; apártela.","Saltee la cebolla y los chiles dulces 5 minutos.","Mezcle con la carne y sirva con las tortillas calientes."],"titulo":"Fajitas de pollo y res","porciones":2},"en":{"ingredientes":["200 g chicken breast, sliced","200 g beef, sliced","1 red sweet pepper, sliced","1 green sweet pepper, sliced","1 onion, sliced","6 flour tortillas","1 tsp cumin","1 lime","2 tbsp oil","salt to taste"],"pasos":["Season the chicken and beef with cumin, salt and lime.","Stir-fry the meat in oil over high heat until cooked; set aside.","Stir-fry the onion and sweet peppers for 5 minutes.","Mix with the meat and serve with warm tortillas."],"titulo":"Chicken and beef fajitas","porciones":2}},"mexicano-pozole":{"es":{"ingredientes":["500 g de carne de cerdo en trozos","2 tazas de maíz cacahuazintle o mote cocido","1/2 cebolla","4 dientes de ajo","6 tazas de agua","2 cdas de orégano","1/4 de repollo rallado","4 rábanos en rodajas","2 limones"],"pasos":["Cocine el cerdo en el agua con la cebolla, el ajo y sal por 1 hora y media.","Agregue el maíz y cocine 30 minutos más.","Sirva caliente con repollo, rábano, orégano y limón."],"titulo":"Pozole de cerdo","porciones":4},"en":{"ingredientes":["500 g pork, in chunks","2 cups cooked hominy","1/2 onion","4 garlic cloves","6 cups water","2 tbsp oregano","1/4 cabbage, shredded","4 radishes, sliced","2 limes"],"pasos":["Cook the pork in the water with the onion, garlic and salt for 1 1/2 hours.","Add the hominy and cook 30 minutes more.","Serve hot with cabbage, radish, oregano and lime."],"titulo":"Pork pozole","porciones":4}},"minestrone-vegetales":{"es":{"ingredientes":["1/2 taza de pasta pequeña","1 taza de frijoles blancos o rojos cocidos","1 zanahoria en cubos","1 papa en cubos","1 zucchini en cubos","2 tomates picados","1 tallo de apio picado","4 tazas de caldo de verduras","1 cda de aceite de oliva","1 cda de albahaca"],"pasos":["Sofría el apio, la zanahoria y la papa en aceite 5 minutos.","Agregue el tomate y el caldo; cocine 15 minutos.","Agregue el zucchini, los frijoles y la pasta; cocine 10 minutos.","Sazone con sal y albahaca."],"titulo":"Minestrone de vegetales","porciones":4},"en":{"ingredientes":["1/2 cup small pasta","1 cup cooked white or red beans","1 carrot, diced","1 potato, diced","1 zucchini, diced","2 tomatoes, chopped","1 celery stalk, chopped","4 cups vegetable broth","1 tbsp olive oil","1 tbsp basil"],"pasos":["Sauté the celery, carrot and potato in oil for 5 minutes.","Add the tomatoes and broth; cook 15 minutes.","Add the zucchini, beans and pasta; cook 10 minutes.","Season with salt and basil."],"titulo":"Vegetable minestrone","porciones":4}},"mini-sandwiches-lentejas":{"es":{"ingredientes":["4 rebanadas de pan integral","1 taza de lentejas cocidas","1 cda de aceite de oliva","1/2 limón","1 diente de ajo pequeño","1 tomate en rodajas","2 hojas de lechuga","sal al gusto"],"pasos":["Triture las lentejas con el aceite, el limón, el ajo y la sal hasta formar una pasta.","Unte el pan con la pasta de lentejas.","Agregue el tomate y la lechuga, cierre y corte en triángulos."],"titulo":"Mini sándwiches de lentejas","porciones":2},"en":{"ingredientes":["4 slices of whole-wheat bread","1 cup cooked lentils","1 tbsp olive oil","1/2 lemon","1 small garlic clove","1 tomato, sliced","2 lettuce leaves","salt to taste"],"pasos":["Mash the lentils with the oil, lemon, garlic and salt into a spread.","Spread the lentil mixture on the bread.","Add the tomato and lettuce, close and cut into triangles."],"titulo":"Mini lentil sandwiches","porciones":2}},"olla-de-carne":{"es":{"ingredientes":["600 g de carne de res con hueso","1 yuca en trozos","2 papas en trozos","1 chayote en trozos","2 elotes en trozos","1 plátano verde en trozos","2 zanahorias","1 cebolla","8 tazas de agua","1/4 de taza de culantro"],"pasos":["Cocine la carne con la cebolla y sal en el agua 1 hora y media a fuego bajo, retirando la espuma.","Agregue la yuca, el plátano y las zanahorias; cocine 20 minutos.","Agregue la papa, el chayote y el elote; cocine 15 minutos más.","Sirva con el culantro picado."],"titulo":"Olla de carne costarricense","porciones":4},"en":{"ingredientes":["600 g beef with bone","1 cassava, chunked","2 potatoes, chunked","1 chayote, chunked","2 corn cobs, chunked","1 green plantain, chunked","2 carrots","1 onion","8 cups water","1/4 cup culantro"],"pasos":["Cook the beef with the onion and salt in the water for 1 1/2 hours, skimming the foam.","Add the cassava, plantain and carrots; cook 20 minutes.","Add the potato, chayote and corn; cook 15 minutes more.","Serve with chopped culantro."],"titulo":"Costa Rican beef and vegetable soup","porciones":4}},"omelette-vegetales":{"es":{"ingredientes":["3 huevos","1/4 de taza de espinaca picada","1/4 de chile dulce picado","1 tomate picado","1/4 de taza de queso rallado","1 cdta de aceite","sal al gusto"],"pasos":["Bata los huevos con sal.","Saltee el chile dulce, el tomate y la espinaca en aceite 2 minutos.","Vierta los huevos y cocine a fuego medio hasta que cuajen.","Agregue el queso, doble el omelette y sirva."],"titulo":"Omelette de vegetales con queso","porciones":1},"en":{"ingredientes":["3 eggs","1/4 cup chopped spinach","1/4 sweet pepper, chopped","1 tomato, chopped","1/4 cup grated cheese","1 tsp oil","salt to taste"],"pasos":["Beat the eggs with salt.","Sauté the sweet pepper, tomato and spinach in oil for 2 minutes.","Pour in the eggs and cook over medium heat until set.","Add the cheese, fold the omelet and serve."],"titulo":"Vegetable omelet with cheese","porciones":1}},"pasta-integral-pesto":{"es":{"ingredientes":["200 g de pasta integral","2 tazas de albahaca fresca","1/4 de taza de nueces","1/4 de taza de queso parmesano","1 diente de ajo","1/4 de taza de aceite de oliva","sal al gusto"],"pasos":["Cocine la pasta en agua con sal y escúrrala; guarde 1/4 de taza del agua.","Licúe la albahaca, las nueces, el parmesano, el ajo, el aceite y la sal.","Mezcle la pasta con el pesto y un poco del agua de cocción."],"titulo":"Pasta integral con pesto de albahaca y nueces","porciones":2},"en":{"ingredientes":["200 g whole-wheat pasta","2 cups fresh basil","1/4 cup walnuts","1/4 cup parmesan cheese","1 garlic clove","1/4 cup olive oil","salt to taste"],"pasos":["Cook the pasta in salted water and drain; save 1/4 cup of the water.","Blend the basil, walnuts, parmesan, garlic, oil and salt.","Toss the pasta with the pesto and a little cooking water."],"titulo":"Whole-wheat pasta with basil and walnut pesto","porciones":2}},"penne-integral-brocoli-hongos":{"es":{"ingredientes":["200 g de penne integral","2 tazas de brócoli en ramitos","1 1/2 tazas de hongos en láminas","3 dientes de ajo picados","2 cdas de aceite de oliva","1 limón","sal y pimienta al gusto"],"pasos":["Cocine el penne en agua con sal; agregue el brócoli los últimos 3 minutos y escurra.","Saltee los hongos y el ajo en aceite 6 minutos.","Mezcle con el penne y el brócoli.","Sazone y agregue jugo de limón."],"titulo":"Penne integral con brócoli y hongos","porciones":2},"en":{"ingredientes":["200 g whole-wheat penne","2 cups broccoli florets","1 1/2 cups sliced mushrooms","3 garlic cloves, minced","2 tbsp olive oil","1 lemon","salt and pepper to taste"],"pasos":["Cook the penne in salted water; add the broccoli for the last 3 minutes and drain.","Sauté the mushrooms and garlic in oil for 6 minutes.","Toss with the penne and broccoli.","Season and add lemon juice."],"titulo":"Whole-wheat penne with broccoli and mushrooms","porciones":2}},"pescado-horno-hierbas":{"es":{"ingredientes":["2 filetes de pescado blanco (300 g)","2 cdas de aceite de oliva","2 dientes de ajo picados","1 cda de perejil picado","1 cdta de tomillo","1 limón en rodajas","2 tomates en rodajas","sal y pimienta al gusto"],"pasos":["Caliente el horno a 200 °C. Coloque el tomate en un molde.","Ponga el pescado encima y sazone con sal, pimienta, ajo, perejil y tomillo.","Agregue el aceite y las rodajas de limón.","Hornee 15 a 18 minutos hasta que se desmenuce fácilmente."],"titulo":"Pescado al horno con hierbas","porciones":2},"en":{"ingredientes":["2 white fish fillets (300 g)","2 tbsp olive oil","2 garlic cloves, minced","1 tbsp chopped parsley","1 tsp thyme","1 lemon, sliced","2 tomatoes, sliced","salt and pepper to taste"],"pasos":["Heat the oven to 200 °C. Place the tomato slices in a dish.","Place the fish on top and season with salt, pepper, garlic, parsley and thyme.","Add the oil and lemon slices.","Bake 15 to 18 minutes until it flakes easily."],"titulo":"Baked fish with herbs","porciones":2}},"pescado-salsa-coco":{"es":{"ingredientes":["2 filetes de pescado (300 g)","1 taza de leche de coco","1/2 cebolla picada","2 dientes de ajo picados","1 tomate picado","1 cdta de jengibre rallado","1 limón","1 cda de aceite","sal al gusto"],"pasos":["Sofría la cebolla, el ajo y el jengibre en aceite; agregue el tomate.","Agregue la leche de coco y cocine 5 minutos.","Agregue el pescado con sal y cocine tapado 8 minutos.","Termine con el jugo de limón."],"titulo":"Pescado en salsa de coco","porciones":2},"en":{"ingredientes":["2 fish fillets (300 g)","1 cup coconut milk","1/2 onion, chopped","2 garlic cloves, minced","1 tomato, chopped","1 tsp grated ginger","1 lime","1 tbsp oil","salt to taste"],"pasos":["Sauté the onion, garlic and ginger in oil; add the tomato.","Add the coconut milk and simmer 5 minutes.","Add the fish with salt and cook covered for 8 minutes.","Finish with the lime juice."],"titulo":"Fish in coconut sauce","porciones":2}},"picadillo-chayote":{"es":{"ingredientes":["2 chayotes en cubos pequeños","200 g de carne molida de res","1/2 cebolla picada","1/2 chile dulce picado","2 dientes de ajo picados","2 cdas de culantro picado","1 cda de aceite","sal al gusto"],"pasos":["Sofría la cebolla, el chile dulce y el ajo en aceite.","Agregue la carne y cocine hasta que cambie de color.","Agregue el chayote con 1/2 taza de agua y sal; tape y cocine 12 minutos.","Termine con el culantro."],"titulo":"Picadillo de chayote con carne","porciones":2},"en":{"ingredientes":["2 chayotes, small-diced","200 g ground beef","1/2 onion, chopped","1/2 sweet pepper, chopped","2 garlic cloves, minced","2 tbsp chopped culantro","1 tbsp oil","salt to taste"],"pasos":["Sauté the onion, sweet pepper and garlic in oil.","Add the beef and cook until browned.","Add the chayote with 1/2 cup water and salt; cover and cook 12 minutes.","Finish with the culantro."],"titulo":"Chayote picadillo with ground beef","porciones":2}},"picadillo-papa-carne":{"es":{"ingredientes":["3 papas en cubos pequeños","200 g de carne molida de res","1/2 cebolla picada","1/2 chile dulce picado","2 dientes de ajo picados","2 cdas de culantro picado","1 cda de aceite","sal al gusto"],"pasos":["Sofría la cebolla, el chile dulce y el ajo en aceite.","Agregue la carne y cocine hasta que cambie de color.","Agregue las papas con 1/2 taza de agua y sal; tape y cocine 15 minutos.","Termine con el culantro."],"titulo":"Picadillo de papa con carne","porciones":2},"en":{"ingredientes":["3 potatoes, small-diced","200 g ground beef","1/2 onion, chopped","1/2 sweet pepper, chopped","2 garlic cloves, minced","2 tbsp chopped culantro","1 tbsp oil","salt to taste"],"pasos":["Sauté the onion, sweet pepper and garlic in oil.","Add the beef and cook until browned.","Add the potatoes with 1/2 cup water and salt; cover and cook 15 minutes.","Finish with the culantro."],"titulo":"Potato picadillo with ground beef","porciones":2}},"pollo-asado-brocoli-jengibre":{"es":{"ingredientes":["4 muslos de pollo","2 tazas de brócoli en ramitos","1 cda de jengibre rallado","3 dientes de ajo picados","1 limón","2 cdas de aceite","sal y pimienta al gusto"],"pasos":["Caliente el horno a 200 °C. Mezcle el jengibre, el ajo, el limón, el aceite y la sal.","Unte el pollo con la mezcla y colóquelo en una bandeja.","Hornee 25 minutos, agregue el brócoli y hornee 15 minutos más."],"titulo":"Pollo asado con brócoli y jengibre","porciones":2},"en":{"ingredientes":["4 chicken thighs","2 cups broccoli florets","1 tbsp grated ginger","3 garlic cloves, minced","1 lemon","2 tbsp oil","salt and pepper to taste"],"pasos":["Heat the oven to 200 °C. Mix the ginger, garlic, lemon, oil and salt.","Coat the chicken with the mixture and place on a tray.","Bake 25 minutes, add the broccoli and bake 15 more minutes."],"titulo":"Roast chicken with broccoli and ginger","porciones":2}},"pollo-horno-hierbas":{"es":{"ingredientes":["1 pollo pequeño en piezas (1 kg)","3 dientes de ajo picados","1 cda de romero","1 cda de tomillo","2 limones","3 cdas de aceite de oliva","2 papas en trozos","sal y pimienta al gusto"],"pasos":["Caliente el horno a 200 °C. Mezcle el ajo, las hierbas, el jugo de un limón, el aceite y la sal.","Unte el pollo y colóquelo en una bandeja con las papas.","Agregue el otro limón en rodajas y hornee 50 minutos.","Deje reposar 5 minutos antes de servir."],"titulo":"Pollo al horno con hierbas","porciones":4},"en":{"ingredientes":["1 small chicken in pieces (1 kg)","3 garlic cloves, minced","1 tbsp rosemary","1 tbsp thyme","2 lemons","3 tbsp olive oil","2 potatoes, chunked","salt and pepper to taste"],"pasos":["Heat the oven to 200 °C. Mix the garlic, herbs, the juice of one lemon, oil and salt.","Coat the chicken and place on a tray with the potatoes.","Add the other lemon in slices and bake for 50 minutes.","Rest 5 minutes before serving."],"titulo":"Herb-roasted chicken","porciones":4}},"pollo-tikka-masala":{"es":{"ingredientes":["400 g de pechuga de pollo en cubos","1/2 taza de yogur natural","2 cdtas de paprika","1 cdta de comino","1 cdta de cúrcuma","1 cebolla picada","3 dientes de ajo picados","1 taza de tomate triturado","1 cda de jengibre rallado","1 cda de aceite"],"pasos":["Marine el pollo 30 minutos con el yogur, la mitad de las especias y sal.","Dore el pollo en una sartén con aceite y apártelo.","Sofría la cebolla, el ajo y el jengibre; agregue las especias restantes y el tomate; cocine 10 minutos.","Regrese el pollo y cocine 15 minutos a fuego bajo."],"titulo":"Pollo tikka masala","porciones":2},"en":{"ingredientes":["400 g chicken breast, cubed","1/2 cup plain yogurt","2 tsp paprika","1 tsp cumin","1 tsp turmeric","1 onion, chopped","3 garlic cloves, minced","1 cup crushed tomatoes","1 tbsp grated ginger","1 tbsp oil"],"pasos":["Marinate the chicken for 30 minutes with the yogurt, half the spices and salt.","Brown the chicken in a pan with oil and set aside.","Sauté the onion, garlic and ginger; add the remaining spices and the tomato; cook 10 minutes.","Return the chicken and simmer for 15 minutes."],"titulo":"Chicken tikka masala","porciones":2}},"pollo-vegetales-vapor":{"es":{"ingredientes":["2 pechugas de pollo","1 taza de brócoli","1 zanahoria en rodajas","1 zucchini en rodajas","1 cdta de jengibre rallado","1 diente de ajo picado","1 cda de aceite","sal al gusto"],"pasos":["Sazone el pollo con sal, jengibre y ajo.","Cocine el pollo al vapor 20 minutos.","Agregue los vegetales a la vaporera los últimos 8 minutos.","Sirva con un chorrito de aceite."],"titulo":"Pollo con vegetales al vapor","porciones":2},"en":{"ingredientes":["2 chicken breasts","1 cup broccoli","1 carrot, sliced","1 zucchini, sliced","1 tsp grated ginger","1 garlic clove, minced","1 tbsp oil","salt to taste"],"pasos":["Season the chicken with salt, ginger and garlic.","Steam the chicken for 20 minutes.","Add the vegetables to the steamer for the last 8 minutes.","Serve with a drizzle of oil."],"titulo":"Chicken with steamed vegetables","porciones":2}},"quinoa-vegetales-asados":{"es":{"ingredientes":["1 taza de quinoa","2 tazas de agua","1 zucchini en cubos","1 chile dulce en cubos","1 berenjena pequeña en cubos","1 cebolla en gajos","2 cdas de aceite de oliva","1 limón","sal al gusto"],"pasos":["Caliente el horno a 210 °C. Mezcle los vegetales con aceite y sal en una bandeja.","Hornee 25 minutos, volteando a la mitad.","Cocine la quinoa lavada en el agua con sal 15 minutos.","Mezcle la quinoa con los vegetales y el jugo de limón."],"titulo":"Quinoa con vegetales asados","porciones":2},"en":{"ingredientes":["1 cup quinoa","2 cups water","1 zucchini, cubed","1 sweet pepper, cubed","1 small eggplant, cubed","1 onion, in wedges","2 tbsp olive oil","1 lemon","salt to taste"],"pasos":["Heat the oven to 210 °C. Toss the vegetables with oil and salt on a tray.","Roast 25 minutes, turning halfway.","Cook the rinsed quinoa in the salted water for 15 minutes.","Mix the quinoa with the vegetables and lemon juice."],"titulo":"Quinoa with roasted vegetables","porciones":2}},"ramen-verduras":{"es":{"ingredientes":["2 porciones de fideos de ramen","4 tazas de caldo de verduras","1 cda de miso","1 cda de salsa de soya","1 taza de hongos en láminas","1 zanahoria en tiras","1 taza de espinacas","1 cebollino picado","1 cdta de jengibre rallado"],"pasos":["Hierva el caldo con el jengibre, los hongos y la zanahoria 8 minutos.","Cocine los fideos aparte según el paquete y escúrralos.","Disuelva el miso y la salsa de soya en un poco de caldo y devuélvalo a la olla.","Sirva los fideos con el caldo, las espinacas y el cebollino."],"titulo":"Ramen de verduras","porciones":2},"en":{"ingredientes":["2 portions ramen noodles","4 cups vegetable broth","1 tbsp miso","1 tbsp soy sauce","1 cup sliced mushrooms","1 carrot, in strips","1 cup spinach","1 scallion, chopped","1 tsp grated ginger"],"pasos":["Simmer the broth with the ginger, mushrooms and carrot for 8 minutes.","Cook the noodles separately as directed and drain.","Dissolve the miso and soy sauce in a little broth and return it to the pot.","Serve the noodles with the broth, spinach and scallion."],"titulo":"Vegetable ramen","porciones":2}},"res-plancha-vegetales":{"es":{"ingredientes":["2 bistecs de res (300 g)","1 zucchini en rodajas","1 chile dulce en tiras","1 cebolla en aros","2 dientes de ajo picados","1 cda de aceite","sal y pimienta al gusto"],"pasos":["Sazone la carne con sal, pimienta y ajo.","Cocine en una plancha caliente con aceite 3 a 4 minutos por lado; deje reposar.","En la misma plancha ase el zucchini, el chile dulce y la cebolla 6 minutos.","Sirva la carne con los vegetales."],"titulo":"Res a la plancha con vegetales","porciones":2},"en":{"ingredientes":["2 beef steaks (300 g)","1 zucchini, sliced","1 sweet pepper, sliced","1 onion, in rings","2 garlic cloves, minced","1 tbsp oil","salt and pepper to taste"],"pasos":["Season the meat with salt, pepper and garlic.","Cook on a hot griddle with oil 3 to 4 minutes per side; let rest.","On the same griddle grill the zucchini, sweet pepper and onion for 6 minutes.","Serve the meat with the vegetables."],"titulo":"Grilled beef with vegetables","porciones":2}},"risotto-cebada-hongos":{"es":{"ingredientes":["1 taza de cebada perlada","250 g de hongos en láminas","3 tazas de caldo de verduras caliente","1/2 cebolla picada","2 dientes de ajo picados","2 cdas de aceite de oliva","2 cdas de perejil picado","sal y pimienta al gusto"],"pasos":["Saltee los hongos en 1 cda de aceite hasta que doren y apártelos.","Sofría la cebolla y el ajo en el aceite restante; agregue la cebada y revuelva 2 minutos.","Agregue el caldo de a poco y cocine 35 minutos revolviendo de vez en cuando.","Mezcle con los hongos, sazone y adorne con perejil."],"titulo":"Risotto de cebada con hongos","porciones":2},"en":{"ingredientes":["1 cup pearl barley","250 g sliced mushrooms","3 cups hot vegetable broth","1/2 onion, chopped","2 garlic cloves, minced","2 tbsp olive oil","2 tbsp chopped parsley","salt and pepper to taste"],"pasos":["Sauté the mushrooms in 1 tbsp oil until browned and set aside.","Sauté the onion and garlic in the remaining oil; add the barley and stir for 2 minutes.","Add the broth gradually and cook 35 minutes, stirring occasionally.","Fold in the mushrooms, season and garnish with parsley."],"titulo":"Barley risotto with mushrooms","porciones":2}},"salmon-horno-vegetales":{"es":{"ingredientes":["2 filetes de salmón (300 g)","1 taza de brócoli","1 zanahoria en rodajas","1 zucchini en rodajas","2 cdas de aceite de oliva","1 limón","sal y pimienta al gusto"],"pasos":["Caliente el horno a 200 °C. Mezcle los vegetales con la mitad del aceite y sal en una bandeja.","Hornee 10 minutos.","Agregue el salmón con sal, pimienta, aceite y limón; hornee 12 a 15 minutos."],"titulo":"Salmón al horno con vegetales","porciones":2},"en":{"ingredientes":["2 salmon fillets (300 g)","1 cup broccoli","1 carrot, sliced","1 zucchini, sliced","2 tbsp olive oil","1 lemon","salt and pepper to taste"],"pasos":["Heat the oven to 200 °C. Toss the vegetables with half the oil and salt on a tray.","Roast for 10 minutes.","Add the salmon with salt, pepper, oil and lemon; bake 12 to 15 minutes."],"titulo":"Baked salmon with vegetables","porciones":2}},"sopa-frijoles-negros":{"es":{"ingredientes":["2 tazas de frijoles negros cocidos","3 tazas de caldo de verduras","1 cebolla picada","1 chile dulce picado","3 dientes de ajo picados","1 cdta de comino","1 cda de aceite","2 cdas de culantro picado"],"pasos":["Sofría la cebolla, el chile dulce y el ajo en aceite; agregue el comino.","Agregue los frijoles y el caldo y cocine 20 minutos.","Triture una parte con un tenedor o licuadora para espesar.","Sazone y sirva con culantro."],"titulo":"Sopa de frijoles negros","porciones":4},"en":{"ingredientes":["2 cups cooked black beans","3 cups vegetable broth","1 onion, chopped","1 sweet pepper, chopped","3 garlic cloves, minced","1 tsp cumin","1 tbsp oil","2 tbsp chopped culantro"],"pasos":["Sauté the onion, sweet pepper and garlic in oil; add the cumin.","Add the beans and broth and cook 20 minutes.","Mash or blend part of it to thicken.","Season and serve with culantro."],"titulo":"Black bean soup","porciones":4}},"sopa-garbanzos":{"es":{"ingredientes":["2 tazas de garbanzos cocidos","4 tazas de caldo de verduras","1 zanahoria en cubos","1 papa en cubos","1/2 cebolla picada","2 dientes de ajo picados","1 taza de espinacas","1 cda de aceite de oliva"],"pasos":["Sofría la cebolla y el ajo en aceite.","Agregue la zanahoria, la papa, los garbanzos y el caldo; cocine 25 minutos.","Agregue las espinacas los últimos 3 minutos y sazone."],"titulo":"Sopa de garbanzos","porciones":4},"en":{"ingredientes":["2 cups cooked chickpeas","4 cups vegetable broth","1 carrot, diced","1 potato, diced","1/2 onion, chopped","2 garlic cloves, minced","1 cup spinach","1 tbsp olive oil"],"pasos":["Sauté the onion and garlic in oil.","Add the carrot, potato, chickpeas and broth; cook 25 minutes.","Add the spinach for the last 3 minutes and season."],"titulo":"Chickpea soup","porciones":4}},"sopa-lentejas-vegetales":{"es":{"ingredientes":["1 taza de lentejas","5 tazas de agua o caldo de verduras","1 zanahoria en cubos","1 papa en cubos","1 tallo de apio picado","1/2 cebolla picada","2 dientes de ajo picados","1 cda de aceite"],"pasos":["Sofría la cebolla, el ajo y el apio en aceite.","Agregue las lentejas lavadas, la zanahoria, la papa y el agua.","Hierva, baje el fuego y cocine tapado 35 minutos.","Sazone con sal y sirva."],"titulo":"Sopa de lentejas con vegetales","porciones":4},"en":{"ingredientes":["1 cup lentils","5 cups water or vegetable broth","1 carrot, diced","1 potato, diced","1 celery stalk, chopped","1/2 onion, chopped","2 garlic cloves, minced","1 tbsp oil"],"pasos":["Sauté the onion, garlic and celery in oil.","Add the rinsed lentils, carrot, potato and water.","Bring to a boil, reduce the heat and cook covered for 35 minutes.","Season with salt and serve."],"titulo":"Lentil soup with vegetables","porciones":4}},"sopa-lentejas":{"es":{"ingredientes":["1 1/2 tazas de lentejas","6 tazas de agua","1 cebolla picada","2 dientes de ajo picados","1 tomate picado","1 cdta de comino","1 cda de aceite","1 limón"],"pasos":["Sofría la cebolla, el ajo y el comino en aceite; agregue el tomate.","Agregue las lentejas lavadas y el agua.","Cocine tapado a fuego bajo 40 minutos.","Sazone con sal y jugo de limón."],"titulo":"Sopa de lentejas","porciones":4},"en":{"ingredientes":["1 1/2 cups lentils","6 cups water","1 onion, chopped","2 garlic cloves, minced","1 tomato, chopped","1 tsp cumin","1 tbsp oil","1 lemon"],"pasos":["Sauté the onion, garlic and cumin in oil; add the tomato.","Add the rinsed lentils and water.","Cook covered over low heat for 40 minutes.","Season with salt and lemon juice."],"titulo":"Lentil soup","porciones":4}},"sopa-negra-costarricense":{"es":{"ingredientes":["2 tazas de frijoles negros cocidos con su caldo","3 tazas de agua","1/2 cebolla picada","1/2 chile dulce picado","3 dientes de ajo picados","1/4 de taza de culantro picado","4 huevos","1 cda de aceite"],"pasos":["Sofría la cebolla, el chile dulce y el ajo en aceite.","Agregue los frijoles con su caldo y el agua; cocine 25 minutos.","Licúe una parte para espesar, sazone y agregue el culantro.","Escalfe un huevo en cada plato con la sopa caliente."],"titulo":"Sopa negra costarricense con huevo","porciones":4},"en":{"ingredientes":["2 cups cooked black beans with their broth","3 cups water","1/2 onion, chopped","1/2 sweet pepper, chopped","3 garlic cloves, minced","1/4 cup chopped culantro","4 eggs","1 tbsp oil"],"pasos":["Sauté the onion, sweet pepper and garlic in oil.","Add the beans with their broth and the water; cook 25 minutes.","Blend part of it to thicken, season and add the culantro.","Poach one egg in each bowl with the hot soup."],"titulo":"Costa Rican black bean soup with egg","porciones":4}},"sopa-pollo-vegetales":{"es":{"ingredientes":["500 g de pollo en piezas","8 tazas de agua","1 papa en trozos","2 zanahorias en rodajas","1 chayote en trozos","1 tallo de apio","1/2 cebolla","1/4 de taza de culantro"],"pasos":["Cocine el pollo con la cebolla, el apio y sal en el agua 25 minutos.","Agregue la papa, la zanahoria y el chayote; cocine 20 minutos.","Sirva con culantro picado."],"titulo":"Sopa de pollo con vegetales","porciones":4},"en":{"ingredientes":["500 g chicken pieces","8 cups water","1 potato, chunked","2 carrots, sliced","1 chayote, chunked","1 celery stalk","1/2 onion","1/4 cup culantro"],"pasos":["Cook the chicken with the onion, celery and salt in the water for 25 minutes.","Add the potato, carrot and chayote; cook 20 minutes.","Serve with chopped culantro."],"titulo":"Chicken soup with vegetables","porciones":4}},"sopa-vegetales-lentejas":{"es":{"ingredientes":["1 taza de lentejas","6 tazas de agua o caldo de verduras","1 zanahoria en cubos","1 chayote en cubos","1 papa en cubos","1 tomate picado","1/2 cebolla picada","1 cda de aceite"],"pasos":["Sofría la cebolla y el tomate en aceite.","Agregue las lentejas lavadas y el agua; hierva y cocine 20 minutos.","Agregue la zanahoria, el chayote y la papa; cocine 20 minutos más.","Sazone con sal y sirva."],"titulo":"Sopa de vegetales y lentejas","porciones":4},"en":{"ingredientes":["1 cup lentils","6 cups water or vegetable broth","1 carrot, diced","1 chayote, diced","1 potato, diced","1 tomato, chopped","1/2 onion, chopped","1 tbsp oil"],"pasos":["Sauté the onion and tomato in oil.","Add the rinsed lentils and water; boil and cook 20 minutes.","Add the carrot, chayote and potato; cook 20 more minutes.","Season with salt and serve."],"titulo":"Vegetable and lentil soup","porciones":4}},"sushi-pescado":{"es":{"ingredientes":["1 taza de arroz para sushi","1 1/4 tazas de agua","150 g de pescado fresco para sushi","3 hojas de alga nori","1/2 pepino en tiras","1/2 aguacate en láminas","2 cdas de vinagre de arroz","1 cdta de azúcar","2 cdas de salsa de soya","1 cda de semillas de ajonjolí"],"pasos":["Cocine el arroz en el agua; mezcle con el vinagre, el azúcar y una pizca de sal; deje enfriar.","Coloque media hoja de nori sobre una esterilla y extienda una capa fina de arroz.","Agregue tiras de pescado, pepino y aguacate; enrolle con firmeza.","Corte en trozos, espolvoree el ajonjolí y sirva con la salsa de soya."],"titulo":"Sushi de pescado","porciones":2},"en":{"ingredientes":["1 cup sushi rice","1 1/4 cups water","150 g sushi-grade fish","3 nori sheets","1/2 cucumber, in strips","1/2 avocado, sliced","2 tbsp rice vinegar","1 tsp sugar","2 tbsp soy sauce","1 tbsp sesame seeds"],"pasos":["Cook the rice in the water; mix with the vinegar, sugar and a pinch of salt; let cool.","Place half a nori sheet on a mat and spread a thin layer of rice.","Add strips of fish, cucumber and avocado; roll tightly.","Cut into pieces, sprinkle with sesame seeds and serve with soy sauce."],"titulo":"Fish sushi","porciones":2}},"tacos-frijoles":{"es":{"ingredientes":["6 tortillas de maíz pequeñas","1 1/2 tazas de frijoles negros cocidos","1 tomate picado","1/4 de cebolla picada","1/2 aguacate","2 cdas de culantro picado","1 limón"],"pasos":["Caliente y triture un poco los frijoles con sal y comino.","Caliente las tortillas en una sartén seca.","Rellene con frijoles, tomate, cebolla y aguacate.","Termine con culantro y limón."],"titulo":"Tacos de frijoles","porciones":2},"en":{"ingredientes":["6 small corn tortillas","1 1/2 cups cooked black beans","1 tomato, chopped","1/4 onion, chopped","1/2 avocado","2 tbsp chopped culantro","1 lime"],"pasos":["Warm and lightly mash the beans with salt and cumin.","Warm the tortillas in a dry pan.","Fill with beans, tomato, onion and avocado.","Finish with culantro and lime."],"titulo":"Bean tacos","porciones":2}},"tacos-vegetarianos":{"es":{"ingredientes":["6 tortillas de maíz pequeñas","1 zucchini en cubos","1 chile dulce en tiras","1/2 taza de maíz","1/2 cebolla en tiras","1 aguacate","1 cda de aceite","1 limón","sal al gusto"],"pasos":["Saltee la cebolla, el chile dulce y el zucchini en aceite 6 minutos.","Agregue el maíz y sal; cocine 2 minutos.","Caliente las tortillas y rellene con los vegetales.","Sirva con aguacate y limón."],"titulo":"Tacos de vegetales salteados","porciones":2},"en":{"ingredientes":["6 small corn tortillas","1 zucchini, diced","1 sweet pepper, sliced","1/2 cup corn","1/2 onion, sliced","1 avocado","1 tbsp oil","1 lime","salt to taste"],"pasos":["Sauté the onion, sweet pepper and zucchini in oil for 6 minutes.","Add the corn and salt; cook for 2 minutes.","Warm the tortillas and fill with the vegetables.","Serve with avocado and lime."],"titulo":"Sautéed vegetable tacos","porciones":2}},"tempeh-vegetales-asados":{"es":{"ingredientes":["200 g de tempeh en cubos","1 brócoli pequeño en ramitos","1 zanahoria en rodajas","1 chile dulce en cubos","2 dientes de ajo picados","1 cdta de jengibre rallado","2 cdas de aceite","1 limón"],"pasos":["Caliente el horno a 200 °C. Mezcle el tempeh y los vegetales con el aceite, el ajo, el jengibre y sal.","Extienda en una bandeja y hornee 25 minutos, volteando a la mitad.","Sirva con jugo de limón."],"titulo":"Tempeh con vegetales asados","porciones":2},"en":{"ingredientes":["200 g tempeh, cubed","1 small broccoli, in florets","1 carrot, sliced","1 sweet pepper, cubed","2 garlic cloves, minced","1 tsp grated ginger","2 tbsp oil","1 lime"],"pasos":["Heat the oven to 200 °C. Toss the tempeh and vegetables with the oil, garlic, ginger and salt.","Spread on a tray and roast 25 minutes, turning halfway.","Serve with lime juice."],"titulo":"Tempeh with roasted vegetables","porciones":2}},"tofu-salteado-vegetales-2":{"es":{"ingredientes":["250 g de tofu firme en cubos","2 tazas de brócoli","1 zanahoria en rodajas finas","2 dientes de ajo picados","1 cdta de jengibre rallado","1 cda de aceite","1 limón","sal al gusto"],"pasos":["Seque el tofu y fríalo en aceite caliente hasta que tome color; apártelo.","Saltee el ajo y el jengibre 30 segundos; agregue la zanahoria y el brócoli 5 minutos.","Regrese el tofu, sazone con sal y limón."],"titulo":"Tofu salteado con brócoli y zanahoria","porciones":2},"en":{"ingredientes":["250 g firm tofu, cubed","2 cups broccoli","1 carrot, thinly sliced","2 garlic cloves, minced","1 tsp grated ginger","1 tbsp oil","1 lemon","salt to taste"],"pasos":["Pat the tofu dry and brown in hot oil until golden; set aside.","Stir-fry the garlic and ginger for 30 seconds; add the carrot and broccoli for 5 minutes.","Return the tofu and season with salt and lemon."],"titulo":"Stir-fried tofu with broccoli and carrot","porciones":2}},"tofu-salteado-vegetales":{"es":{"ingredientes":["200 g de tofu firme","1 chile dulce en tiras","1 taza de brócoli","1 zanahoria","1 diente de ajo picado","1 cda de aceite","sal al gusto"],"pasos":["Dore el tofu en cubos en aceite.","Agregue el ajo y los vegetales y saltee 6 minutos.","Sazone con sal y sirva."],"titulo":"Tofu salteado con vegetales","porciones":2},"en":{"ingredientes":["200 g firm tofu","1 sweet pepper, sliced","1 cup broccoli","1 carrot","1 garlic clove, minced","1 tbsp oil","salt to taste"],"pasos":["Brown the cubed tofu in oil.","Add the garlic and vegetables and stir-fry for 6 minutes.","Season with salt and serve."],"titulo":"Stir-fried tofu with vegetables","porciones":2}},"tostadas-integrales-aguacate-huevo":{"es":{"ingredientes":["4 rebanadas de pan integral","1 aguacate","2 huevos","1/2 limón","1 cdta de aceite","sal y pimienta al gusto"],"pasos":["Tueste el pan.","Triture el aguacate con limón y sal y unte sobre las tostadas.","Fría o escalfe los huevos y colóquelos encima.","Termine con pimienta."],"titulo":"Tostadas integrales con aguacate y huevo","porciones":2},"en":{"ingredientes":["4 slices of whole-grain bread","1 avocado","2 eggs","1/2 lemon","1 tsp oil","salt and pepper to taste"],"pasos":["Toast the bread.","Mash the avocado with lemon and salt and spread on the toast.","Fry or poach the eggs and place on top.","Finish with pepper."],"titulo":"Whole-grain toast with avocado and egg","porciones":2}},"tostadas-integrales-aguacate":{"es":{"ingredientes":["4 rebanadas de pan integral","1 aguacate maduro","1/2 limón","1 tomate en rodajas","sal y pimienta al gusto"],"pasos":["Tueste el pan.","Triture el aguacate con limón, sal y pimienta.","Unte sobre las tostadas y agregue el tomate."],"titulo":"Tostadas integrales con aguacate","porciones":2},"en":{"ingredientes":["4 slices of whole-grain bread","1 ripe avocado","1/2 lemon","1 tomato, sliced","salt and pepper to taste"],"pasos":["Toast the bread.","Mash the avocado with lemon, salt and pepper.","Spread on the toast and top with tomato."],"titulo":"Whole-grain avocado toast","porciones":2}},"yakisoba-vegetales":{"es":{"ingredientes":["200 g de fideos para yakisoba","2 tazas de repollo en tiras","1 zanahoria en tiras","1 chile dulce en tiras","1/2 cebolla en tiras","3 cdas de salsa de soya","1 cdta de jengibre rallado","1 cda de aceite"],"pasos":["Cocine los fideos según el paquete y escúrralos.","Saltee la cebolla, la zanahoria, el chile dulce y el jengibre en aceite 4 minutos.","Agregue el repollo y cocine 2 minutos.","Agregue los fideos y la salsa de soya; mezcle 2 minutos y sirva."],"titulo":"Yakisoba de vegetales","porciones":2},"en":{"ingredientes":["200 g yakisoba noodles","2 cups shredded cabbage","1 carrot, in strips","1 sweet pepper, sliced","1/2 onion, sliced","3 tbsp soy sauce","1 tsp grated ginger","1 tbsp oil"],"pasos":["Cook the noodles as directed and drain.","Stir-fry the onion, carrot, sweet pepper and ginger in oil for 4 minutes.","Add the cabbage and cook 2 minutes.","Add the noodles and soy sauce; toss for 2 minutes and serve."],"titulo":"Vegetable yakisoba","porciones":2}},"casado-vegetariano":{"es":{"ingredientes":["1 taza de arroz cocido","1 taza de frijoles negros cocidos","2 plátanos maduros","1 chayote en cubos","1 tomate en rodajas","2 hojas de lechuga","1 zanahoria rallada","2 cdas de aceite"],"pasos":["Cocine el chayote en cubos con un poco de aceite, cebolla y sal por 12 minutos.","Fría los plátanos en rodajas hasta que doren.","Caliente los frijoles y el arroz.","Sirva todo con la ensalada de tomate, lechuga y zanahoria."],"titulo":"Casado vegetariano con plátano maduro","porciones":2},"en":{"ingredientes":["1 cup cooked rice","1 cup cooked black beans","2 ripe plantains","1 chayote, diced","1 tomato, sliced","2 lettuce leaves","1 carrot, grated","2 tbsp oil"],"pasos":["Cook the diced chayote with a little oil, onion and salt for 12 minutes.","Fry the plantain slices until golden.","Warm the beans and rice.","Serve everything with the tomato, lettuce and carrot salad."],"titulo":"Vegetarian casado with ripe plantain","porciones":2}},"arroz-frito-huevo-vegetales":{"es":{"ingredientes":["2 tazas de arroz cocido (frío)","2 huevos","1/2 taza de arvejas","1 zanahoria picada","2 cdas de aceite","2 cdas de salsa de soya","1 cebollino picado"],"pasos":["Revuelva los huevos en una sartén y apártelos.","Saltee la zanahoria y las arvejas en aceite 4 minutos.","Agregue el arroz y la salsa de soya y mezcle 3 minutos.","Incorpore el huevo y el cebollino."],"titulo":"Arroz frito con huevo y vegetales","porciones":2},"en":{"ingredientes":["2 cups cooked rice (cold)","2 eggs","1/2 cup peas","1 carrot, chopped","2 tbsp oil","2 tbsp soy sauce","1 scallion, chopped"],"pasos":["Scramble the eggs in a pan and set aside.","Stir-fry the carrot and peas in oil for 4 minutes.","Add the rice and soy sauce and toss for 3 minutes.","Fold in the egg and scallion."],"titulo":"Egg fried rice with vegetables","porciones":2}},"curry-vegetales-arroz":{"es":{"ingredientes":["1 taza de arroz","1 papa en cubos","1 zanahoria en rodajas","1 taza de coliflor","1/2 taza de arvejas","1 taza de leche de coco","1 cda de curry en polvo","1/2 cebolla picada","1 cda de aceite"],"pasos":["Cocine el arroz según el paquete.","Sofría la cebolla con el curry en aceite.","Agregue los vegetales y la leche de coco con 1/2 taza de agua; cocine 20 minutos.","Sazone con sal y sirva sobre el arroz."],"titulo":"Curry de vegetales con arroz","porciones":2},"en":{"ingredientes":["1 cup rice","1 potato, cubed","1 carrot, sliced","1 cup cauliflower","1/2 cup peas","1 cup coconut milk","1 tbsp curry powder","1/2 onion, chopped","1 tbsp oil"],"pasos":["Cook the rice as directed.","Sauté the onion with the curry powder in oil.","Add the vegetables and coconut milk with 1/2 cup water; cook 20 minutes.","Season with salt and serve over the rice."],"titulo":"Vegetable curry with rice","porciones":2}},"bowl-arroz-aguacate-pepino":{"es":{"ingredientes":["1 1/2 tazas de arroz cocido","1 aguacate","1 pepino","1 zanahoria rallada","1 cda de aceite de oliva","1 limón","sal al gusto"],"pasos":["Divida el arroz en dos bowls.","Agregue el aguacate y el pepino en láminas y la zanahoria.","Aliñe con aceite, limón y sal."],"titulo":"Bowl de arroz con aguacate y pepino","porciones":2},"en":{"ingredientes":["1 1/2 cups cooked rice","1 avocado","1 cucumber","1 carrot, grated","1 tbsp olive oil","1 lime","salt to taste"],"pasos":["Divide the rice between two bowls.","Add the sliced avocado and cucumber and the carrot.","Dress with oil, lime and salt."],"titulo":"Rice bowl with avocado and cucumber","porciones":2}},"platano-maduro-horno-frijoles":{"es":{"ingredientes":["2 plátanos maduros","1 taza de frijoles negros cocidos","1/2 aguacate","1 tomate picado","1 cda de aceite","1/4 de cebolla picada","sal al gusto"],"pasos":["Caliente el horno a 200 °C. Corte los plátanos en rodajas largas y pincele con aceite.","Hornee 25 minutos, volteando a la mitad.","Caliente los frijoles con la cebolla y sal.","Sirva los plátanos con los frijoles, el tomate y el aguacate."],"titulo":"Plátano maduro al horno con frijoles","porciones":2},"en":{"ingredientes":["2 ripe plantains","1 cup cooked black beans","1/2 avocado","1 tomato, chopped","1 tbsp oil","1/4 onion, chopped","salt to taste"],"pasos":["Heat the oven to 200 °C. Slice the plantains lengthwise and brush with oil.","Bake 25 minutes, turning halfway.","Warm the beans with the onion and salt.","Serve the plantains with the beans, tomato and avocado."],"titulo":"Baked ripe plantain with beans","porciones":2}},"huevos-revueltos-vegetales":{"es":{"ingredientes":["4 huevos","1 tomate picado","1/4 de chile dulce picado","1/4 de cebolla picada","2 cdas de culantro picado","1 cda de aceite","sal al gusto"],"pasos":["Saltee la cebolla, el chile dulce y el tomate en aceite 3 minutos.","Agregue los huevos batidos con sal.","Revuelva a fuego medio hasta que cuajen.","Termine con culantro."],"titulo":"Huevos revueltos con vegetales","porciones":2},"en":{"ingredientes":["4 eggs","1 tomato, chopped","1/4 sweet pepper, chopped","1/4 onion, chopped","2 tbsp chopped culantro","1 tbsp oil","salt to taste"],"pasos":["Sauté the onion, sweet pepper and tomato in oil for 3 minutes.","Add the eggs beaten with salt.","Stir over medium heat until set.","Finish with culantro."],"titulo":"Scrambled eggs with vegetables","porciones":2}},"tortillas-maiz-frijoles-aguacate":{"es":{"ingredientes":["4 tortillas de maíz","1 taza de frijoles negros cocidos","1 aguacate","1 limón","sal al gusto"],"pasos":["Caliente las tortillas y los frijoles.","Sirva los frijoles sobre las tortillas con el aguacate en láminas.","Agregue unas gotas de limón y sal."],"titulo":"Tortillas de maíz con frijoles y aguacate","porciones":2},"en":{"ingredientes":["4 corn tortillas","1 cup cooked black beans","1 avocado","1 lime","salt to taste"],"pasos":["Warm the tortillas and beans.","Top the tortillas with beans and sliced avocado.","Add a squeeze of lime and salt."],"titulo":"Corn tortillas with beans and avocado","porciones":2}},"pollo-arroz-vegetales-vapor":{"es":{"ingredientes":["2 pechugas de pollo","1 taza de arroz","1 taza de brócoli","1 zanahoria en rodajas","100 g de vainicas","1 cdta de sal","1 cda de aceite de oliva"],"pasos":["Cocine el arroz en el doble de agua con sal.","Cocine al vapor el brócoli, la zanahoria y las vainicas 8 minutos.","Dore las pechugas en una sartén con aceite, 6 minutos por lado.","Sirva el pollo con el arroz y los vegetales."],"titulo":"Pollo a la plancha con arroz y vegetales al vapor","porciones":2},"en":{"ingredientes":["2 chicken breasts","1 cup rice","1 cup broccoli","1 carrot, sliced","100 g green beans","1 tsp salt","1 tbsp olive oil"],"pasos":["Cook the rice in twice its volume of salted water.","Steam the broccoli, carrot and green beans for 8 minutes.","Brown the chicken in a pan with oil, 6 minutes per side.","Serve the chicken with the rice and vegetables."],"titulo":"Grilled chicken with rice and steamed vegetables","porciones":2}},"frijoles-molidos-tortilla-queso":{"es":{"ingredientes":["1 1/2 tazas de frijoles negros cocidos","4 tortillas de maíz","100 g de queso fresco","1/4 de cebolla picada","1 diente de ajo picado","1 cda de aceite"],"pasos":["Sofría la cebolla y el ajo en aceite.","Agregue los frijoles y tritúrelos hasta obtener un puré; cocine 5 minutos.","Caliente las tortillas y unte los frijoles.","Agregue el queso en láminas o desmenuzado."],"titulo":"Frijoles molidos con tortilla y queso","porciones":2},"en":{"ingredientes":["1 1/2 cups cooked black beans","4 corn tortillas","100 g fresh cheese","1/4 onion, chopped","1 garlic clove, minced","1 tbsp oil"],"pasos":["Sauté the onion and garlic in oil.","Add the beans and mash into a purée; cook 5 minutes.","Warm the tortillas and spread with the beans.","Top with sliced or crumbled cheese."],"titulo":"Refried beans with tortilla and cheese","porciones":2}},"yuca-ensalada-repollo-frijoles":{"es":{"ingredientes":["500 g de yuca en trozos","2 tazas de repollo en tiras","1 zanahoria rallada","1 taza de frijoles negros cocidos","1 limón","1 cda de aceite","sal al gusto"],"pasos":["Cocine la yuca en agua con sal 25 minutos hasta que esté suave; escurra.","Mezcle el repollo y la zanahoria con limón, aceite y sal.","Caliente los frijoles.","Sirva la yuca con la ensalada y los frijoles."],"titulo":"Yuca con ensalada de repollo y frijoles","porciones":2},"en":{"ingredientes":["500 g cassava, chunked","2 cups shredded cabbage","1 carrot, grated","1 cup cooked black beans","1 lime","1 tbsp oil","salt to taste"],"pasos":["Boil the cassava in salted water for 25 minutes until tender; drain.","Toss the cabbage and carrot with lime, oil and salt.","Warm the beans.","Serve the cassava with the salad and beans."],"titulo":"Cassava with cabbage salad and beans","porciones":2}},"chayote-relleno-queso-fresco":{"es":{"ingredientes":["2 chayotes","150 g de queso fresco desmenuzado","1/4 de cebolla picada","1/2 tomate picado","2 cdas de culantro picado","1 cda de aceite","sal al gusto"],"pasos":["Cocine los chayotes enteros en agua con sal 25 minutos; córtelos por la mitad y retire la semilla.","Saque parte de la pulpa y mézclela con el queso, la cebolla sofrita, el tomate y el culantro.","Rellene los chayotes y gratine en el horno 10 minutos a 200 °C."],"titulo":"Chayote relleno de queso fresco","porciones":2},"en":{"ingredientes":["2 chayotes","150 g crumbled fresh cheese","1/4 onion, chopped","1/2 tomato, chopped","2 tbsp chopped culantro","1 tbsp oil","salt to taste"],"pasos":["Boil the chayotes whole in salted water for 25 minutes; halve and remove the seed.","Scoop out some flesh and mix with the cheese, sautéed onion, tomato and culantro.","Fill the chayotes and bake 10 minutes at 200 °C."],"titulo":"Chayote stuffed with fresh cheese","porciones":2}},"pescado-ajillo-arroz":{"es":{"ingredientes":["2 filetes de pescado (300 g)","5 dientes de ajo en láminas","1 taza de arroz","2 cdas de aceite de oliva","1 limón","2 cdas de perejil picado","sal al gusto"],"pasos":["Cocine el arroz según el paquete.","Dore el ajo en el aceite a fuego bajo sin que se queme; retírelo.","Cocine el pescado con sal en el mismo aceite 4 minutos por lado.","Sirva con el ajo, limón, perejil y el arroz."],"titulo":"Pescado al ajillo con arroz","porciones":2},"en":{"ingredientes":["2 fish fillets (300 g)","5 garlic cloves, sliced","1 cup rice","2 tbsp olive oil","1 lemon","2 tbsp chopped parsley","salt to taste"],"pasos":["Cook the rice as directed.","Gently brown the garlic in the oil over low heat without burning; remove.","Cook the fish with salt in the same oil, 4 minutes per side.","Serve with the garlic, lemon, parsley and rice."],"titulo":"Garlic fish with rice","porciones":2}},"avena-frutas-nueces":{"es":{"ingredientes":["1/2 taza de avena en hojuelas","1 taza de agua","1 banano en rodajas","1/2 taza de fresas o papaya en cubos","2 cdas de nueces","1 cdta de miel","1 pizca de canela"],"pasos":["Cocine la avena en el agua 5 minutos revolviendo.","Pase a un tazón y agregue las frutas.","Termine con las nueces picadas, la miel y la canela."],"titulo":"Avena con frutas y nueces","porciones":1},"en":{"ingredientes":["1/2 cup rolled oats","1 cup water","1 banana, sliced","1/2 cup strawberries or papaya, diced","2 tbsp walnuts","1 tsp honey","1 pinch of cinnamon"],"pasos":["Cook the oats in the water for 5 minutes, stirring.","Transfer to a bowl and add the fruit.","Top with chopped walnuts, honey and cinnamon."],"titulo":"Oatmeal with fruit and walnuts","porciones":1}},"panqueques-integrales-frutas":{"es":{"ingredientes":["1 taza de harina integral","1 huevo","3/4 de taza de leche","1 cdta de polvo de hornear","1 cda de aceite","1 banano en rodajas","1/2 taza de fresas"],"pasos":["Mezcle la harina y el polvo de hornear.","Bata el huevo con la leche y el aceite y combine con la harina hasta obtener una mezcla lisa.","Cocine porciones en una sartén caliente, 2 minutos por lado.","Sirva con el banano y las fresas."],"titulo":"Panqueques integrales con frutas","porciones":2},"en":{"ingredientes":["1 cup whole-wheat flour","1 egg","3/4 cup milk","1 tsp baking powder","1 tbsp oil","1 banana, sliced","1/2 cup strawberries"],"pasos":["Mix the flour and baking powder.","Whisk the egg with the milk and oil and combine with the flour until smooth.","Cook portions in a hot pan, 2 minutes per side.","Serve with the banana and strawberries."],"titulo":"Whole-wheat pancakes with fruit","porciones":2}},"bowl-yogurt-granola":{"es":{"ingredientes":["1 taza de yogur natural","1/2 taza de granola de avena","1/2 taza de fresas o piña en cubos","1 banano en rodajas","1 cda de semillas de girasol"],"pasos":["Coloque el yogur en un tazón.","Agregue las frutas.","Termine con la granola y las semillas."],"titulo":"Bowl de yogur con granola y frutas","porciones":1},"en":{"ingredientes":["1 cup plain yogurt","1/2 cup oat granola","1/2 cup strawberries or pineapple, diced","1 banana, sliced","1 tbsp sunflower seeds"],"pasos":["Place the yogurt in a bowl.","Add the fruit.","Top with the granola and seeds."],"titulo":"Yogurt bowl with granola and fruit","porciones":1}},"sandwich-aguacate-tomate":{"es":{"ingredientes":["2 rebanadas de pan integral","1/2 aguacate","1 tomate en rodajas","2 hojas de lechuga","1/2 limón","sal y pimienta al gusto"],"pasos":["Tueste el pan si desea.","Triture el aguacate con limón, sal y pimienta y unte el pan.","Agregue el tomate y la lechuga, cierre y corte."],"titulo":"Sándwich de aguacate y tomate","porciones":1},"en":{"ingredientes":["2 slices of whole-grain bread","1/2 avocado","1 tomato, sliced","2 lettuce leaves","1/2 lemon","salt and pepper to taste"],"pasos":["Toast the bread if desired.","Mash the avocado with lemon, salt and pepper and spread on the bread.","Add the tomato and lettuce, close and cut."],"titulo":"Avocado and tomato sandwich","porciones":1}},"ensalada-cobb":{"es":{"ingredientes":["2 pechugas de pollo cocidas en cubos","4 tiras de tocino crujiente","2 huevos cocidos","1 aguacate en cubos","2 tomates en cubos","4 tazas de lechuga picada","50 g de queso azul desmenuzado","2 cdas de aceite de oliva","1 limón"],"pasos":["Cocine los huevos 10 minutos en agua hirviendo, enfríelos y pélelos.","Cocine el tocino en una sartén hasta que esté crujiente y desmenúcelo.","Coloque la lechuga en un plato y ordene encima filas de pollo, tocino, huevo, aguacate, tomate y queso.","Aliñe con aceite y limón."],"titulo":"Ensalada Cobb","porciones":2},"en":{"ingredientes":["2 cooked chicken breasts, cubed","4 strips crisp bacon","2 hard-boiled eggs","1 avocado, diced","2 tomatoes, diced","4 cups chopped lettuce","50 g crumbled blue cheese","2 tbsp olive oil","1 lemon"],"pasos":["Boil the eggs for 10 minutes, cool and peel.","Cook the bacon in a pan until crisp and crumble.","Place the lettuce on a plate and arrange rows of chicken, bacon, egg, avocado, tomato and cheese on top.","Dress with oil and lemon."],"titulo":"Cobb salad","porciones":2}},"sopa-pollo-fideos":{"es":{"ingredientes":["400 g de pechuga de pollo","6 tazas de agua","1 taza de fideos","2 zanahorias en rodajas","2 tallos de apio picados","1/2 cebolla picada","2 dientes de ajo","2 cdas de perejil picado"],"pasos":["Cocine el pollo en el agua con la cebolla, el ajo y sal 20 minutos; retírelo y deshébrelo.","Agregue la zanahoria y el apio al caldo; cocine 10 minutos.","Agregue los fideos y cocine 7 minutos.","Regrese el pollo y sirva con perejil."],"titulo":"Sopa de pollo con fideos","porciones":4},"en":{"ingredientes":["400 g chicken breast","6 cups water","1 cup noodles","2 carrots, sliced","2 celery stalks, chopped","1/2 onion, chopped","2 garlic cloves","2 tbsp chopped parsley"],"pasos":["Cook the chicken in the water with the onion, garlic and salt for 20 minutes; remove and shred.","Add the carrot and celery to the broth; cook 10 minutes.","Add the noodles and cook 7 minutes.","Return the chicken and serve with parsley."],"titulo":"Chicken noodle soup","porciones":4}},"chili-frijoles-vegetal":{"es":{"ingredientes":["2 tazas de frijoles rojos cocidos","1 taza de maíz","2 tazas de tomate triturado","1 chile dulce picado","1 cebolla picada","3 dientes de ajo picados","2 cdtas de comino","1 cdta de paprika","1 cda de aceite"],"pasos":["Sofría la cebolla, el chile dulce y el ajo en aceite con las especias.","Agregue el tomate, los frijoles y el maíz.","Cocine a fuego bajo 30 minutos.","Sazone con sal y sirva."],"titulo":"Chili vegetal de frijoles","porciones":4},"en":{"ingredientes":["2 cups cooked red beans","1 cup corn","2 cups crushed tomatoes","1 sweet pepper, chopped","1 onion, chopped","3 garlic cloves, minced","2 tsp cumin","1 tsp paprika","1 tbsp oil"],"pasos":["Sauté the onion, sweet pepper and garlic in oil with the spices.","Add the tomato, beans and corn.","Simmer for 30 minutes.","Season with salt and serve."],"titulo":"Vegetable bean chili","porciones":4}},"pavo-asado-camote":{"es":{"ingredientes":["500 g de pechuga de pavo","3 camotes en trozos","3 dientes de ajo picados","1 cda de romero","2 cdas de aceite de oliva","1 limón","sal y pimienta al gusto"],"pasos":["Caliente el horno a 190 °C. Unte el pavo con aceite, ajo, romero, limón, sal y pimienta.","Coloque el pavo y el camote en una bandeja.","Hornee 45 minutos hasta que el pavo esté bien cocido.","Deje reposar 10 minutos y corte en rebanadas."],"titulo":"Pechuga de pavo asada con camote","porciones":3},"en":{"ingredientes":["500 g turkey breast","3 sweet potatoes, chunked","3 garlic cloves, minced","1 tbsp rosemary","2 tbsp olive oil","1 lemon","salt and pepper to taste"],"pasos":["Heat the oven to 190 °C. Rub the turkey with oil, garlic, rosemary, lemon, salt and pepper.","Place the turkey and sweet potatoes on a tray.","Bake 45 minutes until the turkey is fully cooked.","Rest 10 minutes and slice."],"titulo":"Roast turkey breast with sweet potato","porciones":3}},"salmon-plancha-esparragos":{"es":{"ingredientes":["2 filetes de salmón (300 g)","1 manojo de espárragos","2 cdas de aceite de oliva","2 dientes de ajo picados","1 limón","sal y pimienta al gusto"],"pasos":["Sazone el salmón con sal y pimienta.","Cocine en una sartén con aceite 4 minutos por lado; apártelo.","Saltee los espárragos con el ajo 5 minutos.","Sirva con limón."],"titulo":"Salmón a la plancha con espárragos","porciones":2},"en":{"ingredientes":["2 salmon fillets (300 g)","1 bunch of asparagus","2 tbsp olive oil","2 garlic cloves, minced","1 lemon","salt and pepper to taste"],"pasos":["Season the salmon with salt and pepper.","Cook in a pan with oil, 4 minutes per side; set aside.","Sauté the asparagus with the garlic for 5 minutes.","Serve with lemon."],"titulo":"Pan-seared salmon with asparagus","porciones":2}},"wrap-pollo-vegetales":{"es":{"ingredientes":["2 tortillas de harina grandes","1 pechuga de pollo cocida y deshebrada","1 zanahoria rallada","1 tomate en rodajas","2 hojas de lechuga","1/2 aguacate","1 limón"],"pasos":["Mezcle el pollo con jugo de limón y sal.","Caliente las tortillas.","Rellene con pollo, lechuga, tomate, zanahoria y aguacate.","Enrolle y corte por la mitad."],"titulo":"Wrap de pollo y vegetales","porciones":2},"en":{"ingredientes":["2 large flour tortillas","1 cooked, shredded chicken breast","1 carrot, grated","1 tomato, sliced","2 lettuce leaves","1/2 avocado","1 lime"],"pasos":["Toss the chicken with lime juice and salt.","Warm the tortillas.","Fill with chicken, lettuce, tomato, carrot and avocado.","Roll up and cut in half."],"titulo":"Chicken and vegetable wrap","porciones":2}},"papa-horneada-brocoli":{"es":{"ingredientes":["2 papas grandes","2 tazas de brócoli","1/2 taza de queso rallado","1/4 de taza de yogur natural","1 cda de aceite","sal y pimienta al gusto"],"pasos":["Caliente el horno a 200 °C. Frote las papas con aceite y sal y hornee 45 minutos.","Cocine el brócoli al vapor 5 minutos.","Abra las papas y rellene con el brócoli, el yogur y el queso.","Gratine 5 minutos."],"titulo":"Papa horneada con brócoli y queso","porciones":2},"en":{"ingredientes":["2 large potatoes","2 cups broccoli","1/2 cup grated cheese","1/4 cup plain yogurt","1 tbsp oil","salt and pepper to taste"],"pasos":["Heat the oven to 200 °C. Rub the potatoes with oil and salt and bake 45 minutes.","Steam the broccoli for 5 minutes.","Split the potatoes and fill with the broccoli, yogurt and cheese.","Broil for 5 minutes."],"titulo":"Baked potato with broccoli and cheese","porciones":2}},"pollo-parrilla-ensalada-repollo":{"es":{"ingredientes":["2 pechugas de pollo","2 tazas de repollo en tiras","1 zanahoria rallada","2 limones","2 dientes de ajo picados","2 cdas de aceite","sal y pimienta al gusto"],"pasos":["Marine el pollo 15 minutos con el ajo, el jugo de un limón, aceite, sal y pimienta.","Cocine a la parrilla o plancha 7 minutos por lado.","Mezcle el repollo y la zanahoria con el otro limón y sal.","Sirva el pollo con la ensalada."],"titulo":"Pollo a la parrilla con ensalada de repollo","porciones":2},"en":{"ingredientes":["2 chicken breasts","2 cups shredded cabbage","1 carrot, grated","2 limes","2 garlic cloves, minced","2 tbsp oil","salt and pepper to taste"],"pasos":["Marinate the chicken for 15 minutes with the garlic, the juice of one lime, oil, salt and pepper.","Grill or griddle 7 minutes per side.","Toss the cabbage and carrot with the other lime and salt.","Serve the chicken with the salad."],"titulo":"Grilled chicken with cabbage salad","porciones":2}},"sopa-maiz-papa":{"es":{"ingredientes":["2 tazas de maíz","2 papas en cubos","1/2 cebolla picada","2 dientes de ajo picados","3 tazas de caldo de verduras","1 cda de aceite","2 cdas de culantro picado"],"pasos":["Sofría la cebolla y el ajo en aceite.","Agregue la papa, el maíz y el caldo; cocine 20 minutos.","Licúe la mitad para espesar y regrese a la olla.","Sazone y sirva con culantro."],"titulo":"Sopa de maíz y papa","porciones":3},"en":{"ingredientes":["2 cups corn","2 potatoes, cubed","1/2 onion, chopped","2 garlic cloves, minced","3 cups vegetable broth","1 tbsp oil","2 tbsp chopped culantro"],"pasos":["Sauté the onion and garlic in oil.","Add the potato, corn and broth; cook 20 minutes.","Blend half to thicken and return to the pot.","Season and serve with culantro."],"titulo":"Corn and potato soup","porciones":3}},"huevos-tomate-espinaca":{"es":{"ingredientes":["4 huevos","2 tomates picados","2 tazas de espinaca","1/4 de cebolla picada","1 diente de ajo picado","1 cda de aceite","sal y pimienta al gusto"],"pasos":["Sofría la cebolla y el ajo en aceite; agregue el tomate y cocine 5 minutos.","Agregue la espinaca hasta que se marchite.","Haga cuatro huecos y rompa un huevo en cada uno.","Tape y cocine 5 minutos hasta que cuajen."],"titulo":"Huevos con tomate y espinaca","porciones":2},"en":{"ingredientes":["4 eggs","2 tomatoes, chopped","2 cups spinach","1/4 onion, chopped","1 garlic clove, minced","1 tbsp oil","salt and pepper to taste"],"pasos":["Sauté the onion and garlic in oil; add the tomato and cook 5 minutes.","Add the spinach until wilted.","Make four wells and crack an egg into each.","Cover and cook 5 minutes until set."],"titulo":"Eggs with tomato and spinach","porciones":2}},"huevos-rancheros":{"es":{"ingredientes":["4 huevos","4 tortillas de maíz","1 taza de frijoles refritos","3 tomates","1/4 de cebolla","1 chile picante pequeño (opcional)","1 cda de aceite"],"pasos":["Licúe los tomates cocidos con la cebolla, el chile y sal; cocine la salsa 5 minutos.","Caliente las tortillas y unte los frijoles.","Fría los huevos en aceite.","Coloque un huevo sobre cada tortilla y cubra con la salsa."],"titulo":"Huevos rancheros","porciones":2},"en":{"ingredientes":["4 eggs","4 corn tortillas","1 cup refried beans","3 tomatoes","1/4 onion","1 small hot chili (optional)","1 tbsp oil"],"pasos":["Blend the cooked tomatoes with the onion, chili and salt; simmer the sauce for 5 minutes.","Warm the tortillas and spread with beans.","Fry the eggs in oil.","Place an egg on each tortilla and cover with the sauce."],"titulo":"Ranchero eggs","porciones":2}},"molletes-frijoles-queso":{"es":{"ingredientes":["2 panes tipo baguette o bolillos","1 taza de frijoles refritos","1 taza de queso rallado","1 tomate picado","1/4 de cebolla picada","2 cdas de culantro picado"],"pasos":["Caliente el horno a 200 °C. Corte los panes por la mitad.","Unte los frijoles y cubra con el queso.","Hornee 8 minutos hasta que el queso se derrita.","Mezcle el tomate, la cebolla y el culantro y sírvalo encima."],"titulo":"Molletes de frijoles con queso","porciones":2},"en":{"ingredientes":["2 baguette-style rolls","1 cup refried beans","1 cup grated cheese","1 tomato, chopped","1/4 onion, chopped","2 tbsp chopped culantro"],"pasos":["Heat the oven to 200 °C. Halve the rolls.","Spread with beans and top with cheese.","Bake 8 minutes until the cheese melts.","Mix the tomato, onion and culantro and serve on top."],"titulo":"Bean and cheese molletes","porciones":2}},"huevos-nopales":{"es":{"ingredientes":["4 huevos","2 tazas de nopales limpios en cubos","1 tomate picado","1/4 de cebolla picada","2 cdas de culantro picado","1 cda de aceite","sal al gusto"],"pasos":["Cocine los nopales en agua con sal 10 minutos; escúrralos y enjuáguelos.","Sofría la cebolla y el tomate en aceite; agregue los nopales.","Agregue los huevos batidos y revuelva hasta que cuajen.","Termine con culantro."],"titulo":"Huevos con nopales","porciones":2},"en":{"ingredientes":["4 eggs","2 cups cleaned cactus paddles, diced","1 tomato, chopped","1/4 onion, chopped","2 tbsp chopped culantro","1 tbsp oil","salt to taste"],"pasos":["Boil the cactus in salted water for 10 minutes; drain and rinse.","Sauté the onion and tomato in oil; add the cactus.","Add the beaten eggs and stir until set.","Finish with culantro."],"titulo":"Eggs with cactus paddles","porciones":2}},"avena-canela-manzana":{"es":{"ingredientes":["1/2 taza de avena en hojuelas","1 taza de agua","1 manzana en cubos","1/2 cdta de canela","1 cdta de semillas de chía"],"pasos":["Cocine la avena con el agua y la canela 5 minutos.","Agregue la manzana en los últimos 2 minutos.","Sirva con las semillas de chía."],"titulo":"Avena con canela y manzana","porciones":1},"en":{"ingredientes":["1/2 cup rolled oats","1 cup water","1 apple, diced","1/2 tsp cinnamon","1 tsp chia seeds"],"pasos":["Cook the oats with the water and cinnamon for 5 minutes.","Add the apple for the last 2 minutes.","Serve with the chia seeds."],"titulo":"Oatmeal with cinnamon and apple","porciones":1}},"sopa-tortilla":{"es":{"ingredientes":["4 tortillas de maíz en tiras","4 tazas de caldo de verduras","3 tomates","1/4 de cebolla","2 dientes de ajo","1 aguacate en cubos","1/2 taza de queso fresco en cubos","1 cda de aceite"],"pasos":["Hornee o fría las tiras de tortilla hasta que estén crujientes.","Licúe los tomates con la cebolla y el ajo; fría la salsa en aceite 5 minutos.","Agregue el caldo y cocine 15 minutos; sazone.","Sirva con las tiras de tortilla, el aguacate y el queso."],"titulo":"Sopa de tortilla","porciones":3},"en":{"ingredientes":["4 corn tortillas, cut in strips","4 cups vegetable broth","3 tomatoes","1/4 onion","2 garlic cloves","1 avocado, diced","1/2 cup fresh cheese, cubed","1 tbsp oil"],"pasos":["Bake or fry the tortilla strips until crisp.","Blend the tomatoes with the onion and garlic; fry the sauce in oil for 5 minutes.","Add the broth and simmer 15 minutes; season.","Serve with the tortilla strips, avocado and cheese."],"titulo":"Tortilla soup","porciones":3}},"quesadillas-hongos":{"es":{"ingredientes":["6 tortillas de maíz","2 tazas de hongos en láminas","1 taza de queso rallado","1/4 de cebolla picada","1 diente de ajo picado","1 cda de aceite"],"pasos":["Sofría la cebolla y el ajo en aceite; agregue los hongos con sal y cocine 8 minutos.","Rellene cada tortilla con hongos y queso y dóblela.","Cocine en una sartén 2 minutos por lado hasta que el queso se derrita."],"titulo":"Quesadillas de hongos","porciones":2},"en":{"ingredientes":["6 corn tortillas","2 cups sliced mushrooms","1 cup grated cheese","1/4 onion, chopped","1 garlic clove, minced","1 tbsp oil"],"pasos":["Sauté the onion and garlic in oil; add the mushrooms with salt and cook 8 minutes.","Fill each tortilla with mushrooms and cheese and fold.","Cook in a pan 2 minutes per side until the cheese melts."],"titulo":"Mushroom quesadillas","porciones":2}},"arroz-mexicano-frijoles":{"es":{"ingredientes":["1 taza de arroz","2 tomates","1/4 de cebolla","1 diente de ajo","2 tazas de caldo de verduras","1 taza de frijoles negros cocidos","1/2 taza de arvejas y zanahoria","2 cdas de aceite"],"pasos":["Dore el arroz en aceite 3 minutos.","Licúe los tomates con la cebolla y el ajo y agréguelos; cocine 3 minutos.","Agregue el caldo y las verduras; tape y cocine a fuego bajo 20 minutos.","Sirva con los frijoles calientes."],"titulo":"Arroz mexicano con frijoles","porciones":3},"en":{"ingredientes":["1 cup rice","2 tomatoes","1/4 onion","1 garlic clove","2 cups vegetable broth","1 cup cooked black beans","1/2 cup peas and carrot","2 tbsp oil"],"pasos":["Toast the rice in oil for 3 minutes.","Blend the tomatoes with the onion and garlic and add; cook 3 minutes.","Add the broth and vegetables; cover and simmer for 20 minutes.","Serve with the warm beans."],"titulo":"Mexican rice with beans","porciones":3}},"ensalada-nopales":{"es":{"ingredientes":["3 tazas de nopales cocidos en cubos","2 tomates picados","1/4 de cebolla morada picada","1/2 taza de queso fresco desmenuzado","3 cdas de culantro picado","2 limones","1 cda de aceite de oliva"],"pasos":["Mezcle los nopales, el tomate, la cebolla y el culantro.","Aliñe con el jugo de limón, el aceite y la sal.","Agregue el queso y sirva."],"titulo":"Ensalada de nopales con queso fresco","porciones":2},"en":{"ingredientes":["3 cups cooked cactus paddles, diced","2 tomatoes, chopped","1/4 red onion, chopped","1/2 cup crumbled fresh cheese","3 tbsp chopped culantro","2 limes","1 tbsp olive oil"],"pasos":["Combine the cactus, tomato, onion and culantro.","Dress with the lime juice, oil and salt.","Top with the cheese and serve."],"titulo":"Cactus salad with fresh cheese","porciones":2}},"pollo-pibil":{"es":{"ingredientes":["700 g de muslos de pollo","3 cdas de achiote molido","1/2 taza de jugo de naranja","1/4 de taza de jugo de limón","4 dientes de ajo","1 cdta de comino","1 cdta de orégano","hojas de plátano (opcional)"],"pasos":["Licúe el achiote, los jugos, el ajo y las especias con sal.","Marine el pollo al menos 1 hora.","Envuelva en hojas de plátano o papel aluminio y hornee a 180 °C por 50 minutos.","Desmenuce y sirva con tortillas o arroz."],"titulo":"Pollo pibil","porciones":3},"en":{"ingredientes":["700 g chicken thighs","3 tbsp ground achiote","1/2 cup orange juice","1/4 cup lime juice","4 garlic cloves","1 tsp cumin","1 tsp oregano","banana leaves (optional)"],"pasos":["Blend the achiote, juices, garlic and spices with salt.","Marinate the chicken at least 1 hour.","Wrap in banana leaves or foil and bake at 180 °C for 50 minutes.","Shred and serve with tortillas or rice."],"titulo":"Pibil chicken","porciones":3}},"tinga-pollo-tostadas":{"es":{"ingredientes":["2 pechugas de pollo cocidas y deshebradas","6 tostadas de maíz","3 tomates","1 chile chipotle (opcional)","1/2 cebolla en tiras","2 dientes de ajo","1/2 taza de queso fresco desmenuzado","1 cda de aceite"],"pasos":["Licúe los tomates con el ajo y el chipotle.","Sofría la cebolla en aceite; agregue la salsa y cocine 8 minutos.","Agregue el pollo y cocine 5 minutos.","Sirva sobre las tostadas con el queso."],"titulo":"Tinga de pollo en tostadas","porciones":3},"en":{"ingredientes":["2 cooked, shredded chicken breasts","6 corn tostadas","3 tomatoes","1 chipotle chili (optional)","1/2 onion, sliced","2 garlic cloves","1/2 cup crumbled fresh cheese","1 tbsp oil"],"pasos":["Blend the tomatoes with the garlic and chipotle.","Sauté the onion in oil; add the sauce and simmer 8 minutes.","Add the chicken and cook 5 minutes.","Serve on the tostadas with the cheese."],"titulo":"Chicken tinga tostadas","porciones":3}},"pescado-veracruzana":{"es":{"ingredientes":["2 filetes de pescado blanco (300 g)","3 tomates picados","1/2 cebolla en tiras","2 dientes de ajo picados","10 aceitunas","1 cda de alcaparras","1 limón","2 cdas de aceite de oliva"],"pasos":["Sofría la cebolla y el ajo en aceite; agregue el tomate y cocine 8 minutos.","Agregue las aceitunas y las alcaparras.","Coloque el pescado con sal y limón sobre la salsa; tape y cocine 10 minutos."],"titulo":"Pescado a la veracruzana","porciones":2},"en":{"ingredientes":["2 white fish fillets (300 g)","3 tomatoes, chopped","1/2 onion, sliced","2 garlic cloves, minced","10 olives","1 tbsp capers","1 lime","2 tbsp olive oil"],"pasos":["Sauté the onion and garlic in oil; add the tomato and cook 8 minutes.","Add the olives and capers.","Place the fish with salt and lime over the sauce; cover and cook 10 minutes."],"titulo":"Veracruz-style fish","porciones":2}},"sopa-lima-pollo":{"es":{"ingredientes":["400 g de pechuga de pollo","6 tazas de agua","2 limas o limones","2 tomates picados","1/2 cebolla picada","3 dientes de ajo","4 tortillas de maíz en tiras","2 cdas de culantro picado"],"pasos":["Cocine el pollo en el agua con una parte de la cebolla, el ajo y sal 20 minutos; deshébrelo.","Sofría el resto de la cebolla y el tomate; agregue al caldo y cocine 10 minutos.","Agregue el pollo y el jugo de lima.","Sirva con tiras de tortilla doradas y culantro."],"titulo":"Sopa de lima con pollo","porciones":3},"en":{"ingredientes":["400 g chicken breast","6 cups water","2 limes","2 tomatoes, chopped","1/2 onion, chopped","3 garlic cloves","4 corn tortillas, cut in strips","2 tbsp chopped culantro"],"pasos":["Cook the chicken in the water with part of the onion, garlic and salt for 20 minutes; shred.","Sauté the remaining onion and the tomato; add to the broth and cook 10 minutes.","Add the chicken and lime juice.","Serve with toasted tortilla strips and culantro."],"titulo":"Lime and chicken soup","porciones":3}},"tacos-camote-frijol":{"es":{"ingredientes":["6 tortillas de maíz pequeñas","2 camotes en cubos","1 taza de frijoles negros cocidos","1/2 cebolla morada en tiras","1 aguacate","1 cdta de comino","1 cda de aceite","1 limón"],"pasos":["Mezcle el camote con aceite, comino y sal y hornee a 200 °C por 25 minutos.","Caliente los frijoles y las tortillas.","Rellene con camote, frijoles, cebolla y aguacate.","Termine con limón."],"titulo":"Tacos de camote y frijol","porciones":2},"en":{"ingredientes":["6 small corn tortillas","2 sweet potatoes, cubed","1 cup cooked black beans","1/2 red onion, sliced","1 avocado","1 tsp cumin","1 tbsp oil","1 lime"],"pasos":["Toss the sweet potato with oil, cumin and salt and roast at 200 °C for 25 minutes.","Warm the beans and tortillas.","Fill with sweet potato, beans, onion and avocado.","Finish with lime."],"titulo":"Sweet potato and bean tacos","porciones":2}},"calabacitas-maiz-tortilla":{"es":{"ingredientes":["3 zucchinis en cubos","1 taza de maíz","2 tomates picados","1/2 cebolla picada","2 dientes de ajo picados","1 cda de aceite","6 tortillas de maíz","2 cdas de culantro picado"],"pasos":["Sofría la cebolla y el ajo en aceite; agregue el tomate.","Agregue el zucchini y el maíz con sal; tape y cocine 12 minutos.","Termine con culantro y sirva con las tortillas calientes."],"titulo":"Calabacitas con maíz y tortillas","porciones":2},"en":{"ingredientes":["3 zucchinis, diced","1 cup corn","2 tomatoes, chopped","1/2 onion, chopped","2 garlic cloves, minced","1 tbsp oil","6 corn tortillas","2 tbsp chopped culantro"],"pasos":["Sauté the onion and garlic in oil; add the tomato.","Add the zucchini and corn with salt; cover and cook 12 minutes.","Finish with culantro and serve with warm tortillas."],"titulo":"Zucchini with corn and tortillas","porciones":2}},"tamales-vegetales":{"es":{"ingredientes":["2 tazas de masa de maíz para tamales","1 1/2 tazas de caldo de verduras","1/4 de taza de aceite","1 zanahoria en cubos pequeños","1 papa en cubos pequeños","1/2 taza de arvejas","1 chile dulce picado","hojas de plátano o de maíz"],"pasos":["Mezcle la masa de maíz con el caldo, el aceite y sal hasta formar una masa suave.","Cocine los vegetales en agua con sal 10 minutos y escúrralos.","Extienda masa sobre una hoja, ponga los vegetales y envuelva.","Cocine al vapor 60 minutos."],"titulo":"Tamales de vegetales","porciones":4},"en":{"ingredientes":["2 cups instant corn masa for tamales","1 1/2 cups vegetable broth","1/4 cup oil","1 carrot, small-diced","1 potato, small-diced","1/2 cup peas","1 sweet pepper, chopped","banana or corn leaves"],"pasos":["Mix the corn masa with the broth, oil and salt into a soft dough.","Cook the vegetables in salted water for 10 minutes and drain.","Spread dough on a leaf, add the vegetables and wrap.","Steam for 60 minutes."],"titulo":"Vegetable tamales","porciones":4}},"congee-arroz-jengibre":{"es":{"ingredientes":["1/2 taza de arroz","5 tazas de agua o caldo de verduras","1 cda de jengibre en tiras","1 zanahoria rallada","1 cebollino picado","1 cdta de aceite de ajonjolí","sal al gusto"],"pasos":["Lave el arroz y cocínelo en el agua con el jengibre a fuego bajo 40 minutos, revolviendo.","Agregue la zanahoria los últimos 10 minutos.","Sazone con sal.","Sirva con el cebollino y unas gotas de aceite de ajonjolí."],"titulo":"Congee de arroz con jengibre","porciones":2},"en":{"ingredientes":["1/2 cup rice","5 cups water or vegetable broth","1 tbsp ginger, in strips","1 carrot, grated","1 scallion, chopped","1 tsp sesame oil","salt to taste"],"pasos":["Rinse the rice and cook in the water with the ginger over low heat for 40 minutes, stirring.","Add the carrot for the last 10 minutes.","Season with salt.","Serve with the scallion and a few drops of sesame oil."],"titulo":"Rice congee with ginger","porciones":2}},"huevo-vapor-cebollino":{"es":{"ingredientes":["3 huevos","3/4 de taza de agua tibia","1 cebollino picado","2 cdtas de salsa de soya","1 cdta de aceite"],"pasos":["Bata los huevos con el agua tibia y cuele la mezcla.","Vierta en un recipiente apto para vapor y tápelo.","Cocine al vapor a fuego bajo 12 minutos.","Sirva con la salsa de soya, el aceite y el cebollino."],"titulo":"Huevo al vapor con cebollino","porciones":2},"en":{"ingredientes":["3 eggs","3/4 cup warm water","1 scallion, chopped","2 tsp soy sauce","1 tsp oil"],"pasos":["Beat the eggs with the warm water and strain the mixture.","Pour into a steam-safe dish and cover.","Steam over low heat for 12 minutes.","Serve with the soy sauce, oil and scallion."],"titulo":"Steamed egg with scallion","porciones":2}},"sopa-huevo-maiz":{"es":{"ingredientes":["3 tazas de caldo de verduras","1 taza de maíz","2 huevos batidos","1 cdta de jengibre rallado","1 cebollino picado","sal y pimienta al gusto"],"pasos":["Hierva el caldo con el jengibre y el maíz 8 minutos.","Vierta los huevos en hilo mientras revuelve suavemente.","Sazone y sirva con cebollino."],"titulo":"Sopa de huevo y maíz","porciones":2},"en":{"ingredientes":["3 cups vegetable broth","1 cup corn","2 beaten eggs","1 tsp grated ginger","1 scallion, chopped","salt and pepper to taste"],"pasos":["Simmer the broth with the ginger and corn for 8 minutes.","Pour in the eggs in a thin stream while stirring gently.","Season and serve with scallion."],"titulo":"Egg and corn soup","porciones":2}},"sopa-tofu-hongos":{"es":{"ingredientes":["200 g de tofu suave en cubos","1 taza de hongos en láminas","3 tazas de caldo de verduras","1 cdta de jengibre rallado","1 cda de salsa de soya","1 cebollino picado"],"pasos":["Hierva el caldo con el jengibre y los hongos 8 minutos.","Agregue el tofu y la salsa de soya; cocine 5 minutos.","Sirva con el cebollino."],"titulo":"Sopa de tofu y hongos","porciones":2},"en":{"ingredientes":["200 g soft tofu, cubed","1 cup sliced mushrooms","3 cups vegetable broth","1 tsp grated ginger","1 tbsp soy sauce","1 scallion, chopped"],"pasos":["Simmer the broth with the ginger and mushrooms for 8 minutes.","Add the tofu and soy sauce; cook 5 minutes.","Serve with the scallion."],"titulo":"Tofu and mushroom soup","porciones":2}},"tofu-mapo-suave":{"es":{"ingredientes":["300 g de tofu suave en cubos","150 g de hongos picados","2 dientes de ajo picados","1 cdta de jengibre rallado","1/2 taza de caldo de verduras","1 cda de salsa de soya","1 cdta de fécula de maíz","1 cebollino picado","1 cda de aceite"],"pasos":["Saltee el ajo, el jengibre y los hongos en aceite 5 minutos.","Agregue el caldo y la salsa de soya y hierva.","Agregue el tofu con cuidado y cocine 5 minutos.","Espese con la fécula disuelta en agua; sirva con cebollino."],"titulo":"Tofu mapo suave","porciones":2},"en":{"ingredientes":["300 g soft tofu, cubed","150 g mushrooms, chopped","2 garlic cloves, minced","1 tsp grated ginger","1/2 cup vegetable broth","1 tbsp soy sauce","1 tsp cornstarch","1 scallion, chopped","1 tbsp oil"],"pasos":["Stir-fry the garlic, ginger and mushrooms in oil for 5 minutes.","Add the broth and soy sauce and bring to a simmer.","Gently add the tofu and cook 5 minutes.","Thicken with the cornstarch dissolved in water; serve with scallion."],"titulo":"Mild mapo tofu","porciones":2}},"brocoli-ajo-arroz":{"es":{"ingredientes":["1 taza de arroz","3 tazas de brócoli en ramitos","4 dientes de ajo en láminas","1 cdta de jengibre rallado","1 cda de aceite","1 limón","sal al gusto"],"pasos":["Cocine el arroz según el paquete.","Saltee el ajo y el jengibre en aceite 30 segundos.","Agregue el brócoli con 2 cdas de agua, tape y cocine 4 minutos.","Sazone con sal y limón; sirva con el arroz."],"titulo":"Brócoli salteado con ajo y arroz","porciones":2},"en":{"ingredientes":["1 cup rice","3 cups broccoli florets","4 garlic cloves, sliced","1 tsp grated ginger","1 tbsp oil","1 lemon","salt to taste"],"pasos":["Cook the rice as directed.","Stir-fry the garlic and ginger in oil for 30 seconds.","Add the broccoli with 2 tbsp water, cover and cook 4 minutes.","Season with salt and lemon; serve with the rice."],"titulo":"Garlic broccoli stir-fry with rice","porciones":2}},"pollo-vegetales-salteados":{"es":{"ingredientes":["300 g de pechuga de pollo en tiras","1 chile dulce en tiras","1 zanahoria en rodajas finas","1 taza de brócoli","2 dientes de ajo picados","1 cdta de jengibre rallado","2 cdas de salsa de soya","1 cda de aceite"],"pasos":["Saltee el pollo en aceite a fuego alto 5 minutos y apártelo.","Saltee el ajo, el jengibre y los vegetales 5 minutos.","Regrese el pollo, agregue la salsa de soya y cocine 2 minutos."],"titulo":"Pollo y vegetales salteados","porciones":2},"en":{"ingredientes":["300 g chicken breast, sliced","1 sweet pepper, sliced","1 carrot, thinly sliced","1 cup broccoli","2 garlic cloves, minced","1 tsp grated ginger","2 tbsp soy sauce","1 tbsp oil"],"pasos":["Stir-fry the chicken in oil over high heat for 5 minutes and set aside.","Stir-fry the garlic, ginger and vegetables for 5 minutes.","Return the chicken, add the soy sauce and cook 2 minutes."],"titulo":"Chicken and vegetable stir-fry","porciones":2}},"pescado-vapor-jengibre":{"es":{"ingredientes":["2 filetes de pescado blanco (300 g)","1 cda de jengibre en tiras","2 cebollinos en tiras","2 cdas de salsa de soya","1 cda de aceite","1 cdta de azúcar"],"pasos":["Coloque el pescado en un plato con el jengibre.","Cocine al vapor 8 a 10 minutos.","Mezcle la salsa de soya con el azúcar y viértala sobre el pescado.","Caliente el aceite y viértalo sobre el cebollino y el pescado."],"titulo":"Pescado al vapor con jengibre","porciones":2},"en":{"ingredientes":["2 white fish fillets (300 g)","1 tbsp ginger, in strips","2 scallions, in strips","2 tbsp soy sauce","1 tbsp oil","1 tsp sugar"],"pasos":["Place the fish on a plate with the ginger.","Steam for 8 to 10 minutes.","Mix the soy sauce with the sugar and pour over the fish.","Heat the oil and pour it over the scallions and fish."],"titulo":"Steamed fish with ginger","porciones":2}},"res-brocoli":{"es":{"ingredientes":["300 g de res en tiras finas","3 tazas de brócoli en ramitos","3 dientes de ajo picados","1 cdta de jengibre rallado","2 cdas de salsa de soya","1 cdta de fécula de maíz","1 cda de aceite"],"pasos":["Mezcle la carne con la fécula y 1 cda de salsa de soya.","Saltee la carne en aceite a fuego alto 3 minutos y apártela.","Saltee el ajo, el jengibre y el brócoli con 3 cdas de agua 4 minutos.","Regrese la carne con el resto de la salsa de soya y cocine 1 minuto."],"titulo":"Res con brócoli","porciones":2},"en":{"ingredientes":["300 g beef, thinly sliced","3 cups broccoli florets","3 garlic cloves, minced","1 tsp grated ginger","2 tbsp soy sauce","1 tsp cornstarch","1 tbsp oil"],"pasos":["Toss the beef with the cornstarch and 1 tbsp soy sauce.","Stir-fry the beef in oil over high heat for 3 minutes and set aside.","Stir-fry the garlic, ginger and broccoli with 3 tbsp water for 4 minutes.","Return the beef with the rest of the soy sauce and cook 1 minute."],"titulo":"Beef and broccoli","porciones":2}},"vermicelli-arroz-vegetales":{"es":{"ingredientes":["150 g de fideos de arroz","1 zanahoria en tiras","1 taza de repollo en tiras","1 chile dulce en tiras","2 dientes de ajo picados","1 cda de aceite","1 limón","sal al gusto"],"pasos":["Remoje los fideos de arroz en agua caliente 5 minutos y escúrralos.","Saltee el ajo y los vegetales en aceite 5 minutos.","Agregue los fideos de arroz, sal y limón; mezcle 2 minutos."],"titulo":"Fideos de arroz con vegetales","porciones":2},"en":{"ingredientes":["150 g rice noodles","1 carrot, in strips","1 cup shredded cabbage","1 sweet pepper, sliced","2 garlic cloves, minced","1 tbsp oil","1 lime","salt to taste"],"pasos":["Soak the rice noodles in hot water for 5 minutes and drain.","Stir-fry the garlic and vegetables in oil for 5 minutes.","Add the rice noodles, salt and lime; toss for 2 minutes."],"titulo":"Rice noodles with vegetables","porciones":2}},"bok-choy-hongos":{"es":{"ingredientes":["4 bok choy pequeños","2 tazas de hongos en láminas","3 dientes de ajo picados","1 cdta de jengibre rallado","1 cda de aceite","sal al gusto"],"pasos":["Saltee el ajo y el jengibre en aceite 30 segundos.","Agregue los hongos y cocine 5 minutos.","Agregue el bok choy con 2 cdas de agua, tape y cocine 3 minutos.","Sazone con sal."],"titulo":"Bok choy con hongos","porciones":2},"en":{"ingredientes":["4 baby bok choy","2 cups sliced mushrooms","3 garlic cloves, minced","1 tsp grated ginger","1 tbsp oil","salt to taste"],"pasos":["Stir-fry the garlic and ginger in oil for 30 seconds.","Add the mushrooms and cook 5 minutes.","Add the bok choy with 2 tbsp water, cover and cook 3 minutes.","Season with salt."],"titulo":"Bok choy with mushrooms","porciones":2}},"rollitos-primavera-frescos":{"es":{"ingredientes":["6 hojas de papel de arroz","100 g de fideos de arroz cocidos","1 zanahoria en tiras","1 pepino en tiras","1 taza de lechuga","1/4 de taza de menta y culantro","2 limones","1 cda de azúcar"],"pasos":["Remoje cada hoja de papel de arroz en agua tibia unos segundos.","Coloque los fideos de arroz, los vegetales y las hierbas en el centro.","Doble los lados y enrolle con firmeza.","Prepare una salsa con el limón, el azúcar y un poco de agua para mojar."],"titulo":"Rollitos de primavera frescos","porciones":2},"en":{"ingredientes":["6 rice paper wrappers","100 g cooked rice noodles","1 carrot, in strips","1 cucumber, in strips","1 cup lettuce","1/4 cup mint and culantro","2 limes","1 tbsp sugar"],"pasos":["Dip each rice paper wrapper in warm water for a few seconds.","Place the rice noodles, vegetables and herbs in the center.","Fold in the sides and roll tightly.","Make a dipping sauce with the lime, sugar and a little water."],"titulo":"Fresh spring rolls","porciones":2}},"tortilla-huevo-vegetales-china":{"es":{"ingredientes":["4 huevos","1/2 taza de repollo en tiras finas","1 zanahoria rallada","1 cebollino picado","1 cda de aceite","sal y pimienta al gusto"],"pasos":["Bata los huevos con sal y pimienta.","Mezcle con el repollo, la zanahoria y el cebollino.","Cocine en una sartén con aceite a fuego medio 3 minutos por lado."],"titulo":"Tortilla de huevo con vegetales","porciones":2},"en":{"ingredientes":["4 eggs","1/2 cup finely shredded cabbage","1 carrot, grated","1 scallion, chopped","1 tbsp oil","salt and pepper to taste"],"pasos":["Beat the eggs with salt and pepper.","Mix with the cabbage, carrot and scallion.","Cook in a pan with oil over medium heat 3 minutes per side."],"titulo":"Egg omelet with vegetables","porciones":2}},"arroz-frito-vegetales":{"es":{"ingredientes":["2 tazas de arroz cocido (frío)","1 zanahoria picada","1/2 taza de arvejas","1/2 taza de maíz","2 dientes de ajo picados","2 cdas de salsa de soya","2 cdas de aceite","1 cebollino picado"],"pasos":["Saltee el ajo y los vegetales en aceite 5 minutos.","Agregue el arroz y mezcle a fuego alto 3 minutos.","Agregue la salsa de soya y el cebollino."],"titulo":"Arroz frito con vegetales","porciones":2},"en":{"ingredientes":["2 cups cooked rice (cold)","1 carrot, chopped","1/2 cup peas","1/2 cup corn","2 garlic cloves, minced","2 tbsp soy sauce","2 tbsp oil","1 scallion, chopped"],"pasos":["Stir-fry the garlic and vegetables in oil for 5 minutes.","Add the rice and toss over high heat for 3 minutes.","Add the soy sauce and scallion."],"titulo":"Vegetable fried rice","porciones":2}},"edamame-ensalada-pepino":{"es":{"ingredientes":["1 1/2 tazas de edamame desvainado","2 pepinos en rodajas","1/2 cebolla morada en tiras finas","1 cda de semillas de ajonjolí","1 cda de aceite de ajonjolí","1 limón","sal al gusto"],"pasos":["Cocine el edamame en agua con sal 5 minutos; escurra y enfríe.","Mezcle con el pepino y la cebolla.","Aliñe con el aceite de ajonjolí y el limón; espolvoree el ajonjolí."],"titulo":"Ensalada de edamame y pepino","porciones":2},"en":{"ingredientes":["1 1/2 cups shelled edamame","2 cucumbers, sliced","1/2 red onion, thinly sliced","1 tbsp sesame seeds","1 tbsp sesame oil","1 lime","salt to taste"],"pasos":["Boil the edamame in salted water for 5 minutes; drain and cool.","Combine with the cucumber and onion.","Dress with the sesame oil and lime; sprinkle with sesame seeds."],"titulo":"Edamame and cucumber salad","porciones":2}},"camote-al-vapor-tofu":{"es":{"ingredientes":["2 camotes medianos en rodajas","200 g de tofu firme","2 tazas de espinacas","1 diente de ajo picado","1 cdta de jengibre rallado","1 cda de salsa de soya","1 cda de aceite"],"pasos":["Cocine el camote al vapor 15 minutos.","Dore el tofu en cubos en aceite con el ajo y el jengibre.","Agregue las espinacas hasta que se marchiten y la salsa de soya.","Sirva el tofu y las espinacas con el camote."],"titulo":"Camote al vapor con tofu","porciones":2},"en":{"ingredientes":["2 medium sweet potatoes, sliced","200 g firm tofu","2 cups spinach","1 garlic clove, minced","1 tsp grated ginger","1 tbsp soy sauce","1 tbsp oil"],"pasos":["Steam the sweet potato for 15 minutes.","Brown the cubed tofu in oil with the garlic and ginger.","Add the spinach until wilted and the soy sauce.","Serve the tofu and spinach with the sweet potato."],"titulo":"Steamed sweet potato with tofu","porciones":2}},"sopa-wonton-pollo":{"es":{"ingredientes":["200 g de pollo molido","20 hojas de masa de trigo para wonton","5 tazas de caldo de pollo","1 cdta de jengibre rallado","1 diente de ajo picado","2 tazas de bok choy o espinaca","1 cebollino picado"],"pasos":["Mezcle el pollo con el jengibre, el ajo y sal.","Ponga una cucharadita de relleno en cada hoja, humedezca los bordes y cierre.","Hierva el caldo y cocine los wontons 5 minutos.","Agregue el bok choy 1 minuto y sirva con cebollino."],"titulo":"Sopa de wonton de pollo","porciones":3},"en":{"ingredientes":["200 g ground chicken","20 wheat wonton wrappers","5 cups chicken broth","1 tsp grated ginger","1 garlic clove, minced","2 cups bok choy or spinach","1 scallion, chopped"],"pasos":["Mix the chicken with the ginger, garlic and salt.","Place a teaspoon of filling on each wrapper, moisten the edges and seal.","Bring the broth to a boil and cook the wontons for 5 minutes.","Add the bok choy for 1 minute and serve with scallion."],"titulo":"Chicken wonton soup","porciones":3}},"frittata-vegetales":{"es":{"ingredientes":["5 huevos","1 zucchini en cubos","1 tomate picado","1 taza de espinacas","1/4 de cebolla picada","1 cda de aceite de oliva","sal y pimienta al gusto"],"pasos":["Caliente el horno a 190 °C. Saltee la cebolla y el zucchini en una sartén apta para horno 5 minutos.","Agregue el tomate y las espinacas hasta que se marchiten.","Vierta los huevos batidos con sal y pimienta.","Hornee 12 a 15 minutos hasta que cuaje."],"titulo":"Frittata de vegetales","porciones":2},"en":{"ingredientes":["5 eggs","1 zucchini, diced","1 tomato, chopped","1 cup spinach","1/4 onion, chopped","1 tbsp olive oil","salt and pepper to taste"],"pasos":["Heat the oven to 190 °C. Sauté the onion and zucchini in an oven-safe pan for 5 minutes.","Add the tomato and spinach until wilted.","Pour in the eggs beaten with salt and pepper.","Bake 12 to 15 minutes until set."],"titulo":"Vegetable frittata","porciones":2}},"bruschetta-tomate":{"es":{"ingredientes":["6 rebanadas de pan rústico","4 tomates maduros picados","2 dientes de ajo","1/4 de taza de albahaca fresca","2 cdas de aceite de oliva","sal al gusto"],"pasos":["Tueste el pan en el horno o plancha.","Frote cada rebanada con ajo.","Mezcle el tomate con la albahaca, el aceite y la sal.","Sirva el tomate sobre el pan."],"titulo":"Bruschetta de tomate y albahaca","porciones":2},"en":{"ingredientes":["6 slices of rustic bread","4 ripe tomatoes, chopped","2 garlic cloves","1/4 cup fresh basil","2 tbsp olive oil","salt to taste"],"pasos":["Toast the bread in the oven or on a griddle.","Rub each slice with garlic.","Mix the tomato with the basil, oil and salt.","Spoon the tomato over the bread."],"titulo":"Tomato and basil bruschetta","porciones":2}},"ensalada-caprese":{"es":{"ingredientes":["3 tomates maduros en rodajas","200 g de queso mozzarella en rodajas","1/4 de taza de albahaca fresca","2 cdas de aceite de oliva","sal y pimienta al gusto"],"pasos":["Alterne rodajas de tomate y mozzarella en un plato.","Agregue las hojas de albahaca.","Aliñe con aceite, sal y pimienta."],"titulo":"Ensalada caprese","porciones":2},"en":{"ingredientes":["3 ripe tomatoes, sliced","200 g mozzarella, sliced","1/4 cup fresh basil","2 tbsp olive oil","salt and pepper to taste"],"pasos":["Alternate slices of tomato and mozzarella on a plate.","Tuck in the basil leaves.","Drizzle with oil, salt and pepper."],"titulo":"Caprese salad","porciones":2}},"polenta-hongos":{"es":{"ingredientes":["1 taza de polenta (maíz molido)","4 tazas de caldo de verduras","300 g de hongos en láminas","2 dientes de ajo picados","2 cdas de aceite de oliva","2 cdas de perejil picado","sal y pimienta al gusto"],"pasos":["Hierva el caldo y agregue la polenta en hilo revolviendo.","Cocine a fuego bajo 20 minutos, revolviendo.","Saltee los hongos y el ajo en aceite 8 minutos.","Sirva la polenta con los hongos y el perejil."],"titulo":"Polenta cremosa con hongos","porciones":2},"en":{"ingredientes":["1 cup polenta (cornmeal)","4 cups vegetable broth","300 g sliced mushrooms","2 garlic cloves, minced","2 tbsp olive oil","2 tbsp chopped parsley","salt and pepper to taste"],"pasos":["Bring the broth to a boil and whisk in the polenta in a thin stream.","Cook over low heat for 20 minutes, stirring.","Sauté the mushrooms and garlic in oil for 8 minutes.","Serve the polenta topped with the mushrooms and parsley."],"titulo":"Creamy polenta with mushrooms","porciones":2}},"sopa-pasta-fagioli":{"es":{"ingredientes":["1/2 taza de pasta pequeña","2 tazas de frijoles blancos cocidos","2 tomates picados","1 zanahoria en cubos","1 tallo de apio picado","1/2 cebolla picada","4 tazas de caldo de verduras","1 cda de aceite de oliva"],"pasos":["Sofría la cebolla, el apio y la zanahoria en aceite.","Agregue el tomate, los frijoles y el caldo; cocine 20 minutos.","Agregue la pasta y cocine 10 minutos.","Sazone con sal y pimienta."],"titulo":"Sopa de pasta y frijoles","porciones":4},"en":{"ingredientes":["1/2 cup small pasta","2 cups cooked white beans","2 tomatoes, chopped","1 carrot, diced","1 celery stalk, chopped","1/2 onion, chopped","4 cups vegetable broth","1 tbsp olive oil"],"pasos":["Sauté the onion, celery and carrot in oil.","Add the tomato, beans and broth; cook 20 minutes.","Add the pasta and cook 10 minutes.","Season with salt and pepper."],"titulo":"Pasta and bean soup","porciones":4}},"pasta-pomodoro":{"es":{"ingredientes":["200 g de pasta","5 tomates maduros picados","3 dientes de ajo picados","2 cdas de aceite de oliva","1/4 de taza de albahaca","1/4 de taza de queso parmesano rallado","sal al gusto"],"pasos":["Cocine la pasta en agua con sal y escúrrala.","Sofría el ajo en aceite; agregue el tomate y cocine 15 minutos.","Mezcle la salsa con la pasta y la albahaca.","Sirva con el parmesano."],"titulo":"Pasta pomodoro con parmesano","porciones":2},"en":{"ingredientes":["200 g pasta","5 ripe tomatoes, chopped","3 garlic cloves, minced","2 tbsp olive oil","1/4 cup basil","1/4 cup grated parmesan","salt to taste"],"pasos":["Cook the pasta in salted water and drain.","Sauté the garlic in oil; add the tomato and cook 15 minutes.","Toss the sauce with the pasta and basil.","Serve with the parmesan."],"titulo":"Pasta pomodoro with parmesan","porciones":2}},"gnocchi-tomate":{"es":{"ingredientes":["500 g de ñoquis de papa","4 tomates maduros picados","2 dientes de ajo picados","2 cdas de aceite de oliva","1/4 de taza de albahaca","1/4 de taza de queso parmesano rallado","sal al gusto"],"pasos":["Sofría el ajo en aceite; agregue el tomate y cocine 15 minutos.","Cocine los ñoquis en agua con sal hasta que floten, 2 a 3 minutos.","Mezcle los ñoquis con la salsa y la albahaca.","Sirva con parmesano."],"titulo":"Ñoquis de papa en salsa de tomate","porciones":3},"en":{"ingredientes":["500 g potato gnocchi","4 ripe tomatoes, chopped","2 garlic cloves, minced","2 tbsp olive oil","1/4 cup basil","1/4 cup grated parmesan","salt to taste"],"pasos":["Sauté the garlic in oil; add the tomato and cook 15 minutes.","Cook the gnocchi in salted water until they float, 2 to 3 minutes.","Toss the gnocchi with the sauce and basil.","Serve with parmesan."],"titulo":"Potato gnocchi in tomato sauce","porciones":3}},"pollo-cacciatora":{"es":{"ingredientes":["700 g de pollo en piezas","4 tomates picados","1 chile dulce en tiras","1 cebolla en tiras","3 dientes de ajo picados","1/2 taza de caldo de pollo","1 cda de orégano","2 cdas de aceite de oliva"],"pasos":["Dore el pollo en aceite con sal y apártelo.","Sofría la cebolla, el chile dulce y el ajo; agregue el tomate, el caldo y el orégano.","Regrese el pollo, tape y cocine a fuego bajo 40 minutos."],"titulo":"Pollo cacciatora","porciones":3},"en":{"ingredientes":["700 g chicken pieces","4 tomatoes, chopped","1 sweet pepper, sliced","1 onion, sliced","3 garlic cloves, minced","1/2 cup chicken broth","1 tbsp oregano","2 tbsp olive oil"],"pasos":["Brown the chicken in oil with salt and set aside.","Sauté the onion, sweet pepper and garlic; add the tomato, broth and oregano.","Return the chicken, cover and simmer for 40 minutes."],"titulo":"Chicken cacciatora","porciones":3}},"pescado-pomodoro-alcaparras":{"es":{"ingredientes":["2 filetes de pescado blanco (300 g)","4 tomates picados","2 cdas de alcaparras","8 aceitunas","2 dientes de ajo picados","2 cdas de aceite de oliva","2 cdas de perejil"],"pasos":["Sofría el ajo en aceite; agregue el tomate y cocine 10 minutos.","Agregue las alcaparras y las aceitunas.","Coloque el pescado con sal en la salsa, tape y cocine 10 minutos.","Sirva con perejil."],"titulo":"Pescado en salsa de tomate y alcaparras","porciones":2},"en":{"ingredientes":["2 white fish fillets (300 g)","4 tomatoes, chopped","2 tbsp capers","8 olives","2 garlic cloves, minced","2 tbsp olive oil","2 tbsp parsley"],"pasos":["Sauté the garlic in oil; add the tomato and cook 10 minutes.","Add the capers and olives.","Place the fish with salt in the sauce, cover and cook 10 minutes.","Serve with parsley."],"titulo":"Fish in tomato and caper sauce","porciones":2}},"berenjena-parmigiana":{"es":{"ingredientes":["2 berenjenas grandes en rodajas","2 tazas de salsa de tomate","1 1/2 tazas de queso mozzarella rallado","1/4 de taza de queso parmesano rallado","1/4 de taza de albahaca","3 cdas de aceite de oliva"],"pasos":["Caliente el horno a 200 °C. Pincele las berenjenas con aceite y sal y hornee 15 minutos.","En un molde ponga salsa, berenjena, mozzarella y albahaca en capas.","Termine con salsa y parmesano.","Hornee 30 minutos hasta que burbujee."],"titulo":"Berenjena a la parmesana","porciones":3},"en":{"ingredientes":["2 large eggplants, sliced","2 cups tomato sauce","1 1/2 cups grated mozzarella","1/4 cup grated parmesan","1/4 cup basil","3 tbsp olive oil"],"pasos":["Heat the oven to 200 °C. Brush the eggplant with oil and salt and bake 15 minutes.","In a dish layer sauce, eggplant, mozzarella and basil.","Finish with sauce and parmesan.","Bake 30 minutes until bubbling."],"titulo":"Eggplant parmigiana","porciones":3}},"ensalada-arroz-italiana":{"es":{"ingredientes":["1 1/2 tazas de arroz cocido y frío","2 tomates en cubos","1 pepino en cubos","1 chile dulce en cubos","10 aceitunas","1/2 taza de maíz","3 cdas de aceite de oliva","1 limón","1 cdta de orégano"],"pasos":["Mezcle el arroz con el tomate, el pepino, el chile dulce, las aceitunas y el maíz.","Aliñe con el aceite, el limón, el orégano y la sal.","Refrigere 15 minutos y sirva."],"titulo":"Ensalada de arroz italiana","porciones":3},"en":{"ingredientes":["1 1/2 cups cooked, cooled rice","2 tomatoes, diced","1 cucumber, diced","1 sweet pepper, diced","10 olives","1/2 cup corn","3 tbsp olive oil","1 lemon","1 tsp oregano"],"pasos":["Combine the rice with the tomato, cucumber, sweet pepper, olives and corn.","Dress with the oil, lemon, oregano and salt.","Chill 15 minutes and serve."],"titulo":"Italian rice salad","porciones":3}},"calabacin-relleno":{"es":{"ingredientes":["4 zucchinis medianos","1 taza de arroz cocido","2 tomates picados","1/4 de cebolla picada","1 diente de ajo picado","1 taza de queso mozzarella rallado","1 cda de aceite de oliva"],"pasos":["Caliente el horno a 190 °C. Corte los zucchinis por la mitad y vacíelos; pique la pulpa.","Sofría la cebolla, el ajo, la pulpa y el tomate 6 minutos; mezcle con el arroz.","Rellene los zucchinis y cubra con el queso.","Hornee 25 minutos."],"titulo":"Zucchini relleno gratinado","porciones":2},"en":{"ingredientes":["4 medium zucchinis","1 cup cooked rice","2 tomatoes, chopped","1/4 onion, chopped","1 garlic clove, minced","1 cup grated mozzarella","1 tbsp olive oil"],"pasos":["Heat the oven to 190 °C. Halve the zucchinis and scoop them out; chop the flesh.","Sauté the onion, garlic, flesh and tomato for 6 minutes; mix with the rice.","Fill the zucchinis and top with the cheese.","Bake for 25 minutes."],"titulo":"Stuffed zucchini au gratin","porciones":2}},"tostada-ricotta-fruta":{"es":{"ingredientes":["2 rebanadas de pan integral","1/2 taza de ricotta","1 durazno o 1/2 taza de fresas en láminas","1 cdta de miel","1 pizca de canela"],"pasos":["Tueste el pan.","Unte la ricotta sobre las tostadas.","Agregue la fruta, la miel y la canela."],"titulo":"Tostada con ricotta, fruta y miel","porciones":1},"en":{"ingredientes":["2 slices of whole-grain bread","1/2 cup ricotta","1 peach or 1/2 cup sliced strawberries","1 tsp honey","1 pinch of cinnamon"],"pasos":["Toast the bread.","Spread the ricotta on the toast.","Top with the fruit, honey and cinnamon."],"titulo":"Toast with ricotta, fruit and honey","porciones":1}},"pizza-integral-vegetales":{"es":{"ingredientes":["2 tazas de harina integral","3/4 de taza de agua tibia","1 cdta de levadura seca","1 cda de aceite de oliva","3/4 de taza de salsa de tomate","1 1/2 tazas de queso mozzarella rallado","1 chile dulce y 1 taza de hongos en láminas"],"pasos":["Mezcle la harina, la levadura, el agua, el aceite y sal; amase 8 minutos y deje reposar 30 minutos.","Caliente el horno a 230 °C. Extienda la masa en una bandeja.","Cubra con salsa, vegetales y queso.","Hornee 15 a 18 minutos."],"titulo":"Pizza integral de vegetales","porciones":3},"en":{"ingredientes":["2 cups whole-wheat flour","3/4 cup warm water","1 tsp dry yeast","1 tbsp olive oil","3/4 cup tomato sauce","1 1/2 cups grated mozzarella","1 sweet pepper and 1 cup sliced mushrooms"],"pasos":["Mix the flour, yeast, water, oil and salt; knead 8 minutes and rest 30 minutes.","Heat the oven to 230 °C. Roll out the dough on a tray.","Top with sauce, vegetables and cheese.","Bake 15 to 18 minutes."],"titulo":"Whole-wheat vegetable pizza","porciones":3}},"sopa-lentejas-espinaca-italiana":{"es":{"ingredientes":["1 taza de lentejas","2 tazas de espinacas","2 tomates picados","1 zanahoria en cubos","1/2 cebolla picada","2 dientes de ajo picados","5 tazas de caldo de verduras","1 cda de aceite de oliva"],"pasos":["Sofría la cebolla, la zanahoria y el ajo en aceite.","Agregue el tomate, las lentejas y el caldo; cocine 30 minutos.","Agregue la espinaca los últimos 3 minutos y sazone."],"titulo":"Sopa de lentejas y espinaca estilo italiano","porciones":4},"en":{"ingredientes":["1 cup lentils","2 cups spinach","2 tomatoes, chopped","1 carrot, diced","1/2 onion, chopped","2 garlic cloves, minced","5 cups vegetable broth","1 tbsp olive oil"],"pasos":["Sauté the onion, carrot and garlic in oil.","Add the tomato, lentils and broth; cook 30 minutes.","Add the spinach for the last 3 minutes and season."],"titulo":"Italian lentil and spinach soup","porciones":4}},"risotto-vegetales":{"es":{"ingredientes":["1 taza de arroz arborio","3 tazas de caldo de verduras caliente","1 zucchini en cubos","1/2 taza de arvejas","1 zanahoria en cubos pequeños","1/2 cebolla picada","2 cdas de aceite de oliva","sal y pimienta al gusto"],"pasos":["Sofría la cebolla y la zanahoria en aceite 4 minutos.","Agregue el arroz y revuelva 1 minuto.","Agregue el caldo de a poco, revolviendo, 15 minutos; incluya el zucchini y las arvejas a la mitad.","Sazone y sirva cremoso."],"titulo":"Risotto de vegetales","porciones":2},"en":{"ingredientes":["1 cup arborio rice","3 cups hot vegetable broth","1 zucchini, diced","1/2 cup peas","1 carrot, small-diced","1/2 onion, chopped","2 tbsp olive oil","salt and pepper to taste"],"pasos":["Sauté the onion and carrot in oil for 4 minutes.","Add the rice and stir for 1 minute.","Add the broth gradually, stirring, for 15 minutes; add the zucchini and peas halfway.","Season and serve creamy."],"titulo":"Vegetable risotto","porciones":2}},"tortellini-caldo-vegetal":{"es":{"ingredientes":["250 g de tortellini de queso","4 tazas de caldo de verduras","1 zanahoria en rodajas finas","1 tallo de apio picado","1 taza de espinacas","1 diente de ajo","2 cdas de perejil picado"],"pasos":["Hierva el caldo con el ajo, la zanahoria y el apio 8 minutos.","Agregue los tortellini y cocine según el paquete.","Agregue las espinacas 1 minuto y sirva con perejil."],"titulo":"Tortellini en caldo de vegetales","porciones":2},"en":{"ingredientes":["250 g cheese tortellini","4 cups vegetable broth","1 carrot, thinly sliced","1 celery stalk, chopped","1 cup spinach","1 garlic clove","2 tbsp chopped parsley"],"pasos":["Simmer the broth with the garlic, carrot and celery for 8 minutes.","Add the tortellini and cook as directed.","Add the spinach for 1 minute and serve with parsley."],"titulo":"Tortellini in vegetable broth","porciones":2}},"avena-coco-platano":{"es":{"ingredientes":["1/2 taza de avena en hojuelas","3/4 de taza de leche de coco","1 plátano maduro o banano en rodajas","2 cdas de coco rallado","1 pizca de canela"],"pasos":["Cocine la avena con la leche de coco 5 minutos.","Agregue el plátano y cocine 2 minutos más.","Sirva con el coco rallado y la canela."],"titulo":"Avena con coco y plátano","porciones":1},"en":{"ingredientes":["1/2 cup rolled oats","3/4 cup coconut milk","1 ripe plantain or banana, sliced","2 tbsp shredded coconut","1 pinch of cinnamon"],"pasos":["Cook the oats with the coconut milk for 5 minutes.","Add the plantain and cook 2 more minutes.","Serve with the shredded coconut and cinnamon."],"titulo":"Oatmeal with coconut and banana","porciones":1}},"tortilla-huevo-platano":{"es":{"ingredientes":["4 huevos","1 plátano maduro en cubos","1/4 de cebolla picada","2 cdas de culantro picado","1 cda de aceite","sal al gusto"],"pasos":["Fría el plátano en aceite hasta que dore; apártelo.","Bata los huevos con sal, la cebolla y el culantro.","Cocine en la sartén a fuego medio y agregue el plátano.","Doble la tortilla y sirva."],"titulo":"Tortilla de huevo con plátano maduro","porciones":2},"en":{"ingredientes":["4 eggs","1 ripe plantain, diced","1/4 onion, chopped","2 tbsp chopped culantro","1 tbsp oil","salt to taste"],"pasos":["Fry the plantain in oil until golden; set aside.","Beat the eggs with salt, onion and culantro.","Cook in the pan over medium heat and add the plantain.","Fold the omelet and serve."],"titulo":"Egg omelet with ripe plantain","porciones":2}},"batido-bowl-mango-coco":{"es":{"ingredientes":["1 mango maduro congelado","1 banano congelado","1/2 taza de leche de coco","1 cda de semillas de chía","2 cdas de coco rallado"],"pasos":["Licúe el mango, el banano y la leche de coco hasta obtener una mezcla espesa y lisa.","Sirva en un tazón.","Agregue la chía y el coco rallado."],"titulo":"Bowl de mango y coco","porciones":1},"en":{"ingredientes":["1 ripe frozen mango","1 frozen banana","1/2 cup coconut milk","1 tbsp chia seeds","2 tbsp shredded coconut"],"pasos":["Blend the mango, banana and coconut milk into a thick, smooth mixture.","Pour into a bowl.","Top with the chia and shredded coconut."],"titulo":"Mango and coconut bowl","porciones":1}},"moros-cristianos":{"es":{"ingredientes":["1 taza de arroz","1 taza de frijoles negros cocidos","1 1/2 tazas de caldo de los frijoles o agua","1/2 cebolla picada","1/2 chile dulce picado","3 dientes de ajo picados","1 cdta de comino","1 cda de aceite"],"pasos":["Sofría la cebolla, el chile dulce y el ajo en aceite con el comino.","Agregue el arroz y revuelva 1 minuto.","Agregue los frijoles, el caldo y sal; hierva.","Tape y cocine a fuego bajo 20 minutos."],"titulo":"Moros y cristianos","porciones":3},"en":{"ingredientes":["1 cup rice","1 cup cooked black beans","1 1/2 cups bean cooking liquid or water","1/2 onion, chopped","1/2 sweet pepper, chopped","3 garlic cloves, minced","1 tsp cumin","1 tbsp oil"],"pasos":["Sauté the onion, sweet pepper and garlic in oil with the cumin.","Add the rice and stir for 1 minute.","Add the beans, liquid and salt; bring to a boil.","Cover and cook over low heat for 20 minutes."],"titulo":"Moros y cristianos (rice and black beans)","porciones":3}},"tostones-ensalada":{"es":{"ingredientes":["2 plátanos verdes","1/2 taza de aceite","2 tomates en cubos","1 aguacate en cubos","2 tazas de lechuga","1 limón","sal al gusto"],"pasos":["Pele y corte los plátanos en rodajas gruesas; fríalos 3 minutos por lado.","Aplástelos, fríalos de nuevo hasta que doren y salpimiente.","Mezcle la lechuga, el tomate y el aguacate con limón y sal.","Sirva los tostones con la ensalada."],"titulo":"Tostones con ensalada fresca","porciones":2},"en":{"ingredientes":["2 green plantains","1/2 cup oil","2 tomatoes, diced","1 avocado, diced","2 cups lettuce","1 lime","salt to taste"],"pasos":["Peel and cut the plantains into thick slices; fry 3 minutes per side.","Flatten them, fry again until golden and salt.","Toss the lettuce, tomato and avocado with lime and salt.","Serve the tostones with the salad."],"titulo":"Tostones with fresh salad","porciones":2}},"pollo-guisado-caribeno":{"es":{"ingredientes":["700 g de pollo en piezas","2 tomates picados","1 cebolla en tiras","1 chile dulce en tiras","3 dientes de ajo picados","1 limón","1 cdta de orégano","1 taza de agua","2 cdas de aceite"],"pasos":["Sazone el pollo con sal, ajo, orégano y limón; deje reposar 15 minutos.","Dore el pollo en aceite y apártelo.","Sofría la cebolla y el chile dulce; agregue el tomate.","Regrese el pollo con el agua, tape y cocine 35 minutos."],"titulo":"Pollo guisado caribeño","porciones":3},"en":{"ingredientes":["700 g chicken pieces","2 tomatoes, chopped","1 onion, sliced","1 sweet pepper, sliced","3 garlic cloves, minced","1 lime","1 tsp oregano","1 cup water","2 tbsp oil"],"pasos":["Season the chicken with salt, garlic, oregano and lime; rest 15 minutes.","Brown the chicken in oil and set aside.","Sauté the onion and sweet pepper; add the tomato.","Return the chicken with the water, cover and simmer 35 minutes."],"titulo":"Caribbean stewed chicken","porciones":3}},"sopa-yuca-frijol":{"es":{"ingredientes":["400 g de yuca en cubos","1 taza de frijoles rojos cocidos","5 tazas de agua o caldo de verduras","1/2 cebolla picada","2 dientes de ajo picados","1 zanahoria en rodajas","2 cdas de culantro","1 cda de aceite"],"pasos":["Sofría la cebolla y el ajo en aceite.","Agregue la yuca, la zanahoria y el agua; cocine 25 minutos.","Agregue los frijoles y cocine 10 minutos más.","Sazone y sirva con culantro."],"titulo":"Sopa de yuca y frijoles","porciones":4},"en":{"ingredientes":["400 g cassava, cubed","1 cup cooked red beans","5 cups water or vegetable broth","1/2 onion, chopped","2 garlic cloves, minced","1 carrot, sliced","2 tbsp culantro","1 tbsp oil"],"pasos":["Sauté the onion and garlic in oil.","Add the cassava, carrot and water; cook 25 minutes.","Add the beans and cook 10 more minutes.","Season and serve with culantro."],"titulo":"Cassava and bean soup","porciones":4}},"pescado-criollo":{"es":{"ingredientes":["2 filetes de pescado (300 g)","2 tomates picados","1 cebolla en tiras","1 chile dulce en tiras","3 dientes de ajo picados","1 limón","2 cdas de aceite","2 cdas de culantro"],"pasos":["Sazone el pescado con sal, ajo y limón.","Sofría la cebolla y el chile dulce en aceite; agregue el tomate y cocine 8 minutos.","Coloque el pescado sobre la salsa, tape y cocine 10 minutos.","Sirva con culantro."],"titulo":"Pescado criollo","porciones":2},"en":{"ingredientes":["2 fish fillets (300 g)","2 tomatoes, chopped","1 onion, sliced","1 sweet pepper, sliced","3 garlic cloves, minced","1 lime","2 tbsp oil","2 tbsp culantro"],"pasos":["Season the fish with salt, garlic and lime.","Sauté the onion and sweet pepper in oil; add the tomato and cook 8 minutes.","Place the fish over the sauce, cover and cook 10 minutes.","Serve with culantro."],"titulo":"Creole-style fish","porciones":2}},"curry-garbanzos-papa-caribeno":{"es":{"ingredientes":["2 tazas de garbanzos cocidos","2 papas en cubos","1 cebolla picada","3 dientes de ajo picados","1 1/2 cdas de curry en polvo","1 taza de agua","1 cda de aceite","1 cebollino picado"],"pasos":["Sofría la cebolla y el ajo con el curry en aceite 3 minutos.","Agregue las papas y el agua; cocine tapado 12 minutos.","Agregue los garbanzos y cocine 10 minutos más.","Sirva con cebollino."],"titulo":"Curry caribeño de garbanzos y papa","porciones":3},"en":{"ingredientes":["2 cups cooked chickpeas","2 potatoes, cubed","1 onion, chopped","3 garlic cloves, minced","1 1/2 tbsp curry powder","1 cup water","1 tbsp oil","1 scallion, chopped"],"pasos":["Sauté the onion and garlic with the curry powder in oil for 3 minutes.","Add the potatoes and water; cook covered 12 minutes.","Add the chickpeas and cook 10 more minutes.","Serve with scallion."],"titulo":"Caribbean chickpea and potato curry","porciones":3}},"arroz-gandules":{"es":{"ingredientes":["1 taza de arroz","1 taza de gandules cocidos","1 1/2 tazas de agua o caldo de verduras","2 tomates picados","1/2 cebolla picada","1/2 chile dulce picado","3 dientes de ajo picados","2 cdas de culantro","1 cda de aceite"],"pasos":["Sofría la cebolla, el chile dulce y el ajo en aceite; agregue el tomate.","Agregue el arroz y mezcle 1 minuto.","Agregue los gandules, el caldo y sal; hierva.","Tape, cocine a fuego bajo 20 minutos y termine con culantro."],"titulo":"Arroz con gandules","porciones":3},"en":{"ingredientes":["1 cup rice","1 cup cooked pigeon peas","1 1/2 cups water or vegetable broth","2 tomatoes, chopped","1/2 onion, chopped","1/2 sweet pepper, chopped","3 garlic cloves, minced","2 tbsp culantro","1 tbsp oil"],"pasos":["Sauté the onion, sweet pepper and garlic in oil; add the tomato.","Add the rice and stir 1 minute.","Add the pigeon peas, broth and salt; bring to a boil.","Cover, cook over low heat 20 minutes and finish with culantro."],"titulo":"Rice with pigeon peas","porciones":3}},"ensalada-papaya-frijol":{"es":{"ingredientes":["2 tazas de papaya en cubos","1 taza de frijoles negros cocidos","1/2 cebolla morada picada","1 chile dulce picado","3 cdas de culantro picado","2 limones","1 cda de aceite de oliva"],"pasos":["Mezcle la papaya, los frijoles, la cebolla y el chile dulce.","Aliñe con limón, aceite y sal.","Agregue el culantro y sirva fresco."],"titulo":"Ensalada de papaya y frijoles","porciones":2},"en":{"ingredientes":["2 cups diced papaya","1 cup cooked black beans","1/2 red onion, chopped","1 sweet pepper, chopped","3 tbsp chopped culantro","2 limes","1 tbsp olive oil"],"pasos":["Combine the papaya, beans, onion and sweet pepper.","Dress with lime, oil and salt.","Add the culantro and serve chilled."],"titulo":"Papaya and bean salad","porciones":2}},"camarones-coco":{"es":{"ingredientes":["350 g de camarones pelados","1 taza de leche de coco","1/2 cebolla picada","2 dientes de ajo picados","1 tomate picado","1 cdta de jengibre rallado","1 limón","1 cda de aceite"],"pasos":["Sofría la cebolla, el ajo y el jengibre en aceite; agregue el tomate.","Agregue la leche de coco y cocine 8 minutos.","Agregue los camarones con sal y cocine 4 minutos.","Termine con limón."],"titulo":"Camarones al coco","porciones":2},"en":{"ingredientes":["350 g peeled shrimp","1 cup coconut milk","1/2 onion, chopped","2 garlic cloves, minced","1 tomato, chopped","1 tsp grated ginger","1 lime","1 tbsp oil"],"pasos":["Sauté the onion, garlic and ginger in oil; add the tomato.","Add the coconut milk and simmer 8 minutes.","Add the shrimp with salt and cook 4 minutes.","Finish with lime."],"titulo":"Coconut shrimp curry","porciones":2}},"sopa-pescado-coco":{"es":{"ingredientes":["400 g de pescado en trozos","1 1/2 tazas de leche de coco","2 tazas de agua","1 papa en cubos","1 zanahoria en rodajas","1/2 cebolla picada","2 dientes de ajo picados","2 cdas de culantro"],"pasos":["Sofría la cebolla y el ajo; agregue el agua, la papa y la zanahoria y cocine 15 minutos.","Agregue la leche de coco y hierva suave.","Agregue el pescado con sal y cocine 8 minutos.","Sirva con culantro."],"titulo":"Sopa de pescado con coco","porciones":3},"en":{"ingredientes":["400 g fish, in chunks","1 1/2 cups coconut milk","2 cups water","1 potato, cubed","1 carrot, sliced","1/2 onion, chopped","2 garlic cloves, minced","2 tbsp culantro"],"pasos":["Sauté the onion and garlic; add the water, potato and carrot and cook 15 minutes.","Add the coconut milk and bring to a gentle simmer.","Add the fish with salt and cook 8 minutes.","Serve with culantro."],"titulo":"Fish and coconut soup","porciones":3}},"yuca-guisada-tomate":{"es":{"ingredientes":["600 g de yuca en trozos","3 tomates picados","1 cebolla en tiras","1/2 chile dulce picado","3 dientes de ajo picados","1 taza de agua","2 cdas de aceite","2 cdas de culantro"],"pasos":["Cocine la yuca en agua con sal 15 minutos y escúrrala.","Sofría la cebolla, el chile dulce y el ajo en aceite; agregue el tomate.","Agregue la yuca y el agua; cocine tapado 15 minutos.","Termine con culantro."],"titulo":"Yuca guisada con tomate","porciones":3},"en":{"ingredientes":["600 g cassava, chunked","3 tomatoes, chopped","1 onion, sliced","1/2 sweet pepper, chopped","3 garlic cloves, minced","1 cup water","2 tbsp oil","2 tbsp culantro"],"pasos":["Boil the cassava in salted water for 15 minutes and drain.","Sauté the onion, sweet pepper and garlic in oil; add the tomato.","Add the cassava and water; cook covered 15 minutes.","Finish with culantro."],"titulo":"Stewed cassava with tomato","porciones":3}},"pimientos-rellenos-arroz":{"es":{"ingredientes":["4 chiles dulces grandes","1 1/2 tazas de arroz cocido","1 taza de frijoles negros cocidos","2 tomates picados","1/2 cebolla picada","2 dientes de ajo picados","1 cdta de comino","1 cda de aceite"],"pasos":["Caliente el horno a 190 °C. Corte la tapa de los chiles y retire las semillas.","Sofría la cebolla, el ajo y el comino; agregue el tomate, el arroz y los frijoles.","Rellene los chiles y colóquelos en un molde.","Hornee tapados 30 minutos."],"titulo":"Chiles dulces rellenos de arroz","porciones":3},"en":{"ingredientes":["4 large sweet peppers","1 1/2 cups cooked rice","1 cup cooked black beans","2 tomatoes, chopped","1/2 onion, chopped","2 garlic cloves, minced","1 tsp cumin","1 tbsp oil"],"pasos":["Heat the oven to 190 °C. Cut the tops off the peppers and remove the seeds.","Sauté the onion, garlic and cumin; add the tomato, rice and beans.","Fill the peppers and place in a dish.","Bake covered for 30 minutes."],"titulo":"Sweet peppers stuffed with rice","porciones":3}},"calabaza-guisada-coco":{"es":{"ingredientes":["500 g de calabaza o ayote en cubos","1 taza de leche de coco","1/2 cebolla picada","2 dientes de ajo picados","1 cdta de jengibre rallado","1 cebollino picado","1 cda de aceite"],"pasos":["Sofría la cebolla, el ajo y el jengibre en aceite.","Agregue la calabaza y la leche de coco con sal.","Tape y cocine a fuego bajo 20 minutos hasta que esté suave.","Sirva con cebollino."],"titulo":"Calabaza guisada con coco","porciones":3},"en":{"ingredientes":["500 g pumpkin or squash, cubed","1 cup coconut milk","1/2 onion, chopped","2 garlic cloves, minced","1 tsp grated ginger","1 scallion, chopped","1 tbsp oil"],"pasos":["Sauté the onion, garlic and ginger in oil.","Add the squash and coconut milk with salt.","Cover and cook over low heat for 20 minutes until tender.","Serve with scallion."],"titulo":"Squash stewed with coconut","porciones":3}},"res-guisada-name":{"es":{"ingredientes":["600 g de res en cubos","400 g de ñame en trozos","2 tomates picados","1 cebolla en tiras","1 chile dulce en tiras","3 dientes de ajo picados","3 tazas de agua","2 cdas de aceite"],"pasos":["Dore la carne en aceite con sal y apártela.","Sofría la cebolla, el chile dulce y el ajo; agregue el tomate.","Regrese la carne con el agua, tape y cocine 1 hora a fuego bajo.","Agregue el ñame y cocine 25 minutos más."],"titulo":"Res guisada con ñame","porciones":4},"en":{"ingredientes":["600 g beef, cubed","400 g yam, chunked","2 tomatoes, chopped","1 onion, sliced","1 sweet pepper, sliced","3 garlic cloves, minced","3 cups water","2 tbsp oil"],"pasos":["Brown the beef in oil with salt and set aside.","Sauté the onion, sweet pepper and garlic; add the tomato.","Return the beef with the water, cover and simmer for 1 hour.","Add the yam and cook 25 more minutes."],"titulo":"Beef stew with yam","porciones":4}},"pan-coco-aguacate":{"es":{"ingredientes":["2 rebanadas de pan integral","1 aguacate maduro","2 cdas de coco rallado","1/2 limón","1 pizca de pimienta","sal al gusto"],"pasos":["Tueste el pan y el coco rallado en una sartén seca 2 minutos.","Triture el aguacate con limón y sal.","Unte el aguacate sobre el pan y espolvoree el coco tostado."],"titulo":"Pan con aguacate y coco","porciones":1},"en":{"ingredientes":["2 slices of whole-grain bread","1 ripe avocado","2 tbsp shredded coconut","1/2 lemon","1 pinch of pepper","salt to taste"],"pasos":["Toast the bread and the shredded coconut in a dry pan for 2 minutes.","Mash the avocado with lemon and salt.","Spread the avocado on the bread and sprinkle with the toasted coconut."],"titulo":"Toast with avocado and coconut","porciones":1}},"ensalada-pina-pollo":{"es":{"ingredientes":["2 pechugas de pollo cocidas y deshebradas","1 taza de piña en cubos","3 tazas de lechuga","1/2 pepino en rodajas","1/4 de cebolla morada en tiras","2 cdas de aceite de oliva","1 limón"],"pasos":["Mezcle la lechuga, el pepino y la cebolla en un plato.","Agregue el pollo y la piña.","Aliñe con aceite, limón y sal."],"titulo":"Ensalada de piña y pollo","porciones":2},"en":{"ingredientes":["2 cooked, shredded chicken breasts","1 cup diced pineapple","3 cups lettuce","1/2 cucumber, sliced","1/4 red onion, sliced","2 tbsp olive oil","1 lime"],"pasos":["Combine the lettuce, cucumber and onion on a plate.","Add the chicken and pineapple.","Dress with oil, lime and salt."],"titulo":"Pineapple and chicken salad","porciones":2}},"poha-vegetales":{"es":{"ingredientes":["2 tazas de arroz aplastado (poha)","1/4 de taza de maní","1 papa pequeña en cubos","1/2 cebolla picada","1/2 taza de arvejas","1/2 cdta de cúrcuma","1 cda de aceite","1 limón"],"pasos":["Lave el arroz aplastado en un colador y déjelo escurrir.","Dore el maní en aceite y apártelo; sofría la cebolla y la papa con la cúrcuma 8 minutos.","Agregue las arvejas y el arroz aplastado con sal; mezcle 3 minutos.","Termine con limón y el maní."],"titulo":"Poha de vegetales con maní","porciones":2},"en":{"ingredientes":["2 cups flattened rice (poha)","1/4 cup peanuts","1 small potato, diced","1/2 onion, chopped","1/2 cup peas","1/2 tsp turmeric","1 tbsp oil","1 lemon"],"pasos":["Rinse the flattened rice in a strainer and let it drain.","Brown the peanuts in oil and set aside; sauté the onion and potato with the turmeric for 8 minutes.","Add the peas and flattened rice with salt; toss 3 minutes.","Finish with lemon and the peanuts."],"titulo":"Vegetable poha with peanuts","porciones":2}},"upma-vegetales":{"es":{"ingredientes":["1 taza de sémola de trigo","2 1/2 tazas de agua caliente","1 zanahoria en cubos pequeños","1/2 taza de arvejas","1/2 cebolla picada","1 cdta de jengibre rallado","1 cda de aceite","1 limón"],"pasos":["Tueste la sémola en una sartén seca 4 minutos y apártela.","Sofría la cebolla y el jengibre en aceite; agregue la zanahoria y las arvejas.","Agregue el agua con sal y hierva; vierta la sémola revolviendo.","Tape 3 minutos y termine con limón."],"titulo":"Upma de sémola con vegetales","porciones":2},"en":{"ingredientes":["1 cup wheat semolina","2 1/2 cups hot water","1 carrot, small-diced","1/2 cup peas","1/2 onion, chopped","1 tsp grated ginger","1 tbsp oil","1 lemon"],"pasos":["Dry-toast the semolina in a pan for 4 minutes and set aside.","Sauté the onion and ginger in oil; add the carrot and peas.","Add the water with salt and bring to a boil; pour in the semolina, stirring.","Cover 3 minutes and finish with lemon."],"titulo":"Vegetable semolina upma","porciones":2}},"chilla-garbanzo":{"es":{"ingredientes":["1 taza de harina de garbanzo","3/4 de taza de agua","1/4 de cebolla picada","1 tomate picado","2 cdas de culantro picado","1/2 cdta de cúrcuma","1 cda de aceite"],"pasos":["Mezcle la harina de garbanzo con el agua, la cúrcuma y sal hasta obtener una masa líquida.","Agregue la cebolla, el tomate y el culantro.","Cocine porciones en una sartén con aceite 2 a 3 minutos por lado."],"titulo":"Chilla de harina de garbanzo","porciones":2},"en":{"ingredientes":["1 cup besan (ground chickpeas)","3/4 cup water","1/4 onion, chopped","1 tomato, chopped","2 tbsp chopped culantro","1/2 tsp turmeric","1 tbsp oil"],"pasos":["Mix the besan with the water, turmeric and salt into a runny batter.","Stir in the onion, tomato and culantro.","Cook portions in an oiled pan 2 to 3 minutes per side."],"titulo":"Besan (chickpea) chilla","porciones":2}},"huevos-bhurji":{"es":{"ingredientes":["4 huevos","1 cebolla pequeña picada","1 tomate picado","1 cdta de jengibre rallado","1/2 cdta de cúrcuma","2 cdas de culantro","1 cda de aceite","4 rebanadas de pan"],"pasos":["Sofría la cebolla y el jengibre en aceite; agregue la cúrcuma y el tomate.","Agregue los huevos batidos con sal y revuelva hasta que cuajen.","Termine con culantro y sirva con el pan tostado."],"titulo":"Huevos bhurji con pan","porciones":2},"en":{"ingredientes":["4 eggs","1 small onion, chopped","1 tomato, chopped","1 tsp grated ginger","1/2 tsp turmeric","2 tbsp culantro","1 tbsp oil","4 slices of bread"],"pasos":["Sauté the onion and ginger in oil; add the turmeric and tomato.","Add the eggs beaten with salt and stir until set.","Finish with culantro and serve with toasted bread."],"titulo":"Bhurji-style scrambled eggs with bread","porciones":2}},"chana-masala":{"es":{"ingredientes":["2 tazas de garbanzos cocidos","2 tomates picados","1 cebolla picada","3 dientes de ajo picados","1 cda de jengibre rallado","2 cdtas de comino","1 cdta de paprika","1/2 cdta de cúrcuma","1 cda de aceite"],"pasos":["Sofría la cebolla, el ajo y el jengibre en aceite.","Agregue las especias y el tomate; cocine 8 minutos.","Agregue los garbanzos con 1/2 taza de agua y sal; cocine 15 minutos."],"titulo":"Chana masala (garbanzos especiados)","porciones":3},"en":{"ingredientes":["2 cups cooked chickpeas","2 tomatoes, chopped","1 onion, chopped","3 garlic cloves, minced","1 tbsp grated ginger","2 tsp cumin","1 tsp paprika","1/2 tsp turmeric","1 tbsp oil"],"pasos":["Sauté the onion, garlic and ginger in oil.","Add the spices and tomato; cook 8 minutes.","Add the chickpeas with 1/2 cup water and salt; cook 15 minutes."],"titulo":"Chana masala (spiced chickpeas)","porciones":3}},"aloo-gobi":{"es":{"ingredientes":["3 papas en cubos","1 coliflor pequeña en ramitos","1 cebolla picada","1 tomate picado","1 cdta de cúrcuma","1 cdta de comino","1 cdta de jengibre rallado","2 cdas de aceite"],"pasos":["Sofría la cebolla, el jengibre y el comino en aceite.","Agregue el tomate y la cúrcuma; cocine 3 minutos.","Agregue la papa y la coliflor con sal y 1/4 de taza de agua.","Tape y cocine a fuego bajo 20 minutos."],"titulo":"Aloo gobi (papa y coliflor)","porciones":3},"en":{"ingredientes":["3 potatoes, cubed","1 small cauliflower, in florets","1 onion, chopped","1 tomato, chopped","1 tsp turmeric","1 tsp cumin","1 tsp grated ginger","2 tbsp oil"],"pasos":["Sauté the onion, ginger and cumin in oil.","Add the tomato and turmeric; cook 3 minutes.","Add the potato and cauliflower with salt and 1/4 cup water.","Cover and cook over low heat for 20 minutes."],"titulo":"Aloo gobi (potato and cauliflower)","porciones":3}},"palak-tofu":{"es":{"ingredientes":["400 g de espinacas","250 g de tofu firme en cubos","1/2 cebolla picada","3 dientes de ajo","1 cdta de jengibre rallado","1 cdta de comino","1 cda de aceite","2 panes de harina (roti o chapati)"],"pasos":["Cocine las espinacas 3 minutos en agua hirviendo; escurra y licúe con el ajo.","Sofría la cebolla, el jengibre y el comino en aceite; agregue el puré de espinaca.","Agregue el tofu con sal y cocine 8 minutos.","Sirva con el pan caliente."],"titulo":"Palak tofu (espinacas con tofu)","porciones":2},"en":{"ingredientes":["400 g spinach","250 g firm tofu, cubed","1/2 onion, chopped","3 garlic cloves","1 tsp grated ginger","1 tsp cumin","1 tbsp oil","2 flatbreads (roti or chapati)"],"pasos":["Boil the spinach 3 minutes; drain and blend with the garlic.","Sauté the onion, ginger and cumin in oil; add the spinach purée.","Add the tofu with salt and cook 8 minutes.","Serve with warm flatbread."],"titulo":"Palak tofu (spinach with tofu)","porciones":2}},"sopa-lentejas-india-limon":{"es":{"ingredientes":["1 taza de lentejas rojas","4 tazas de agua","1 cebolla picada","2 dientes de ajo picados","1 cdta de jengibre rallado","1 cdta de cúrcuma","1 cdta de comino","1 limón","1 cda de aceite"],"pasos":["Sofría la cebolla, el ajo y el jengibre con las especias en aceite.","Agregue las lentejas lavadas y el agua; cocine 25 minutos.","Licúe un poco si desea una textura más cremosa.","Sazone con sal y jugo de limón."],"titulo":"Sopa india de lentejas y limón","porciones":3},"en":{"ingredientes":["1 cup red lentils","4 cups water","1 onion, chopped","2 garlic cloves, minced","1 tsp grated ginger","1 tsp turmeric","1 tsp cumin","1 lemon","1 tbsp oil"],"pasos":["Sauté the onion, garlic and ginger with the spices in oil.","Add the rinsed lentils and water; cook 25 minutes.","Blend lightly if you prefer a creamier texture.","Season with salt and lemon juice."],"titulo":"Indian lentil and lemon soup","porciones":3}},"khichdi":{"es":{"ingredientes":["1/2 taza de arroz","1/2 taza de lentejas amarillas o rojas","4 tazas de agua","1 zanahoria en cubos","1/2 taza de arvejas","1 cdta de cúrcuma","1 cdta de comino","1 cdta de jengibre rallado","1 cda de aceite"],"pasos":["Lave el arroz y las lentejas.","Caliente el aceite y tueste el comino y el jengibre 30 segundos.","Agregue el arroz, las lentejas, los vegetales, la cúrcuma, sal y el agua.","Cocine tapado a fuego bajo 30 minutos, hasta que quede suave y espeso."],"titulo":"Khichdi de arroz y lentejas","porciones":3},"en":{"ingredientes":["1/2 cup rice","1/2 cup yellow or red lentils","4 cups water","1 carrot, diced","1/2 cup peas","1 tsp turmeric","1 tsp cumin","1 tsp grated ginger","1 tbsp oil"],"pasos":["Rinse the rice and lentils.","Heat the oil and toast the cumin and ginger for 30 seconds.","Add the rice, lentils, vegetables, turmeric, salt and water.","Cook covered over low heat for 30 minutes until soft and thick."],"titulo":"Rice and lentil khichdi","porciones":3}},"pollo-curry-india":{"es":{"ingredientes":["600 g de pollo en trozos","2 cebollas picadas","3 tomates picados","4 dientes de ajo picados","1 cda de jengibre rallado","2 cdas de curry en polvo","1/2 taza de agua","2 cdas de aceite"],"pasos":["Sofría la cebolla, el ajo y el jengibre en aceite hasta que doren.","Agregue el curry y el tomate; cocine 8 minutos.","Agregue el pollo, sal y el agua; tape y cocine 30 minutos."],"titulo":"Pollo al curry estilo indio","porciones":3},"en":{"ingredientes":["600 g chicken pieces","2 onions, chopped","3 tomatoes, chopped","4 garlic cloves, minced","1 tbsp grated ginger","2 tbsp curry powder","1/2 cup water","2 tbsp oil"],"pasos":["Sauté the onion, garlic and ginger in oil until golden.","Add the curry powder and tomato; cook 8 minutes.","Add the chicken, salt and the water; cover and cook 30 minutes."],"titulo":"Indian-style chicken curry","porciones":3}},"pescado-curry-coco":{"es":{"ingredientes":["2 filetes de pescado firme (350 g)","1 taza de leche de coco","1 cebolla picada","2 tomates picados","3 dientes de ajo picados","1 cda de curry en polvo","1 cdta de jengibre rallado","1 cda de aceite"],"pasos":["Sofría la cebolla, el ajo y el jengibre en aceite; agregue el curry.","Agregue el tomate y la leche de coco; cocine 8 minutos.","Agregue el pescado con sal y cocine 8 minutos a fuego bajo."],"titulo":"Pescado al curry con coco","porciones":2},"en":{"ingredientes":["2 firm fish fillets (350 g)","1 cup coconut milk","1 onion, chopped","2 tomatoes, chopped","3 garlic cloves, minced","1 tbsp curry powder","1 tsp grated ginger","1 tbsp oil"],"pasos":["Sauté the onion, garlic and ginger in oil; add the curry powder.","Add the tomato and coconut milk; cook 8 minutes.","Add the fish with salt and cook 8 minutes over low heat."],"titulo":"Fish curry with coconut","porciones":2}},"baingan-bharta":{"es":{"ingredientes":["2 berenjenas grandes","1 cebolla picada","2 tomates picados","3 dientes de ajo picados","1 cdta de comino","1 cdta de cúrcuma","2 cdas de aceite","3 panes de harina (roti o chapati)"],"pasos":["Ase las berenjenas enteras hasta que la piel se queme y la pulpa esté suave, unos 25 minutos.","Pélelas y triture la pulpa.","Sofría la cebolla, el ajo y las especias en aceite; agregue el tomate y la berenjena.","Cocine 10 minutos y sirva con el pan caliente."],"titulo":"Baingan bharta (berenjena asada) con pan","porciones":3},"en":{"ingredientes":["2 large eggplants","1 onion, chopped","2 tomatoes, chopped","3 garlic cloves, minced","1 tsp cumin","1 tsp turmeric","2 tbsp oil","3 flatbreads (roti or chapati)"],"pasos":["Roast the whole eggplants until the skin chars and the flesh is soft, about 25 minutes.","Peel and mash the flesh.","Sauté the onion, garlic and spices in oil; add the tomato and eggplant.","Cook 10 minutes and serve with warm flatbread."],"titulo":"Baingan bharta (roasted eggplant) with bread","porciones":3}},"raita-pepino-arroz":{"es":{"ingredientes":["1 taza de arroz","1 taza de yogur natural","1 pepino rallado","1/2 cdta de comino tostado","2 cdas de menta o culantro picado","1 tomate en cubos","sal al gusto"],"pasos":["Cocine el arroz según el paquete.","Mezcle el yogur con el pepino, el comino, la menta y sal.","Sirva el arroz con la raita fría y el tomate."],"titulo":"Raita de pepino con arroz","porciones":2},"en":{"ingredientes":["1 cup rice","1 cup plain yogurt","1 cucumber, grated","1/2 tsp toasted cumin","2 tbsp chopped mint or culantro","1 tomato, diced","salt to taste"],"pasos":["Cook the rice as directed.","Mix the yogurt with the cucumber, cumin, mint and salt.","Serve the rice with the cold raita and tomato."],"titulo":"Cucumber raita with rice","porciones":2}},"rajma-frijoles-rojos":{"es":{"ingredientes":["2 tazas de frijoles rojos cocidos","2 tomates picados","1 cebolla picada","3 dientes de ajo picados","1 cda de jengibre rallado","1 cdta de comino","1 cdta de paprika","1 cda de aceite"],"pasos":["Sofría la cebolla, el ajo y el jengibre en aceite.","Agregue las especias y el tomate; cocine 8 minutos.","Agregue los frijoles con 1 taza de agua y sal; cocine 25 minutos a fuego bajo."],"titulo":"Rajma (frijoles rojos en salsa especiada)","porciones":3},"en":{"ingredientes":["2 cups cooked red beans","2 tomatoes, chopped","1 onion, chopped","3 garlic cloves, minced","1 tbsp grated ginger","1 tsp cumin","1 tsp paprika","1 tbsp oil"],"pasos":["Sauté the onion, garlic and ginger in oil.","Add the spices and tomato; cook 8 minutes.","Add the beans with 1 cup water and salt; simmer 25 minutes."],"titulo":"Rajma (red beans in spiced sauce)","porciones":3}},"tandoori-pollo-horno":{"es":{"ingredientes":["700 g de muslos de pollo","3/4 de taza de yogur natural","2 cdas de jugo de limón","4 dientes de ajo picados","1 cda de jengibre rallado","2 cdtas de paprika","1 cdta de comino","1 cdta de cúrcuma"],"pasos":["Mezcle el yogur con el limón, el ajo, el jengibre, las especias y sal.","Cubra el pollo con la marinada y refrigere al menos 2 horas.","Hornee a 220 °C por 35 a 40 minutos hasta que esté bien cocido y con la piel tostada."],"titulo":"Pollo tandoori al horno","porciones":3},"en":{"ingredientes":["700 g chicken thighs","3/4 cup plain yogurt","2 tbsp lemon juice","4 garlic cloves, minced","1 tbsp grated ginger","2 tsp paprika","1 tsp cumin","1 tsp turmeric"],"pasos":["Mix the yogurt with the lemon, garlic, ginger, spices and salt.","Coat the chicken in the marinade and refrigerate at least 2 hours.","Bake at 220 °C for 35 to 40 minutes until fully cooked and the skin is browned."],"titulo":"Oven-baked tandoori chicken","porciones":3}},"paneer-vegetales":{"es":{"ingredientes":["250 g de queso paneer en cubos","1 chile dulce en cubos","1 cebolla en gajos","2 tomates picados","2 dientes de ajo picados","1 cdta de curry en polvo","1 cda de aceite"],"pasos":["Dore el paneer en aceite y apártelo.","Sofría la cebolla, el chile dulce y el ajo; agregue el curry y el tomate.","Cocine 8 minutos, agregue el paneer con sal y cocine 3 minutos."],"titulo":"Paneer con vegetales","porciones":2},"en":{"ingredientes":["250 g paneer cheese, cubed","1 sweet pepper, cubed","1 onion, in wedges","2 tomatoes, chopped","2 garlic cloves, minced","1 tsp curry powder","1 tbsp oil"],"pasos":["Brown the paneer in oil and set aside.","Sauté the onion, sweet pepper and garlic; add the curry powder and tomato.","Cook 8 minutes, add the paneer with salt and cook 3 minutes."],"titulo":"Paneer with vegetables","porciones":2}},"sambar-vegetales":{"es":{"ingredientes":["1 taza de lentejas amarillas o rojas","5 tazas de agua","1 zanahoria en rodajas","1 papa en cubos","1 berenjena pequeña en cubos","2 tomates picados","1 cebolla picada","1 cda de curry en polvo","1 cda de aceite"],"pasos":["Cocine las lentejas en el agua con cúrcuma 20 minutos.","Sofría la cebolla con el curry en aceite; agregue el tomate.","Agregue los vegetales y el sofrito a las lentejas con sal.","Cocine 20 minutos hasta que los vegetales estén suaves."],"titulo":"Sambar de lentejas y vegetales","porciones":4},"en":{"ingredientes":["1 cup yellow or red lentils","5 cups water","1 carrot, sliced","1 potato, cubed","1 small eggplant, cubed","2 tomatoes, chopped","1 onion, chopped","1 tbsp curry powder","1 tbsp oil"],"pasos":["Cook the lentils in the water with turmeric for 20 minutes.","Sauté the onion with the curry powder in oil; add the tomato.","Add the vegetables and sauté to the lentils with salt.","Cook 20 minutes until the vegetables are tender."],"titulo":"Lentil and vegetable sambar","porciones":4}},"camote-especiado-horno":{"es":{"ingredientes":["3 camotes medianos en trozos","2 cdas de aceite","1 cdta de comino","1 cdta de paprika","1/2 cdta de cúrcuma","1 limón","2 cdas de culantro picado"],"pasos":["Caliente el horno a 210 °C. Mezcle el camote con el aceite, las especias y sal.","Hornee 30 a 35 minutos, volteando a la mitad.","Sirva con limón y culantro."],"titulo":"Camote especiado al horno","porciones":2},"en":{"ingredientes":["3 medium sweet potatoes, chunked","2 tbsp oil","1 tsp cumin","1 tsp paprika","1/2 tsp turmeric","1 lime","2 tbsp chopped culantro"],"pasos":["Heat the oven to 210 °C. Toss the sweet potato with the oil, spices and salt.","Roast 30 to 35 minutes, turning halfway.","Serve with lime and culantro."],"titulo":"Spiced baked sweet potato","porciones":2}},"ensalada-kachumber":{"es":{"ingredientes":["3 tomates en cubos","2 pepinos en cubos","1 cebolla morada picada","2 cdas de culantro picado","2 limones","1/2 cdta de comino","sal al gusto"],"pasos":["Mezcle el tomate, el pepino y la cebolla.","Agregue el culantro, el comino, el jugo de limón y sal.","Sirva de inmediato o refrigere 10 minutos."],"titulo":"Ensalada kachumber","porciones":2},"en":{"ingredientes":["3 tomatoes, diced","2 cucumbers, diced","1 red onion, chopped","2 tbsp chopped culantro","2 limes","1/2 tsp cumin","salt to taste"],"pasos":["Combine the tomato, cucumber and onion.","Add the culantro, cumin, lime juice and salt.","Serve right away or chill 10 minutes."],"titulo":"Kachumber salad","porciones":2}},"onigiri-vegetales":{"es":{"ingredientes":["2 tazas de arroz de grano corto cocido","2 hojas de alga nori","1/2 aguacate en cubos","1/2 pepino en tiras finas","1 zanahoria rallada","sal al gusto"],"pasos":["Moje las manos y espolvoree con sal.","Tome una porción de arroz, ponga un poco de aguacate, pepino y zanahoria en el centro.","Cierre y forme un triángulo o una bola.","Envuelva con una tira de nori."],"titulo":"Onigiri de vegetales","porciones":2},"en":{"ingredientes":["2 cups cooked short-grain rice","2 nori sheets","1/2 avocado, diced","1/2 cucumber, in thin strips","1 carrot, grated","salt to taste"],"pasos":["Wet your hands and sprinkle with salt.","Take a portion of rice and place a little avocado, cucumber and carrot in the center.","Close and shape into a triangle or ball.","Wrap with a strip of nori."],"titulo":"Vegetable onigiri","porciones":2}},"sopa-miso-tofu":{"es":{"ingredientes":["3 tazas de agua","2 cdas de miso","150 g de tofu en cubos","1 cdta de alga wakame seca","1 cebollino picado"],"pasos":["Caliente el agua sin dejar que hierva fuerte.","Agregue el wakame y el tofu y cocine 3 minutos.","Disuelva el miso en un poco de caldo y agréguelo a la olla fuera del fuego.","Sirva con cebollino."],"titulo":"Sopa de miso con tofu","porciones":2},"en":{"ingredientes":["3 cups water","2 tbsp miso","150 g tofu, cubed","1 tsp dried wakame","1 scallion, chopped"],"pasos":["Heat the water without letting it boil hard.","Add the wakame and tofu and cook 3 minutes.","Dissolve the miso in a little broth and add it to the pot off the heat.","Serve with scallion."],"titulo":"Miso soup with tofu","porciones":2}},"tamagoyaki":{"es":{"ingredientes":["4 huevos","2 cdas de agua","1 cdta de azúcar","1 pizca de sal","1 cebollino picado","1 cda de aceite"],"pasos":["Bata los huevos con el agua, el azúcar, la sal y el cebollino.","Vierta una capa fina en una sartén con aceite a fuego medio.","Cuando cuaje, enrolle hacia un lado y agregue otra capa.","Repita, deje reposar 2 minutos y corte en rodajas."],"titulo":"Tamagoyaki (tortilla japonesa enrollada)","porciones":2},"en":{"ingredientes":["4 eggs","2 tbsp water","1 tsp sugar","1 pinch of salt","1 scallion, chopped","1 tbsp oil"],"pasos":["Beat the eggs with the water, sugar, salt and scallion.","Pour a thin layer into an oiled pan over medium heat.","When set, roll to one side and add another layer.","Repeat, rest 2 minutes and slice."],"titulo":"Tamagoyaki (Japanese rolled omelet)","porciones":2}},"donburi-pollo-huevo":{"es":{"ingredientes":["2 tazas de arroz cocido","300 g de pechuga de pollo en trozos","3 huevos batidos","1 cebolla en tiras","2 cdas de salsa de soya","1 cdta de azúcar","1/2 taza de agua"],"pasos":["Hierva el agua con la salsa de soya y el azúcar; agregue la cebolla y el pollo y cocine 10 minutos.","Vierta los huevos batidos por encima y tape 2 minutos hasta que cuajen.","Sirva sobre el arroz caliente."],"titulo":"Donburi de pollo y huevo","porciones":2},"en":{"ingredientes":["2 cups cooked rice","300 g chicken breast, in pieces","3 beaten eggs","1 onion, sliced","2 tbsp soy sauce","1 tsp sugar","1/2 cup water"],"pasos":["Simmer the water with the soy sauce and sugar; add the onion and chicken and cook 10 minutes.","Pour the beaten eggs over the top and cover 2 minutes until set.","Serve over the hot rice."],"titulo":"Chicken and egg donburi","porciones":2}},"salmon-teriyaki-arroz":{"es":{"ingredientes":["2 filetes de salmón (300 g)","1 taza de arroz","3 cdas de salsa de soya","1 cda de azúcar","1 cdta de jengibre rallado","1 diente de ajo picado","1 cda de aceite"],"pasos":["Cocine el arroz según el paquete.","Mezcle la salsa de soya, el azúcar, el jengibre y el ajo.","Dore el salmón en aceite 3 minutos por lado.","Agregue la salsa y cocine 2 minutos hasta que espese; sirva con el arroz."],"titulo":"Salmón teriyaki con arroz","porciones":2},"en":{"ingredientes":["2 salmon fillets (300 g)","1 cup rice","3 tbsp soy sauce","1 tbsp sugar","1 tsp grated ginger","1 garlic clove, minced","1 tbsp oil"],"pasos":["Cook the rice as directed.","Mix the soy sauce, sugar, ginger and garlic.","Sear the salmon in oil for 3 minutes per side.","Add the sauce and cook 2 minutes until glazed; serve with the rice."],"titulo":"Teriyaki salmon with rice","porciones":2}},"ensalada-pepino-sunomono":{"es":{"ingredientes":["2 pepinos en rodajas muy finas","3 cdas de vinagre de arroz","1 cda de azúcar","1 cdta de sal","1 cdta de jengibre rallado","1 cdta de semillas de ajonjolí"],"pasos":["Sale el pepino, déjelo reposar 10 minutos y escúrralo.","Mezcle el vinagre, el azúcar y el jengibre.","Combine con el pepino y refrigere 10 minutos.","Sirva con el ajonjolí."],"titulo":"Ensalada de pepino sunomono","porciones":2},"en":{"ingredientes":["2 cucumbers, very thinly sliced","3 tbsp rice vinegar","1 tbsp sugar","1 tsp salt","1 tsp grated ginger","1 tsp sesame seeds"],"pasos":["Salt the cucumber, rest 10 minutes and squeeze dry.","Mix the vinegar, sugar and ginger.","Combine with the cucumber and chill 10 minutes.","Serve with the sesame seeds."],"titulo":"Sunomono cucumber salad","porciones":2}},"tofu-agedashi":{"es":{"ingredientes":["300 g de tofu firme en cubos","3 cdas de fécula de maíz","1/2 taza de aceite para freír","1 taza de caldo de verduras","1 cda de salsa de soya","1 cdta de jengibre rallado","1 cebollino picado"],"pasos":["Seque el tofu y pase los cubos por la fécula.","Fríalos en aceite caliente hasta que estén crujientes.","Caliente el caldo con la salsa de soya.","Sirva el tofu en el caldo con jengibre y cebollino."],"titulo":"Tofu agedashi","porciones":2},"en":{"ingredientes":["300 g firm tofu, cubed","3 tbsp cornstarch","1/2 cup frying oil","1 cup vegetable broth","1 tbsp soy sauce","1 tsp grated ginger","1 scallion, chopped"],"pasos":["Pat the tofu dry and dust the cubes with cornstarch.","Fry in hot oil until crisp.","Warm the broth with the soy sauce.","Serve the tofu in the broth with ginger and scallion."],"titulo":"Agedashi tofu","porciones":2}},"udon-vegetales":{"es":{"ingredientes":["2 porciones de fideos udon","4 tazas de caldo de verduras","1 zanahoria en rodajas finas","1 taza de hongos en láminas","2 tazas de espinacas","1 cdta de jengibre rallado","1 cebollino picado"],"pasos":["Hierva el caldo con el jengibre, la zanahoria y los hongos 8 minutos.","Cocine los fideos udon aparte según el paquete y escúrralos.","Agregue las espinacas al caldo 1 minuto.","Sirva los fideos con el caldo y el cebollino."],"titulo":"Udon con vegetales","porciones":2},"en":{"ingredientes":["2 portions udon noodles","4 cups vegetable broth","1 carrot, thinly sliced","1 cup sliced mushrooms","2 cups spinach","1 tsp grated ginger","1 scallion, chopped"],"pasos":["Simmer the broth with the ginger, carrot and mushrooms for 8 minutes.","Cook the udon noodles separately as directed and drain.","Add the spinach to the broth for 1 minute.","Serve the noodles with the broth and scallion."],"titulo":"Vegetable udon","porciones":2}},"okonomiyaki-vegetales":{"es":{"ingredientes":["1 taza de harina de trigo","3/4 de taza de agua","2 huevos","3 tazas de repollo en tiras finas","1 zanahoria rallada","2 cebollinos picados","1 cda de aceite"],"pasos":["Mezcle la harina, el agua, los huevos y sal hasta obtener una masa lisa.","Agregue el repollo, la zanahoria y el cebollino.","Cocine dos tortitas en una sartén con aceite, tapadas, 5 minutos por lado.","Sirva calientes, cortadas en cuñas."],"titulo":"Okonomiyaki de vegetales","porciones":2},"en":{"ingredientes":["1 cup wheat flour","3/4 cup water","2 eggs","3 cups finely shredded cabbage","1 carrot, grated","2 scallions, chopped","1 tbsp oil"],"pasos":["Mix the flour, water, eggs and salt into a smooth batter.","Fold in the cabbage, carrot and scallions.","Cook two pancakes in an oiled pan, covered, 5 minutes per side.","Serve hot, cut into wedges."],"titulo":"Vegetable okonomiyaki","porciones":2}},"gyoza-vegetales-vapor":{"es":{"ingredientes":["20 hojas de masa para gyoza (de trigo)","2 tazas de repollo picado fino","1 zanahoria rallada","1 taza de hongos picados","2 dientes de ajo picados","1 cdta de jengibre rallado","2 cdas de salsa de soya"],"pasos":["Mezcle los vegetales con el ajo, el jengibre y 1 cda de salsa de soya.","Ponga una cucharada de relleno en cada hoja, humedezca los bordes y selle.","Cocine al vapor 10 minutos.","Sirva con el resto de la salsa de soya."],"titulo":"Gyoza de vegetales al vapor","porciones":3},"en":{"ingredientes":["20 gyoza wrappers (wheat)","2 cups finely chopped cabbage","1 carrot, grated","1 cup chopped mushrooms","2 garlic cloves, minced","1 tsp grated ginger","2 tbsp soy sauce"],"pasos":["Mix the vegetables with the garlic, ginger and 1 tbsp soy sauce.","Place a spoonful of filling on each wrapper, moisten the edges and seal.","Steam for 10 minutes.","Serve with the remaining soy sauce."],"titulo":"Steamed vegetable gyoza","porciones":3}},"arroz-curry-japones":{"es":{"ingredientes":["1 1/2 tazas de arroz","2 papas en cubos","2 zanahorias en trozos","1 cebolla picada","2 cdas de curry en polvo","2 cdas de harina de trigo","3 tazas de caldo de verduras","1 cda de aceite"],"pasos":["Cocine el arroz según el paquete.","Sofría la cebolla en aceite; agregue la harina y el curry y revuelva 1 minuto.","Agregue el caldo, las papas y las zanahorias; cocine 25 minutos hasta que espese.","Sirva sobre el arroz."],"titulo":"Arroz con curry japonés","porciones":3},"en":{"ingredientes":["1 1/2 cups rice","2 potatoes, cubed","2 carrots, chunked","1 onion, chopped","2 tbsp curry powder","2 tbsp wheat flour","3 cups vegetable broth","1 tbsp oil"],"pasos":["Cook the rice as directed.","Sauté the onion in oil; add the flour and curry powder and stir 1 minute.","Add the broth, potatoes and carrots; cook 25 minutes until thickened.","Serve over the rice."],"titulo":"Japanese curry rice","porciones":3}},"sopa-pollo-jengibre-japonesa":{"es":{"ingredientes":["300 g de pechuga de pollo","5 tazas de agua","1 cda de jengibre en láminas","1 zanahoria en rodajas","1 taza de hongos en láminas","2 tazas de espinacas","1 cebollino picado"],"pasos":["Hierva el agua con el jengibre y el pollo 20 minutos; retire el pollo y deshébrelo.","Agregue la zanahoria y los hongos al caldo; cocine 8 minutos.","Regrese el pollo, agregue las espinacas y sazone con sal.","Sirva con cebollino."],"titulo":"Sopa de pollo con jengibre","porciones":3},"en":{"ingredientes":["300 g chicken breast","5 cups water","1 tbsp ginger, sliced","1 carrot, sliced","1 cup sliced mushrooms","2 cups spinach","1 scallion, chopped"],"pasos":["Simmer the water with the ginger and chicken for 20 minutes; remove and shred the chicken.","Add the carrot and mushrooms to the broth; cook 8 minutes.","Return the chicken, add the spinach and season with salt.","Serve with scallion."],"titulo":"Chicken ginger soup","porciones":3}},"ensalada-algas-wakame":{"es":{"ingredientes":["20 g de alga wakame seca","1 pepino en rodajas finas","2 cdas de vinagre de arroz","1 cdta de aceite de ajonjolí","1 cdta de semillas de ajonjolí","1 cdta de azúcar","1 cdta de jengibre rallado"],"pasos":["Remoje el wakame en agua fría 10 minutos y escúrralo.","Mezcle el vinagre, el aceite de ajonjolí, el azúcar y el jengibre.","Combine con el wakame y el pepino.","Espolvoree las semillas de ajonjolí."],"titulo":"Ensalada de algas wakame","porciones":2},"en":{"ingredientes":["20 g dried wakame","1 cucumber, thinly sliced","2 tbsp rice vinegar","1 tsp sesame oil","1 tsp sesame seeds","1 tsp sugar","1 tsp grated ginger"],"pasos":["Soak the wakame in cold water for 10 minutes and drain.","Mix the vinegar, sesame oil, sugar and ginger.","Toss with the wakame and cucumber.","Sprinkle with the sesame seeds."],"titulo":"Wakame seaweed salad","porciones":2}},"berenjena-miso":{"es":{"ingredientes":["2 berenjenas medianas","2 cdas de miso","1 cda de azúcar","1 cda de agua","1 cda de aceite","1 cdta de semillas de ajonjolí","1 cebollino picado"],"pasos":["Caliente el horno a 200 °C. Corte las berenjenas por la mitad y haga cortes en la pulpa.","Pincele con aceite y hornee 20 minutos.","Mezcle el miso con el azúcar y el agua; unte sobre las berenjenas y hornee 8 minutos.","Sirva con ajonjolí y cebollino."],"titulo":"Berenjena glaseada con miso","porciones":2},"en":{"ingredientes":["2 medium eggplants","2 tbsp miso","1 tbsp sugar","1 tbsp water","1 tbsp oil","1 tsp sesame seeds","1 scallion, chopped"],"pasos":["Heat the oven to 200 °C. Halve the eggplants and score the flesh.","Brush with oil and bake 20 minutes.","Mix the miso with the sugar and water; spread over the eggplants and bake 8 minutes.","Serve with sesame seeds and scallion."],"titulo":"Miso-glazed eggplant","porciones":2}},"atun-sellado-arroz":{"es":{"ingredientes":["2 filetes de atún fresco (300 g)","1 taza de arroz","1 pepino en rodajas","1/2 aguacate","1 cda de aceite","1 limón","1 cdta de jengibre rallado"],"pasos":["Cocine el arroz según el paquete.","Sazone el atún con sal y jengibre.","Cocine en una sartén muy caliente con aceite 3 a 4 minutos por lado, hasta que esté bien cocido.","Corte en rodajas y sirva con el arroz, el pepino, el aguacate y limón."],"titulo":"Atún sellado con arroz","porciones":2},"en":{"ingredientes":["2 fresh tuna steaks (300 g)","1 cup rice","1 cucumber, sliced","1/2 avocado","1 tbsp oil","1 lemon","1 tsp grated ginger"],"pasos":["Cook the rice as directed.","Season the tuna with salt and ginger.","Cook in a very hot pan with oil 3 to 4 minutes per side, until fully cooked.","Slice and serve with the rice, cucumber, avocado and lemon."],"titulo":"Seared tuna with rice","porciones":2}},"chawanmushi":{"es":{"ingredientes":["3 huevos","1 1/2 tazas de caldo de verduras","1/2 taza de hongos en láminas","1/2 zanahoria en cubos pequeños","1 cebollino picado","1 pizca de sal"],"pasos":["Bata suavemente los huevos con el caldo tibio y la sal; cuele la mezcla.","Reparta los hongos y la zanahoria en dos tazas aptas para vapor y vierta la mezcla.","Tape y cocine al vapor a fuego bajo 15 minutos.","Sirva con cebollino."],"titulo":"Chawanmushi (flan salado de huevo)","porciones":2},"en":{"ingredientes":["3 eggs","1 1/2 cups vegetable broth","1/2 cup sliced mushrooms","1/2 carrot, small-diced","1 scallion, chopped","1 pinch of salt"],"pasos":["Gently beat the eggs with the warm broth and salt; strain.","Divide the mushrooms and carrot into two steam-safe cups and pour in the mixture.","Cover and steam over low heat for 15 minutes.","Serve with scallion."],"titulo":"Chawanmushi (savory egg custard)","porciones":2}},"yasai-itame":{"es":{"ingredientes":["2 tazas de repollo en tiras","1 zanahoria en tiras","1 chile dulce en tiras","1 taza de brócoli","1 cebolla en tiras","2 dientes de ajo picados","1 cda de aceite","sal y pimienta al gusto"],"pasos":["Caliente el aceite a fuego alto y saltee el ajo y la cebolla 1 minuto.","Agregue la zanahoria y el brócoli, 3 minutos.","Agregue el repollo y el chile dulce, 2 minutos más.","Sazone con sal y pimienta."],"titulo":"Yasai itame (vegetales salteados)","porciones":2},"en":{"ingredientes":["2 cups shredded cabbage","1 carrot, in strips","1 sweet pepper, sliced","1 cup broccoli","1 onion, sliced","2 garlic cloves, minced","1 tbsp oil","salt and pepper to taste"],"pasos":["Heat the oil over high heat and stir-fry the garlic and onion 1 minute.","Add the carrot and broccoli, 3 minutes.","Add the cabbage and sweet pepper, 2 more minutes.","Season with salt and pepper."],"titulo":"Yasai itame (stir-fried vegetables)","porciones":2}},"temaki-vegetales":{"es":{"ingredientes":["1 1/2 tazas de arroz de grano corto cocido","4 hojas de alga nori","1/2 aguacate en tiras","1/2 pepino en tiras","1 zanahoria en tiras","1 taza de lechuga","1 cdta de vinagre de arroz"],"pasos":["Mezcle el arroz con el vinagre de arroz y una pizca de sal.","Corte las hojas de nori por la mitad.","Extienda arroz sobre un lado, coloque los vegetales en diagonal.","Enrolle en forma de cono y sirva de inmediato."],"titulo":"Temaki de vegetales","porciones":2},"en":{"ingredientes":["1 1/2 cups cooked short-grain rice","4 nori sheets","1/2 avocado, in strips","1/2 cucumber, in strips","1 carrot, in strips","1 cup lettuce","1 tsp rice vinegar"],"pasos":["Mix the rice with the rice vinegar and a pinch of salt.","Cut the nori sheets in half.","Spread rice on one side and place the vegetables diagonally.","Roll into a cone and serve immediately."],"titulo":"Vegetable temaki hand rolls","porciones":2}},"okayu-arroz-vegetales":{"es":{"ingredientes":["1/2 taza de arroz","4 tazas de agua","1 zanahoria rallada","1 taza de espinacas","1 cdta de jengibre rallado","1 cebollino picado","sal al gusto"],"pasos":["Lave el arroz y cocínelo con el agua y el jengibre a fuego bajo 35 minutos.","Agregue la zanahoria y las espinacas los últimos 5 minutos.","Sazone con sal y sirva con cebollino."],"titulo":"Okayu (arroz caldoso) con vegetales","porciones":2},"en":{"ingredientes":["1/2 cup rice","4 cups water","1 carrot, grated","1 cup spinach","1 tsp grated ginger","1 scallion, chopped","salt to taste"],"pasos":["Rinse the rice and cook with the water and ginger over low heat for 35 minutes.","Add the carrot and spinach for the last 5 minutes.","Season with salt and serve with scallion."],"titulo":"Okayu (rice porridge) with vegetables","porciones":2}},"pollo-yakitori-arroz":{"es":{"ingredientes":["400 g de muslos de pollo sin hueso en cubos","1 taza de arroz","3 cdas de salsa de soya","1 cda de azúcar","1 cdta de jengibre rallado","2 cebollinos en trozos","1 cdta de aceite"],"pasos":["Cocine el arroz según el paquete.","Hierva la salsa de soya con el azúcar y el jengibre 3 minutos hasta que espese un poco.","Ensarte el pollo y el cebollino en palillos y cocínelos a la plancha 10 a 12 minutos, pincelando con la salsa.","Sirva con el arroz."],"titulo":"Pollo yakitori con arroz","porciones":2},"en":{"ingredientes":["400 g boneless chicken thighs, cubed","1 cup rice","3 tbsp soy sauce","1 tbsp sugar","1 tsp grated ginger","2 scallions, in pieces","1 tsp oil"],"pasos":["Cook the rice as directed.","Simmer the soy sauce with the sugar and ginger for 3 minutes until slightly thickened.","Thread the chicken and scallion on skewers and grill 10 to 12 minutes, brushing with the sauce.","Serve with the rice."],"titulo":"Chicken yakitori with rice","porciones":2}}};
if (typeof module !== 'undefined') module.exports = RECETAS; else window.MPI_RECETAS = RECETAS;
